INSERT INTO `kategori` (`id`, `nama`, `icon`, `deskripsi`) VALUES
(1, 'Statistika Dasar', 'fa-chart-simple', 'Belajar mean, median, modus'),
(2, 'Pengenalan BPS', 'fa-building', 'Belajar tentang Badan Pusat Statistik'),
(3, 'Indikator Statistik', 'fa-chart-line', 'IPM, Inflasi, Kemiskinan, PDRB');
INSERT INTO `materi` (`id`, `kategori_id`, `judul`, `isi`, `durasi_menit`, `xp`, `urutan`) VALUES
(1, 1, 'Pengertian Statistika', 'Statistika adalah ilmu yang mempelajari cara mengumpulkan, mengolah, menyajikan, dan menganalisis data, sehingga data tersebut dapat memberikan informasi yang bermakna untuk pengambilan keputusan.', 10, 5, 0),
(2, 1, 'Mean, Median, dan Modus', '<b>Mean (rata-rata)</b> adalah jumlah seluruh data dibagi banyaknya data. Contoh: mean dari 2, 4, 6, 8, 10 adalah (2+4+6+8+10)/5 = 6.<br><br><b>Median</b> adalah nilai tengah data setelah diurutkan. Jika jumlah data ganjil, median adalah nilai tengah tunggal; jika genap, median adalah rata-rata dua nilai tengah.<br><br><b>Modus</b> adalah nilai yang paling sering muncul dalam sekumpulan data.', 15, 5, 1),
(3, 1, 'Grafik dan Tabel', 'Data dapat disajikan dalam berbagai bentuk agar mudah dipahami:<br><br><b>Diagram Batang</b> untuk membandingkan nilai antar kategori.<br><b>Diagram Garis</b> untuk menunjukkan tren/perkembangan data dari waktu ke waktu.<br><b>Diagram Lingkaran</b> untuk menunjukkan proporsi/persentase bagian terhadap keseluruhan.<br><b>Tabel Distribusi Frekuensi</b> untuk mengelompokkan data dan menunjukkan banyaknya kemunculan tiap kelompok.', 15, 5, 2),
(4, 2, 'Apa itu BPS?', 'Badan Pusat Statistik (BPS) adalah Lembaga Pemerintah Non Kementerian yang bertanggung jawab langsung kepada Presiden. BPS bertugas menyediakan data statistik dasar bagi pemerintah dan masyarakat.', 10, 5, 0),
(5, 2, 'Tugas dan Fungsi BPS', 'BPS berfungsi menyelenggarakan kegiatan statistik dasar, mengoordinasikan kegiatan statistik sektoral yang diselenggarakan instansi pemerintah, serta menyediakan data statistik yang digunakan lintas sektor. Dasar hukum penyelenggaraan statistik dan pembentukan BPS diatur dalam UU No. 16 Tahun 1997 tentang Statistik.', 15, 5, 1),
(6, 2, 'Sensus Penduduk', 'Sensus adalah kegiatan mengumpulkan data dari seluruh unit populasi. Sensus Penduduk dilaksanakan setiap 10 tahun sekali, pada tahun yang berakhiran angka 0 (misalnya 2020, 2030).', 12, 5, 2),
(7, 2, 'Sensus Pertanian', 'Sensus Pertanian dilaksanakan setiap 10 tahun sekali, pada tahun yang berakhiran angka 3 (misalnya 2013, 2023), untuk mendata seluruh unit usaha pertanian di Indonesia.', 12, 5, 3),
(8, 2, 'Sensus Ekonomi', 'Sensus Ekonomi dilaksanakan setiap 10 tahun sekali, pada tahun yang berakhiran angka 6 (misalnya 2016, 2026), untuk mendata seluruh unit usaha di luar sektor pertanian.', 12, 5, 4),
(9, 2, 'Survei BPS', 'Berbeda dengan sensus yang mencakup seluruh populasi, survei hanya menggunakan sebagian data (sampel) untuk mewakili populasi. Contoh survei rutin BPS: <b>Susenas</b> (Survei Sosial Ekonomi Nasional) untuk kondisi sosial ekonomi rumah tangga, dan <b>Sakernas</b> (Survei Angkatan Kerja Nasional) untuk kondisi ketenagakerjaan.', 10, 5, 5),
(10, 3, 'Indeks Pembangunan Manusia (IPM)', 'IPM mengukur capaian pembangunan manusia suatu wilayah berdasarkan tiga dimensi dasar: kesehatan (umur panjang dan hidup sehat), pendidikan (pengetahuan), dan standar hidup layak (ekonomi). Semakin tinggi nilai IPM, semakin tinggi kualitas pembangunan manusia di wilayah tersebut.', 15, 5, 0),
(11, 3, 'Produk Domestik Regional Bruto (PDRB)', 'PDRB mengukur nilai tambah ekonomi suatu wilayah dan mencerminkan kinerja/pertumbuhan ekonominya. PDRB atas dasar harga konstan digunakan untuk melihat pertumbuhan ekonomi riil tanpa pengaruh inflasi.', 15, 5, 1),
(12, 3, 'Tingkat Pengangguran', 'Tingkat Pengangguran Terbuka (TPT) menunjukkan persentase angkatan kerja yang tidak memiliki pekerjaan/sedang mencari pekerjaan, diukur melalui Sakernas.', 12, 5, 2),
(13, 3, 'Kemiskinan', 'Tingkat kemiskinan menunjukkan persentase penduduk yang berada di bawah garis kemiskinan. Garis kemiskinan versi BPS ditentukan berdasarkan nilai pengeluaran minimum untuk memenuhi kebutuhan dasar makanan dan non-makanan.', 12, 5, 3),
(14, 3, 'Inflasi', 'Inflasi adalah kenaikan harga barang dan jasa secara umum dan terus-menerus. Inflasi di Indonesia umumnya diukur menggunakan perubahan Indeks Harga Konsumen (IHK) dari waktu ke waktu.', 12, 5, 4),
(16, 1, 'Ukuran Penyebaran Data: Jangkauan, Kuartil, dan Titik Tengah Kelas', '<b>Jangkauan (Range)</b> adalah ukuran penyebaran data paling sederhana, dihitung dengan rumus Nilai Maksimum dikurangi Nilai Minimum. Jika seluruh data bernilai sama, jangkauannya adalah 0.<br><br><b>Kuartil</b> membagi data yang sudah diurutkan menjadi 4 bagian sama banyak: Kuartil Bawah (Q1), Kuartil Tengah (Q2, sama dengan Median), dan Kuartil Atas (Q3).<br><br><b>Jangkauan Antarkuartil (Hamparan)</b> dihitung dengan rumus H = Q3 - Q1. Caranya: urutkan data, bagi menjadi kelompok bawah dan kelompok atas, lalu cari nilai tengah masing-masing kelompok untuk mendapatkan Q1 dan Q3.<br><br><b>Titik Tengah Kelas Interval</b> pada tabel distribusi frekuensi kelompok dihitung dengan rumus (Batas Bawah + Batas Atas) &divide; 2.', 15, 5, 3),
(17, 1, 'Statistika Lanjutan: Rata-rata Gabungan, Varians, dan Kemiringan Data', '<b>Rata-rata Gabungan</b> dari dua kelompok data dihitung dengan rumus: (n1 &times; mean1 + n2 &times; mean2) &divide; (n1 + n2).<br><br>Jika seluruh data dalam suatu kelompok dikurangi atau ditambah dengan bilangan konstan, <b>Mean</b> akan bergeser sebesar konstanta tersebut, tetapi <b>Varians (Ragam)</b> tidak berubah karena jarak/sebaran antar data tetap sama.<br><br><b>Distribusi menjulur kanan (Positively Skewed)</b> memiliki urutan Mean &gt; Median &gt; Modus.<br><br><b>Koefisien Korelasi (r)</b> bernilai antara -1 sampai +1. Tandanya menunjukkan arah hubungan (positif/negatif), sedangkan nilai mutlaknya menunjukkan kekuatan hubungan &mdash; semakin dekat ke 1, semakin kuat hubungannya.', 15, 5, 4),
(18, 1, 'Populasi, Sampel, dan Metode Sampling', '<b>Populasi</b> adalah keseluruhan objek yang menjadi target penelitian, sedangkan <b>Sampel</b> adalah sebagian kecil dari populasi yang diambil untuk mewakili keseluruhan.<br><br><b>Sensus</b> adalah kegiatan mendata seluruh anggota populasi tanpa terkecuali, dan hasilnya disebut <b>parameter</b>.<br><br><b>Sampling error</b> adalah selisih hasil akibat hanya mengamati sebagian populasi (sampel), bukan keseluruhan. Kesalahan ini tidak bisa dihindari sepenuhnya, tapi bisa diperkecil dengan memperbesar atau merepresentatifkan sampel.<br><br><b>Stratified Random Sampling</b> adalah teknik membagi populasi yang heterogen menjadi beberapa strata (lapisan) yang lebih homogen di dalamnya, untuk meningkatkan presisi estimasi.', 12, 5, 5),
(19, 1, 'Jenis Data dan Skala Pengukuran', '<b>Data Primer</b> dikumpulkan langsung dari objek yang diteliti (wawancara, kuesioner, observasi, eksperimen), sedangkan <b>Data Sekunder</b> diambil dari dokumen atau sumber pihak lain yang sudah diolah, misalnya data dari website BPS.<br><br><b>Data Kualitatif</b> berupa kategori atau kata-kata (bukan angka), misalnya jenis pekerjaan. <b>Data Kontinu</b> adalah hasil pengukuran yang bisa berupa desimal, misalnya berat badan.<br><br>Empat <b>skala pengukuran</b> data: <b>Nominal</b> (kategori/label tanpa urutan, misalnya jenis kelamin), <b>Ordinal</b> (kategori bertingkat/berurutan, misalnya jenjang pendidikan), <b>Interval</b> (tidak punya nilai nol mutlak, misalnya suhu Celsius), dan <b>Rasio</b> (punya nilai nol mutlak).', 15, 5, 6),
(20, 1, 'Aritmetika Sosial: Untung, Rugi, dan Persentase', '<b>Persentase Untung</b> dihitung dengan rumus: (Keuntungan &divide; Harga Beli) &times; 100%, di mana Keuntungan = Harga Jual - Harga Beli.<br><br>Untuk mencari <b>jumlah objek dari sebuah persentase</b>, gunakan rumus: Persentase &times; Total Populasi/Sampel.<br><br>Perhitungan <b>bunga</b> yang belum genap satu tahun perlu di-prorata (disesuaikan) dulu sesuai jangka waktunya sebelum dibandingkan.', 12, 5, 7),
(21, 1, 'Operasi Hitung Campuran dan Pola Bilangan', 'Aturan <b>KABATAKU</b> (Kali, Bagi, Tambah, Kurang) adalah urutan pengerjaan operasi hitung campuran: operasi dalam tanda kurung dikerjakan lebih dulu, lalu perkalian/pembagian, baru penjumlahan/pengurangan.<br><br><b>Pola bilangan (deret angka)</b> bisa berbentuk dua operasi berselang-seling (misalnya kali 2 lalu kurang 2 berulang), berbasis bilangan berpangkat, atau penambahan konstan yang nilainya terus meningkat setiap langkah.', 12, 5, 8),
(22, 1, 'Perbandingan Senilai, Berbalik Nilai, dan Soal Cerita', '<b>Perbandingan Senilai</b>: jika satu nilai naik, nilai lainnya juga ikut naik. Rumus: X1/Y1 = X2/Y2.<br><br><b>Perbandingan Berbalik Nilai</b>: jika satu nilai naik, nilai lainnya justru turun (misalnya makin banyak pekerja, makin sedikit waktu yang dibutuhkan). Rumus: X1 &times; Y1 = X2 &times; Y2.<br><br>Untuk soal <b>rasio bagian dari total</b>, gunakan rumus: Bagian = (Rasio Bagian &divide; Total Rasio) &times; Total. Untuk soal jarak-kecepatan-waktu, gunakan rumus: Waktu = Jarak &divide; Kecepatan.', 15, 5, 9),
(23, 1, 'Peluang, Kombinatorika, dan Himpunan', '<b>Peluang</b> suatu kejadian dihitung dengan rumus: Jumlah kejadian target &divide; Total ruang sampel. Peluang kejadian yang mustahil terjadi bernilai 0.<br><br><b>Nilai Harapan</b> dihitung dengan rumus: E(X) = n &times; P(A), di mana n adalah banyaknya percobaan.<br><br><b>Kombinasi</b> dipakai ketika urutan pemilihan tidak diperhatikan, sedangkan <b>Aturan Perkalian (Kaidah Pencacahan)</b> menghitung total variasi dengan mengalikan jumlah pilihan tiap kelompok.<br><br>Pada soal <b>Himpunan</b>, gunakan prinsip inclusion-exclusion: Total = (hanya A) + (hanya B) + (A dan B) + (bukan keduanya).', 15, 5, 10),
(24, 1, 'Logika Matematika', '<b>Modus Tollens</b>: jika pernyataan \"p maka r\" benar, dan ternyata r terbukti salah, maka p juga pasti salah.<br><br><b>Silogisme Disjungtif</b>: dari pernyataan \"A atau B\" dan fakta bahwa B salah, dapat disimpulkan bahwa A benar.<br><br>Soal <b>deduksi logis</b> (misalnya menentukan urutan/posisi) diselesaikan dengan menggabungkan semua petunjuk yang diberikan satu per satu secara sistematis.', 12, 5, 11),
(25, 2, 'Istilah, Prosedur Lapangan, dan Kendali Mutu Data', '<b>PML (Petugas Pemeriksa/Pengawas Lapangan)</b> bertugas mengawasi pengumpulan data dan memeriksa (editing/coding) kualitas isian kuesioner dari PCL sebelum diserahkan ke kecamatan/kabupaten.<br><br><b>Responden</b> adalah individu, kepala keluarga/rumah tangga, kelompok, atau lembaga/perusahaan yang memberi data kepada petugas lapangan. <b>Data Primer</b> didapat langsung lewat wawancara tatap muka, menggunakan <b>Kuesioner</b> sebagai instrumen daftar pertanyaan terstruktur agar data seragam dan standar.<br><br>Jika seluruh anggota rumah tangga sedang bepergian, petugas bisa melakukan <b>Proxy Interview</b> (menggali info lewat tetangga/pengurus RT). Jika terjadi penolakan keras (hard refusal), tindakan pertama adalah melapor ke PML/Ketua RT untuk pendekatan ulang secara persuasif &mdash; bukan memaksa.<br><br><b>Spotcheck</b> adalah pemeriksaan acak lapangan oleh PML untuk memastikan validitas data. <b>Editing</b> memeriksa kelengkapan dan konsistensi logis isian, sedangkan <b>Coding</b> mengubah jawaban teks menjadi kode angka baku BPS.', 15, 5, 6),
(26, 2, 'Metode Pengumpulan Data Digital Modern (PAPI, CAPI, CAWI)', '<b>PAPI (Paper and Pencil Interviewing)</b> adalah metode wawancara tatap muka konvensional dengan kuesioner kertas.<br><br><b>CAPI (Computer Assisted Personal Interviewing)</b> adalah wawancara tatap muka dengan input langsung ke gawai &mdash; lebih unggul dari PAPI karena data masuk real-time ke server dengan validasi otomatis, tanpa perlu scanning atau entri ulang.<br><br><b>CAWI (Computer Assisted Web Interviewing)</b> memungkinkan responden mengisi kuesioner mandiri secara daring tanpa kehadiran petugas, misalnya pada Sensus Penduduk Online. Keamanannya wajib menggunakan protokol HTTPS.<br><br><b>Consistency Check/Skip Logic</b> mencegah kesalahan entri akibat jawaban tidak logis dan otomatis melompati blok pertanyaan yang tidak relevan. <b>Geotagging</b> mengunci koordinat GPS lokasi wawancara untuk mencegah data fiktif.<br><br>Metode <b>KSA (Kerangka Sampel Area)</b> memakai citra satelit untuk mendata luas panen pertanian, sedangkan SP2020 memakai Metode Kombinasi dengan data Administrasi Kependudukan Dukcapil sebagai prelist awal.', 15, 5, 7),
(27, 2, 'Wilayah Kerja Statistik dan Unit Sensus', '<b>Blok Sensus (BS)</b> adalah wilayah kerja statistik terkecil, dibentuk dari batas alam/buatan yang jelas, dan biasanya memuat sekitar 80&ndash;120 rumah tangga.<br><br><b>Kode wilayah BPS</b> tersusun berjenjang: 2 digit provinsi, 2 digit kabupaten/kota, 3 digit kecamatan, dan 3 digit desa/kelurahan.<br><br>Jika muatan sebuah Blok Sensus melonjak melebihi standar, tim pemetaan melakukan <b>Splitting</b> menjadi BS baru dengan batas yang jelas.<br><br><b>Rumah Tangga Khusus</b> adalah kelompok orang yang diurus yayasan/lembaga, misalnya panti asuhan, barak militer, lapas, atau asrama/indekos berisi 10 orang atau lebih.<br><br>Konsep <b>De Jure</b> mencatat penduduk berdasarkan tempat tinggal resmi (KTP/domisili) &mdash; orang yang bepergian sementara tetap dicatat di tempat asalnya.', 12, 5, 8),
(28, 2, 'Kode Etik, Kerahasiaan Data, dan Sanksi Hukum Statistik', 'Kerahasiaan data responden dijamin oleh <b>UU No. 16 Tahun 1997</b>. Menurut <b>Pasal 21</b>, penyelenggara statistik wajib merahasiakan data individu responden dan tidak boleh mempublikasikannya ke pihak lain atau menjadikannya alat bukti pengadilan &mdash; karena itu BPS melakukan anonimisasi data mikro sebelum dibagikan ke peneliti.<br><br><b>Pasal 37</b> mengatur bahwa membocorkan data individu responden dapat dikenai pidana kurungan maksimal 1 tahun 6 bulan dan/atau denda maksimal Rp15 juta.<br><br>Menolak gratifikasi (uang/bingkisan) dari responden mencerminkan nilai <b>Akuntabel</b> dalam Core Values BerAKHLAK ASN.<br><br><b>Fabrikasi data</b> (mengarang atau menyalin data tanpa mendatangi responden) adalah pelanggaran kode etik terberat petugas lapangan, dan dapat berujung pemutusan kontrak serta sanksi hukum.', 15, 5, 9),
(29, 2, 'Klasifikasi Baku Statistik dan Cakupan Sensus Ekonomi/Pertanian', '<b>KBLI (Klasifikasi Baku Lapangan Usaha Indonesia)</b> adalah sistem pengodean resmi BPS untuk mengelompokkan aktivitas ekonomi/bisnis, dan menjadi acuan nasional termasuk perizinan usaha di OSS.<br><br><b>KBJI (Klasifikasi Baku Jabatan Indonesia)</b>, merujuk standar internasional ISCO, dipakai untuk mengelompokkan jabatan/pekerjaan berdasarkan jenis tugas dan tingkat keahlian.<br><br><b>Sensus Pertanian</b> mencakup tiga unit pencacahan: Usaha Pertanian Perorangan (UTP), Usaha Perusahaan Pertanian Berbadan Hukum (UPB), dan Usaha Pertanian Lainnya (UTL, misalnya pondok pesantren/kelompok tani).<br><br><b>Sensus Ekonomi</b> mencakup seluruh usaha/perusahaan di luar sektor pertanian, baik skala besar maupun UMKM, formal maupun informal.', 12, 5, 10),
(30, 2, 'Jenis Statistik (Dasar, Sektoral, Khusus) dan Peran BPS', 'Berdasarkan <b>UU No. 16 Tahun 1997 Pasal 5</b>, statistik dibagi menjadi tiga jenis: <b>Statistik Dasar</b> (lintas sektoral, skala nasional, diselenggarakan BPS), <b>Statistik Sektoral</b> (untuk kebutuhan instansi pemerintah tertentu, misalnya data luas sawah oleh Kementerian Pertanian), dan <b>Statistik Khusus</b> (untuk kebutuhan spesifik, diselenggarakan swasta/organisasi/universitas/perorangan, misalnya survei elektabilitas politik).<br><br>BPS bertanggung jawab penuh atas Statistik Dasar, dan bertindak sebagai <b>pembina</b> (memberi bimbingan, standar metodologi, dan rekomendasi) untuk Statistik Sektoral.<br><br>Instansi penyelenggara statistik sektoral wajib berkonsultasi dengan BPS sebelum kegiatan lapangan dan menyerahkan hasilnya ke BPS, guna menghindari duplikasi data.', 12, 5, 11),
(31, 2, 'Satu Data Indonesia (SDI) dan Tata Kelola Data', '<b>Perpres No. 39 Tahun 2019</b> adalah payung hukum Satu Data Indonesia (SDI) yang memberi mandat kepada BPS sebagai Pembina Data Statistik tingkat pusat.<br><br>Empat <b>Pilar Prinsip SDI</b>: Standar Data, Metadata, Interoperabilitas Data, dan Kode Referensi/Data Induk. <b>Interoperabilitas</b> berarti data bisa dibagikan/diakses antar sistem elektronik berbeda tanpa hambatan teknis.<br><br><b>Metadata</b> adalah &quot;data tentang data&quot; &mdash; informasi terstruktur soal definisi, latar belakang, cakupan, dan metodologi suatu data agar tidak salah tafsir. <b>Walidata</b> adalah unit kerja instansi yang mengumpulkan, memeriksa, mengelola, dan menyebarluaskan data dari Produsen Data.<br><br><b>EPSS (Evaluasi Penyelenggaraan Statistik Sektoral)</b> menilai kematangan instansi lewat 5 domain: Prinsip SDI, Kualitas Data, Proses Bisnis Statistik, Kelembagaan, dan Statistik Nasional.', 15, 5, 12),
(32, 2, 'Metodologi Sampling dan Survei Lanjutan (Susenas & Sakernas)', '<b>Stratified Random Sampling</b> dipakai pada survei besar dengan membagi wilayah menjadi strata (misalnya provinsi/kabupaten) agar populasi yang heterogen tetap terwakili.<br><br><b>Susenas</b> memakai Two-Stage Sampling: tahap pertama memilih Blok Sensus dari Master Sampling Frame, tahap kedua memilih rumah tangga secara acak dari hasil listing (pendataan awal bangunan/rumah tangga) di Blok Sensus terpilih.<br><br>Periode acuan (recall period) Susenas Modul Konsumsi untuk makanan/minuman/rokok adalah <b>7 hari terakhir</b>. Definisi &quot;seminggu yang lalu&quot; pada data ketenagakerjaan mengikuti standar ILO, yaitu 7 hari berturut-turut yang berakhir sehari sebelum pencacahan.<br><br><b>Pengangguran Terbuka</b> mencakup: sedang mempersiapkan usaha baru, merasa tidak mungkin mendapat pekerjaan (discouraged worker), dan sudah diterima kerja tapi belum mulai bekerja. Indikator TPT bersumber dari <b>Sakernas</b>, bukan Susenas.', 15, 5, 13),
(33, 2, 'Produk, Sejarah, dan Prinsip Internasional Statistik BPS', 'Logo BPS memuat grafik batang tiga warna yang melambangkan tiga sensus nasional; warna oranye melambangkan Sensus Ekonomi.<br><br><b>Daerah Dalam Angka (DDA)</b> adalah publikasi tahunan BPS paling komprehensif (mencakup geografi, pemerintahan, penduduk, sosial, dan ekonomi suatu wilayah), yang rutin dirilis serentak akhir Februari.<br><br><b>WebGIS/Silastik</b> menyajikan visualisasi peta indikator statistik wilayah, sedangkan <b>SP2HP</b> adalah aplikasi pemantauan dan pelaporan harga barang kebutuhan pokok secara digital.<br><br><b>Hari Statistik Nasional</b> diperingati setiap 26 September, mengenang lahirnya UU No. 7 Tahun 1960 tentang Statistik. <b>ARC (Advance Release Calendar)</b> &mdash; jadwal rilis data setahun di muka &mdash; adalah wujud prinsip akuntabilitas dan transparansi dalam Fundamental Principles of Official Statistics PBB.', 12, 5, 14),
(34, 3, 'Nilai Tukar Petani (NTP) dan Klasifikasi Sektor Pertanian', '<b>Nilai Tukar Petani (NTP)</b> adalah rasio Indeks Harga yang Diterima Petani (It) terhadap Indeks Harga yang Dibayar Petani (Ib), dikali 100. NTP di bawah 100 berarti petani mengalami defisit &mdash; harga yang mereka bayar naik lebih cepat daripada harga yang mereka terima, sehingga daya beli menurun.<br><br>NTP disusun dari 5 subsektor: <b>Tanaman Pangan (NTPP)</b>, <b>Hortikultura (NTPH)</b>, <b>Tanaman Perkebunan Rakyat (NTPR)</b>, <b>Peternakan (NTPT)</b>, dan <b>Perikanan (NTNP)</b>.<br><br><b>Petani Subsisten</b> adalah petani yang hasil usaha taninya untuk memenuhi konsumsi rumah tangga sendiri, bukan dijual. <b>Petani Gurem</b> adalah rumah tangga usaha pertanian yang menguasai lahan kurang dari 0,50 hektare.<br><br>Hortikultura mencakup sayur, buah, tanaman obat/biofarmaka, dan tanaman hias, sedangkan Tanaman Pangan mencakup padi dan palawija (jagung, kedelai, kacang tanah, kacang hijau, ubi kayu, ubi jalar).', 15, 5, 5),
(35, 3, 'Ketenagakerjaan Lanjutan: TPAK, Jenis Pengangguran, dan Konsep Bekerja', '<b>TPAK (Tingkat Partisipasi Angkatan Kerja)</b> dihitung dengan rumus: (Jumlah Angkatan Kerja &divide; Jumlah Penduduk Usia Kerja) &times; 100%. <b>Angkatan Kerja</b> terdiri dari penduduk yang bekerja ditambah pengangguran terbuka, sedangkan <b>Penduduk Usia Kerja</b> adalah penduduk berusia 15 tahun ke atas.<br><br><b>Setengah Penganggur (Pengangguran Terselubung)</b> adalah orang yang bekerja kurang dari 35 jam seminggu namun masih mencari kerja atau bersedia menerima pekerjaan tambahan.<br><br><b>Pengangguran Terbuka</b> mencakup orang yang tidak bekerja dan sedang mencari kerja, termasuk yang sedang mempersiapkan usaha baru atau sudah diterima kerja tapi belum mulai bekerja.<br><br>Konsep &quot;Bekerja&quot; dalam Sakernas adalah kegiatan ekonomi untuk memperoleh pendapatan minimal 1 jam (boleh tidak berturut-turut) selama seminggu terakhir.', 15, 5, 6),
(36, 3, 'Indikator Kependudukan: Rasio Ketergantungan, Sex Ratio, dan Fertilitas', '<b>Rasio Ketergantungan (Dependency Ratio)</b> dihitung dengan rumus: (penduduk usia 0-14 tahun + usia 65 tahun ke atas) &divide; penduduk usia produktif (15-64 tahun) &times; 100. Nilai yang rendah menandakan potensi <b>Bonus Demografi</b>.<br><br><b>Sex Ratio</b> adalah jumlah penduduk laki-laki per 100 penduduk perempuan.<br><br><b>TFR (Total Fertility Rate)</b> adalah rata-rata jumlah anak yang dilahirkan seorang wanita sepanjang usia reproduksinya (15-49 tahun).<br><br>Proyeksi penduduk BPS-Bappenas menggunakan <b>Metode Komponen (Cohort Component Method)</b>. Data seperti Angka Kematian Ibu (AKI), yang tergolong kejadian langka (rare events), diestimasi lewat Sensus Penduduk Long Form atau SUPAS, bukan survei sampel kecil biasa.', 12, 5, 7),
(37, 3, 'Ketimpangan dan Kesetaraan Gender: Gini Ratio, IPG, IDG, IKG', '<b>Rasio Gini</b> berkisar antara 0 sampai 1: semakin mendekati 0 berarti distribusi (misalnya pengeluaran) semakin merata, semakin mendekati 1 berarti semakin timpang.<br><br><b>IPG (Indeks Pembangunan Gender)</b> membandingkan capaian dimensi IPM (kesehatan, pendidikan, standar hidup layak) antara laki-laki dan perempuan &mdash; semakin dekat ke angka 100, semakin setara.<br><br><b>IDG (Indeks Pemberdayaan Gender)</b> tersusun dari 3 komponen: partisipasi politik (keterwakilan di parlemen), pengambilan keputusan ekonomi (persentase perempuan di posisi manajerial/profesional), dan penguasaan sumber daya ekonomi (sumbangan pendapatan perempuan).<br><br><b>IKG (Indeks Ketimpangan Gender)</b> diadopsi dari UNDP, dengan dimensi Pemberdayaan diukur dari persentase kursi parlemen dan persentase penduduk berusia 25 tahun ke atas yang berpendidikan minimal SMA, menurut jenis kelamin.', 15, 5, 8),
(38, 3, 'Indeks-Indeks Sosial dan Kesejahteraan Non-Ekonomi BPS', '<b>IDI (Indeks Demokrasi Indonesia)</b> data sekundernya dikumpulkan lewat Content Analysis (Analisis Konten) terhadap berita media massa dan dokumen resmi pemerintah.<br><br><b>Indeks Kebahagiaan BPS</b> adalah indeks komposit dari 3 dimensi: Kepuasan Hidup (Life Satisfaction), Perasaan (Affect), dan Makna Hidup (Eudaimonia).<br><br><b>IPAK (Indeks Perilaku Anti Korupsi)</b> memiliki skala 0-5, di mana semakin mendekati 5 berarti masyarakat semakin bersih/anti-korupsi.<br><br><b>IP-TIK</b> tersusun dari 3 sub-indeks: Akses/Infrastruktur, Pemanfaatan (Use), dan Keahlian (Skills), mengadopsi standar internasional ITU. <b>Indeks KUB (Kerukunan Umat Beragama)</b> memiliki 3 dimensi utama: Toleransi, Kesetaraan, dan Kerja Sama.<br><br>Penting diketahui, IPM tidak mencakup dimensi kebahagiaan atau kriminalitas &mdash; keduanya dirilis terpisah lewat Indeks Kebahagiaan dan statistik Keamanan &amp; Kriminalitas. Salah satu indikator perumahan sehat BPS adalah luas lantai minimal 7,2 m&sup2; per kapita untuk dikategorikan layak huni.', 15, 5, 9),
(39, 3, 'PDB, PNB, dan Kondisi Perekonomian Makro', '<b>PNB (Produk Nasional Bruto)</b> dihitung berdasarkan kewarganegaraan (nationality) &mdash; pendapatan WNI di luar negeri ikut dihitung, sedangkan pendapatan WNA di dalam negeri dikeluarkan. Ini berbeda dengan PDB yang berbasis wilayah.<br><br><b>PDB Atas Dasar Harga Konstan (ADHK)</b> dipakai untuk mengukur pertumbuhan ekonomi riil (bebas pengaruh inflasi), sedangkan <b>PDB Atas Dasar Harga Berlaku (ADHB)</b> menunjukkan nilai nominal saat ini.<br><br><b>Resesi ekonomi</b> terjadi ketika pertumbuhan PDB/PDRB ADHK bernilai negatif selama dua kuartal berturut-turut. Pertumbuhan yang positif namun melambat (misalnya dari 5,0% ke 4,8%) bukan resesi, karena ekonomi tetap tumbuh, hanya kecepatannya menurun.<br><br><b>Stagflasi</b> adalah kondisi gabungan antara stagnasi pertumbuhan ekonomi dan inflasi yang tinggi secara bersamaan. <b>Tabel Input-Output</b> BPS dipakai untuk menganalisis dampak pengganda (multiplier effect) dan keterkaitan antar sektor ekonomi.', 15, 5, 10),
(40, 3, 'Metodologi Lanjutan Penghitungan IHK dan Inflasi', 'BPS menghitung <b>IHK (Indeks Harga Konsumen)</b> memakai formula Laspeyres yang dimodifikasi, di mana bobot/kuantitas komoditas dikunci di tahun dasar (hasil Survei Biaya Hidup/SBH) sehingga tidak perlu dihitung ulang setiap bulan, dan rilis inflasi bisa lebih cepat.<br><br>Diagram timbang dari SBH memastikan komoditas yang paling banyak dikonsumsi masyarakat (misalnya beras) berpengaruh besar terhadap inflasi, sementara barang mewah yang jarang dibeli tidak mendistorsi angkanya. Kelompok <b>Makanan, Minuman, dan Tembakau</b> biasanya menyumbang andil terbesar (sekitar 25%) terhadap inflasi umum (headline inflation).<br><br><b>Inflasi Year-on-Year (YoY)</b> membandingkan level harga suatu bulan dengan bulan yang sama pada tahun sebelumnya.<br><br><b>IHPB (Indeks Harga Perdagangan Besar)</b> mengukur harga di tingkat grosir, dan <b>IHP (Indeks Harga Produsen)</b> mengukur harga yang diterima produsen domestik &mdash; keduanya berfungsi sebagai early warning inflasi sebelum sampai ke konsumen. <b>Seasonal Adjustment</b> digunakan untuk menghilangkan efek musiman berulang (Lebaran, Natal, panen raya) dari data agar tren aslinya terlihat jelas.', 15, 5, 11),
(41, 3, 'Perdagangan Luar Negeri, Distribusi, dan Ekonomi Digital', '<b>Neraca Perdagangan</b> dikatakan surplus jika nilai ekspor lebih besar dari nilai impor, dan defisit jika sebaliknya.<br><br>Ekspor dicatat dengan basis <b>FOB (Free on Board)</b>, yaitu harga sampai barang dimuat ke kapal, belum termasuk biaya angkut dan asuransi. Impor dicatat dengan basis <b>CIF (Cost, Insurance, Freight)</b>, yang sudah termasuk biaya angkut dan asuransi.<br><br><b>SPAW (Survei Perdagangan Antar Wilayah)</b> mengukur nilai, volume, dan moda transportasi transaksi perdagangan barang antar-provinsi di dalam negeri.<br><br><b>GMV (Gross Merchandise Value)</b> adalah total nilai transaksi kotor e-commerce/marketplace sebelum dikurangi biaya operasional, diskon, atau refund.', 12, 5, 12),
(42, 3, 'Statistik Pariwisata, Industri, dan Keuangan Daerah', '<b>TPK (Tingkat Penghunian Kamar)</b> adalah persentase kamar hotel yang terjual dibandingkan kapasitas yang tersedia, dirilis untuk Hotel Bintang maupun Non-Bintang. TPK bisa turun meski jumlah wisatawan mancanegara naik, jika Rata-rata Lama Menginap Tamu (RLMT) memendek.<br><br>Klasifikasi industri pengolahan berdasarkan jumlah tenaga kerja: <b>Mikro</b> (1-4 orang), <b>Kecil</b> (5-19 orang), <b>Sedang/Menengah</b> (20-99 orang), dan <b>Besar</b> (100 orang atau lebih).<br><br>Dalam komponen <b>Pendapatan Asli Daerah (PAD)</b>, Retribusi Daerah umumnya memberikan kontribusi paling kecil dibanding komponen PAD lainnya.', 12, 5, 13),
(43, 3, 'Metodologi Lanjutan Kemiskinan dan IPM', '<b>Garis Kemiskinan (GK)</b> terdiri dari <b>GKM (Garis Kemiskinan Makanan)</b>, setara 2.100 kkal per kapita per hari yang diwakili 52 komoditas dasar, ditambah <b>GKNM (Garis Kemiskinan Non-Makanan)</b> seperti perumahan, sandang, pendidikan, kesehatan, dan transportasi. GKM menyumbang porsi terbesar terhadap GK nasional, sekitar 74-75%.<br><br><b>Kemiskinan ekstrem</b>, mengikuti standar Bank Dunia yang diadopsi BPS, didefinisikan sebagai pengeluaran di bawah USD 2,15 (PPP) per kapita per hari.<br><br>Dimensi <b>Standar Hidup Layak</b> pada IPM dihitung memakai transformasi logaritma natural (Ln) karena adanya diminishing marginal utility of income (tambahan pendapatan memberi manfaat yang makin kecil). Dimensi <b>Umur Panjang dan Hidup Sehat</b> diukur dari Usia Harapan Hidup saat Lahir (UHH), sedangkan dimensi <b>Pengetahuan</b> disusun dari Rata-rata Lama Sekolah (RLS, usia 25+) dan Harapan Lama Sekolah (HLS, usia 7+).<br><br>Sejak 2014, IPM dihitung dengan <b>rata-rata geometrik</b> (bukan aritmetika), agar capaian rendah di satu dimensi tidak bisa ditutupi oleh capaian tinggi di dimensi lain.', 15, 5, 14);
