INSERT INTO `soal` (`id`, `kategori_id`, `level`, `pertanyaan`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `jawaban`, `pembahasan`, `xp`) VALUES
(1, 1, 'Mudah', 'Apa yang dimaksud dengan Mean?', 'Nilai Tengah', 'Nilai Terbesar', 'Rata-rata seluruh data', 'Jumlah data', 'C', 'Mean adalah nilai rata-rata dari suatu kelompok data.', 10),
(2, 1, 'Mudah', 'Karakteristik data tunggal yang paling sering muncul atau memiliki frekuensi terbanyak disebut ...', 'Mean', 'Median', 'Modus', 'Range', 'C', 'Modus didefinisikan sebagai nilai dari variabel atau observasi yang paling sering muncul atau memiliki frekuensi kemunculan tertinggi di antara data lainnya. Keunikan dari modus adalah sebuah kelompok data bisa memiliki satu modus (unimodal), dua modus (bimodal), banyak modus (multimodal), atau bahkan tidak memiliki modus sama sekali jika semua data muncul dengan frekuensi yang sama', 10),
(3, 2, 'Mudah', 'BPS merupakan singkatan dari?', 'Badan Perencanaan Statistik', 'Badan Pusat Statistik', 'Biro Pusat Survei', 'Badan Pengolahan Statistik', 'B', 'BPS merupakan singkatan dari Badan Pusat Statistik.', 10),
(4, 1, 'Mudah', 'Median adalah istilah untuk?', 'Rata-rata data', 'Nilai tengah data yang telah diurutkan', 'Nilai yang sering muncul', 'Jumlah seluruh data', 'B', 'Median atau yang sering disebut sebagai nilai tengah adalah suatu nilai yang membagi sekumpulan data menjadi dua bagian yang sama besar setelah diurutkan dari yang terkecil hingga terbesar.', 10),
(5, 1, 'Mudah', 'Statistika adalah ilmu yang mempelajari cara?', 'Mengumpulkan, mengolah, menyajikan, dan menganalisis data', 'Menghitung uang', 'Membuat grafik saja', 'Mensurvei penduduk saja', 'A', 'Ilmu yang mempelajari tentang pengumpulan, pengolahan, penganalisisan, interpretasi, hingga penyajian data disebut Statistika.', 10),
(6, 1, 'Sedang', 'Diberikan data nilai ujian : 65, 70, 85, 80, 60, 90, 75, 80. \r\nNilai Jangkauan Antarkuartil (Hamparan) dari data tersebut adalah ...', '10', '12,5', '15', '17,5', 'C', 'Jangkauan Antarkuartil (atau disebut juga Hamparan) dihitung menggunakan rumus selisih antara Kuartil Atas (Q3) dan Kuartil Bawah (Q1) : H = Q3 - Q1\r\n\r\nLangkah-langkahnya :\r\n1. Urutkan data dari yang terkecil ke terbesar => \r\n    60, 65, 70, 75, 80, 85, 90\r\n    Total data (n) adalah 8 (genap).\r\n2. Bagi data menjadi dua bagian untuk mencari Median (Q2) =>\r\n    a. Kelompok Bawah : 60, 65, 70, 75\r\n    b. Kelompok Atas : 80, 80, 85, 90\r\n3. Cari Kuartil Bawah (Q1) yaitu nilai tengah dari kelompok bawah => dua angka di tengah kelompok bawah adalah 65 dan 70.\r\nQ1 = 65+70/2 = 67,5\r\n4. Cari Kuartil Bawah (Q3) yaitu nilai tengah dari kelompok atas => dua angka di tengah kelompok atas adalah 80 dan 85.\r\nQ3 = 80+85/2 = 82,5\r\n5. Hitung jangkauan AntarKuartil (hamparan) =>\r\nH = Q3 - Q1 = 82,5 - 67,5 = 15', 10),
(7, 1, 'Sedang', 'Diagram yang paling cocok untuk menampilkan perbandingan proporsi/persentase adalah?', 'Diagram Garis', 'Diagram Batang', 'Diagram Lingkaran', 'Tabel Distribusi', 'C', 'Diagram lingkaran (pie chart) adalah diagram yang paling cocok untuk menampilkan perbandingan proporsi atau persentase. Alasanya :\r\n1. Visualisasi utuh => menampilkan data sebagai potongan dari satu kesatuan utuh (100%). \r\n2. Mudah dipahami => setiap potongan lingkaran langsung mencerminkan besar kecilnya persentase komponen.\r\n3. Fokus kategori => sangat efektif untuk membandingkan sedikir variabel (ideal rentang 2-7 kategori).', 10),
(8, 1, 'Sedang', 'Median lebih cocok digunakan dibanding mean ketika data memiliki?', 'Data yang simetris', 'Nilai ekstrem (outlier)', 'Jumlah data sedikit', 'Data berbentuk grafik', 'B', 'Median lebih cocok digunakan dibanding Mean ketika data memiliki nilai ekstrem atau pencilan (outlier).\r\nAlasannya karena Mean (Rata-rata) sangat sensitif terhadap nilai ekstrem karena melibatkan seluruh angka dalam perhitungan.\r\nSedangkan Median (Nilai tengah) tidak terpengaruh oleh angka yang terlalu besar atau terlalu kecil di ujung data', 10),
(9, 1, 'Sedang', 'Tabel distribusi frekuensi digunakan untuk?', 'Menyajikan data mentah tanpa pengelompokan', 'Mengelompokkan data dan menunjukkan banyaknya kemunculan tiap kelompok', 'Menghitung mean saja', 'Mengganti diagram batang', 'B', 'Tabel distribusi frekuensi dirancang khusus sebagai alat penyajian data Statistik untuk menyusun data acak ke dalam kelas interval tertentu (kelompok). Tabel ini juga mencatat frekuensi yang menunjukkan seberapa sering nilai dalam kelompok tersebut muncul.', 10),
(10, 1, 'Mudah', 'Data : 4, 8, 6, 5, 3, 8, 9. \r\nModus dari data tersebut adalah?', '4', '6', '8', '9', 'C', 'Modus adalah nilai yang paling sering muncul atau memiliki frekuensi kemunculan terbanyak dalam suatu kumpulan data. \r\nUntuk mempermudah melihat frekuensinya, mari kita hitung berapa kali setiap angka muncul :\r\n1. Angka 3 muncul sebanyak 1 kali.\r\n2. Angka 4 muncul sebanyak 1 kali.\r\n3. Angka 5 muncul sebanyak 1 kali.\r\n4. Angka 6 muncul sebanyak 1 kali.\r\n5. Angka 8 muncul sebanyak 2 kali.\r\n6. Angka 9 muncul sebanyak 1 kali.\r\n\r\nKarena angka 8 muncul paling banyak (yaitu 2 kali) dibandingkan dengan angka-angka lainnya, maka modus dari kelompok data tersebut adalah 8.', 10),
(11, 1, 'Sedang', 'Data nilai praktikum Biologi 8 orang mahasiswa adalah sebagai berikut : 75, 80, 65, 90, 70, 85, 65, 75. \r\nNilai median dari data praktikum tersebut adalah ...', '70', '72,5', '75', '77,5', 'C', '1. Urutkan data dari terkecil ke terbesar =>  65, 65, 70, 75, 75, 80, 85, 90.\r\n2. Jumlah data genap (n = 8), posisi dua angka tengah terletak pada data ke-4 \r\n    dan data ke-5.\r\n3. Data ke-4 adalah 75 dan data ke-5 adalah 75.\r\n4. Hitung rata-ratanya => 75+75/2 = 75', 10),
(12, 1, 'Sedang', 'Untuk data berjumlah genap, median dihitung dengan cara?', 'Mengambil satu nilai tengah', 'Rata-rata dua nilai tengah setelah data diurutkan', 'Mengambil modus data', 'Total data dibagi banyak data', 'B', 'Apabila sebuah kelompok data memiliki jumlah anggota yang genap (misalnya n = 4, 6, 8, ...), kita tidak bisa menunjuk satu angka tunggal di tengah-tengah. Oleh karena itu, aturan baku statistika menetapkan bahwa data tersebut wajib diurutkan terlebih dahulu dari yang terkecil. Setelah itu, kita mengambil dua buah angka yang berada paling tengah, menjumlahkannya, lalu membaginya dengan dua (mencari rata-ratanya).', 10),
(13, 1, 'Mudah', 'Grafik yang paling tepat untuk menunjukkan tren/perkembangan data dari waktu ke waktu adalah?', 'Diagram Lingkaran', 'Diagram Garis', 'Diagram Batang', 'Tabel Distribusi', 'B', 'Diagram garis adalah jenis grafik statistik yang paling ideal untuk menggambarkan tren, perkembangan, atau perubahan suatu data secara terus-menerus dalam jangka waktu tertentu (time series data). Sumbu horizontal (X) biasanya digunakan untuk menunjukkan kronologi waktu (seperti jam, hari, bulan, atau tahun), sedangkan sumbu vertikal (Y) menunjukkan nilai datanya. Garis penghubung antar-titik mempermudah kita melihat pola kenaikan atau penurunan data secara cepat.', 10),
(14, 2, 'Mudah', 'BPS adalah Lembaga Pemerintah Non Kementerian yang bertanggung jawab langsung kepada?', 'Gubernur', 'Presiden', 'Menteri Dalam Negeri', 'DPR', 'B', 'Berdasarkan ketentuan tata negara di Indonesia yang diatur dalam Undang-Undang Nomor 16 Tahun 1997 tentang Statistik, Badan Pusat Statistik (BPS) ditetapkan secara resmi sebagai sebuah Lembaga Pemerintah Non Kementerian (LPNK). Sebagai LPNK, kedudukan BPS berada di bawah dan bertanggung jawab langsung kepada Presiden.', 10),
(15, 2, 'Mudah', 'Sensus Penduduk Sensus Penduduk (SP) di Indonesia dilaksanakan oleh BPS setiap 10 tahun sekali, yaitu pada tahun yang berakhiran angka…', '0', '3', '6', '8', 'A', 'Berdasarkan UU Nomor 16 Tahun 1997 tentang Statistik, Sensus Penduduk (SP) di Indonesia dirancang untuk diselenggarakan setiap 10 tahun sekali pada tahun yang berakhiran angka 0 [Sensus Pertanian BPS]. Sensus ini bertujuan untuk menghitung jumlah penduduk, persebaran, dan karakteristik demografi seluruh warga negara Indonesia. \r\nContoh pelaksanaannya adalah Sensus Penduduk tahun 2000, 2010, dan 2020.', 10),
(16, 2, 'Mudah', 'Kegiatan mengumpulkan data dari seluruh unit populasi disebut?', 'Survei', 'Sensus', 'Riset', 'Observasi', 'B', 'Berdasarkan UU Nomor 16 Tahun 1997 tentang Statistik, Sensus didefinisikan sebagai cara pengumpulan data yang dilakukan melalui pencacahan terhadap seluruh unit populasi tanpa terkecuali [Sensus Pertanian BPS]. \r\nTujuannya adalah untuk mendapatkan karakteristik nyata dari populasi tersebut secara menyeluruh dan akurat (seperti Sensus Penduduk, Sensus Pertanian, dan Sensus Ekonomi) [Sensus Pertanian BPS, Wikipedia Sensus Pertanian 2023].', 10),
(17, 2, 'Mudah', 'Sensus Pertanian di Indonesia dilaksanakan pada tahun yang berakhiran angka?', '0', '3', '5', '7', 'B', 'Berdasarkan amanat Undang-Undang Republik Indonesia Nomor 16 Tahun 1997 tentang Statistik, Badan Pusat Statistik (BPS) menyelenggarakan tiga jenis sensus nasional secara berkala setiap 10 tahun sekali.\r\nSensus Pertanian (ST) : Dilaksanakan pada tahun yang berakhiran angka 3 (contoh : 2003, 2013, dan yang terakhir adalah Sensus Pertanian 2023', 10),
(18, 2, 'Sedang', 'Kode Etik Mitra Lapangan Jika seorang responden menolak memberikan informasi pendapatan karena dinilai rahasia, sikap terbaik dari seorang mitra pencacah adalah ...', 'Memaksa responden dengan nada keras', 'Mengisi kuisioner dengan data karangan sendiri', 'Menjelaskan jaminan kerahasiaan data Undang-Undang dan membujuk secara sopan', 'Langsung meninggalkan rumah responden tanpa pamit', 'C', 'Kode etik utama petugas lapangan/mitra pencacah statistik (seperti mitra BPS) menekankan pentingnya profesionalisme, integritas, dan persuasif tanpa paksaan. \r\nSesuai dengan UU Nomor 16 Tahun 1997 tentang Statistik, data pribadi responden dijamin kerahasiaannya oleh undang-undang. Jika responden merasa ragu atau takut, tugas pencacah adalah memberikan edukasi secara ramah mengenai payung hukum perlindungan data tersebut dan kembali membujuknya secara sopan demi mendapatkan data yang valid.', 10),
(19, 2, 'Sedang', 'Perbedaan utama survei dengan sensus adalah?', 'Survei mencakup seluruh populasi, sensus memakai sampel', 'Survei memakai sebagian data (sampel), sensus mencakup seluruh populasi', 'Survei dan sensus sama saja', 'Survei hanya untuk data ekonomi', 'B', 'Perbedaan paling mendasar dan utama antara survei dan sensus terletak pada cakupan objek yang didata [Sensus Pertanian BPS] : \r\n- Sensus => Mengumpulkan data dari seluruh anggota populasi tanpa \r\n   terkecuali [Sensus Pertanian BPS]. \r\n   Contohnya : Sensus Penduduk yang mendata seluruh warga negara Indonesia \r\n   [Sensus Pertanian BPS].\r\n- Survei => Hanya mengambil sebagian kecil dari populasi (disebut sebagai \r\n   sampel) yang dipilih dengan teknik tertentu untuk mewakili karakteristik \r\n   seluruh kelompok besar tersebut', 10),
(20, 2, 'Mudah', 'Salah satu fungsi utama BPS adalah?', 'Menetapkan kebijakan fiskal negara', 'Menyediakan data statistik dasar bagi pemerintah dan masyarakat', 'Mengelola anggaran negara', 'Menyusun undang-undang', 'B', 'Berdasarkan Undang-Undang Nomor 16 Tahun 1997 tentang Statistik, salah satu tugas pokok dan fungsi utama Badan Pusat Statistik (BPS) adalah sebagai penyedia Statistik Dasar [PPID BPS]. \r\nStatistik dasar adalah statistik yang pemanfataannya ditujukan untuk keperluan luas, baik bagi pemerintah (sebagai basis perencanaan dan evaluasi kebijakan nasional) maupun masyarakat umum, akademisi, dan pelaku bisnis (sebagai rujukan riset dan keputusan ekonomi) [PPID BPS]. \r\nContoh data ini meliputi angka inflasi, pertumbuhan ekonomi, tingkat pengangguran, indeks kemiskinan, dan hasil sensus [PPID BPS]', 10),
(21, 2, 'Sedang', 'Dasar hukum penyelenggaraan statistik dan pembentukan BPS diatur dalam?', 'UU No. 16 Tahun 1997 tentang Statistik', 'UU No. 8 Tahun 1999', 'UU No. 25 Tahun 2004', 'UU No. 23 Tahun 2014', 'A', 'Seluruh payung hukum utama mengenai tata cara penyelenggaraan kegiatan statistik di Indonesia serta pembentukan, tugas pokok, fungsi, dan wewenang struktural dari Badan Pusat Statistik (BPS) diatur secara komprehensif di dalam Undang-Undang Nomor 16 Tahun 1997 tentang Statistik [PPID BPS]. \r\nUndang-undang inilah yang mengubah nama instansi ini dari yang semula \"Biro Pusat Statistik\" menjadi \"Badan Pusat Statistik\" [PPID BPS].', 10),
(22, 2, 'Mudah', 'Data yang dihasilkan BPS dan digunakan secara luas oleh berbagai sektor disebut?', 'Data Sektoral', 'Data Internal', 'Data Khusus', 'Data Statistik Dasar', 'D', 'Berdasarkan Undang-Undang Nomor 16 Tahun 1997 tentang Statistik, Statistik Dasar adalah statistik yang pemanfaatannya ditujukan untuk keperluan luas, baik bagi pemerintah maupun masyarakat, memiliki ciri lintas sektoral, berskala nasional, makro, dan diselenggarakan oleh Badan Pusat Statistik (BPS) [PPID BPS]. \r\nContoh data statistik dasar ini adalah data Sensus Penduduk, angka Inflasi, Pertumbuhan Ekonomi, Indeks Kemiskinan, dan Tingkat Pengangguran [PPID BPS].', 10),
(23, 2, 'Mudah', 'Survei rutin BPS yang mengukur kondisi sosial ekonomi rumah tangga adalah?', 'Susenas', 'Sensus Pertanian', 'Sensus Ekonomi', 'Sakernas', 'A', 'Survei Sosial Ekonomi Nasional (Susenas) adalah survei rutin andalan BPS yang dirancang khusus untuk mengumpulkan data mengenai kondisi sosial ekonomi rumah tangga di Indonesia. Data yang dihasilkan dari Susenas mencakup pilar-pilar penting seperti tingkat pengeluaran/konsumsi rumah tangga (menjadi dasar penghitungan angka kemiskinan dan Gini Ratio), status pendidikan, kesehatan, perumahan, serta pemenuhan kebutuhan hidup lainnya.', 10),
(24, 2, 'Mudah', 'Survei Angkatan Kerja Nasional yang mengukur kondisi ketenagakerjaan disebut?', 'Susenas', 'Sakernas', 'SP2020', 'SE2016', 'B', 'Sakernas adalah singkatan dari Survei Angkatan Kerja Nasional. Survei rutin yang diselenggarakan oleh BPS ini dirancang khusus untuk mengumpulkan data mengenai kondisi ketenagakerjaan di Indonesia secara berkala. \r\nIndikator utama yang dihasilkan dari Sakernas meliputi Tingkat Pengangguran Terbuka (TPT), jumlah angkatan kerja, lapangan pekerjaan yang mendominasi, status pekerjaan, serta rata-rata upah buruh', 10),
(25, 3, 'Mudah', 'IPM adalah singkatan dari?', 'Indeks Pembangunan Manusia', 'Indeks Produktivitas Masyarakat', 'Indikator Pendapatan Masyarakat', 'Indeks Pertumbuhan Modal', 'A', 'IPM adalah singkatan dari Indeks Pembangunan Manusia.\r\nDalam konteks internasional, indeks ini dikenal dengan istilah HDI (Human Development Index)', 10),
(26, 3, 'Mudah', 'Kenaikan harga barang dan jasa secara umum dan terus-menerus disebut?', 'Deflasi', 'Inflasi', 'Resesi', 'Devaluasi', 'B', 'Inflasi adalah kenaikan harga barang dan jasa secara umum dan terus-menerus.\r\nSecara Umum => Berarti kenaikan harga tidak hanya terjadi pada satu atau dua barang saja (misalnya hanya harga cabai naik), melainkan meluas ke sebagian besar kelompok barang dan jasa lainnya.\r\nTerus-Menerus => Kenaikan tersebut berlangsung dalam jangka waktu yang relatif lama atau konsisten, bukan hanya lonjakan sesaat (seperti kenaikan musiman sehari sebelum hari raya).', 10),
(27, 3, 'Mudah', 'Persentase penduduk yang berada di bawah garis kemiskinan disebut?', 'Tingkat Pengangguran', 'Tingkat Kemiskinan', 'Tingkat Inflasi', 'Tingkat Pertumbuhan Ekonomi', 'B', 'Tingkat Kemiskinan (Persentase Penduduk Miskin - P0)\r\n => Mengukur persentase jumlah penduduk yang memiliki rata-rata   \r\n       pengeluaran per kapita per bulan di bawah Garis Kemiskinan (GK).', 10),
(28, 3, 'Mudah', 'PDRB adalah singkatan dari?', 'Produk Domestik Regional Bruto', 'Pendapatan Daerah Regional Bruto', 'Produk Domestik Rata-rata Bruto', 'Pertumbuhan Domestik Regional Bruto', 'A', 'PDRB (Produk Domestik Regional Bruto) mengukur nilai tambah ekonomi suatu wilayah.\r\nDalam istilah ekonomi internasional, PDRB setara dengan Gross Regional Domestic Product (GRDP). PDRB merupakan salah satu indikator makroekonomi terpenting yang dihitung oleh BPS untuk mengukur kinerja ekonomi di tingkat daerah (Provinsi maupun Kabupaten/Kota).', 10),
(29, 3, 'Mudah', 'IPM dihitung berdasarkan tiga dimensi dasar, yaitu?', 'Kesehatan, Pendidikan, Standar Hidup Layak', 'Kesehatan, Ekonomi, Politik', 'Pendidikan, Infrastruktur, Keamanan', 'Ekonomi, Sosial, Budaya', 'A', 'Tiga dimensi dasar pembentuk Indeks Pembangunan Manusia (IPM) adalah => \r\n1. Umur Panjang dan Hidup Sehat (Kesehatan)\r\n2. Pengetahuan (Pendidikan)\r\n3. Standar Hidup Layak (Ekonomi)', 10),
(30, 3, 'Mudah', 'Tingkat Pengangguran Terbuka (TPT) menunjukkan?', 'Persentase penduduk usia kerja yang bekerja', 'Persentase angkatan kerja yang tidak memiliki pekerjaan', 'Jumlah penduduk usia produktif', 'Jumlah lapangan kerja baru', 'B', 'Tingkat Pengangguran Terbuka (TPT) menunjukkan persentase jumlah pengangguran terhadap jumlah total angkatan kerja.\r\nTPT menggambarkan seberapa besar porsi pasokan tenaga kerja (angkatan kerja) yang gagal atau belum terserap oleh pasar kerja yang tersedia.', 10),
(31, 3, 'Mudah', 'PDRB dapat digunakan untuk mengukur?', 'Tingkat kebahagiaan penduduk', 'Kinerja/pertumbuhan ekonomi suatu wilayah', 'Jumlah penduduk miskin', 'Tingkat pendidikan masyarakat', 'B', 'PDRB (Produk Domestik Regional Bruto) digunakan oleh BPS untuk mengukur pertumbuhan ekonomi suatu daerah dan struktur ekonomi wilayah tersebut.', 10),
(32, 3, 'Mudah', 'Garis kemiskinan versi BPS ditentukan berdasarkan?', 'Pendapatan minimum regional', 'Nilai pengeluaran minimum untuk kebutuhan dasar makanan dan non-makanan', 'Harga emas', 'Jumlah utang penduduk', 'B', 'Garis kemiskinan versi Badan Pusat Statistik (BPS) ditentukan berdasarkan konsep kemampuan memenuhi kebutuhan dasar (basic needs approach). Melalui pendekatan ini, kemiskinan diukur dari sisi pengeluaran minimum (bukan pendapatan) yang dibutuhkan oleh seseorang untuk memenuhi kebutuhan pokoknya.', 10),
(33, 3, 'Mudah', 'Inflasi di Indonesia umumnya diukur menggunakan perubahan?', 'Indeks Harga Konsumen (IHK)', 'Indeks Harga Produsen saja', 'Nilai Tukar Rupiah', 'Suku Bunga Bank Indonesia', 'A', 'Inflasi di Indonesia umumnya diukur menggunakan persentase perubahan Indeks Harga Konsumen (IHK).\r\nBadan Pusat Statistik (BPS) memantau perubahan IHK ini secara rutin dari waktu ke waktu untuk mengetahui pergerakan harga komoditas (sekeranjang barang dan jasa) yang dikonsumsi oleh masyarakat secara eceran.', 10),
(34, 3, 'Mudah', 'PDRB atas dasar harga konstan digunakan untuk melihat?', 'Pertumbuhan ekonomi riil tanpa pengaruh inflasi', 'Nilai nominal ekonomi saat ini', 'Jumlah penduduk', 'Tingkat kemiskinan', 'A', 'Pertumbuhan ekonomi secara riil dari tahun ke tahun [PDRB].', 10),
(35, 3, 'Mudah', 'Semakin tinggi nilai IPM suatu wilayah menunjukkan?', 'Semakin rendah kualitas pembangunan manusia', 'Semakin tinggi kualitas pembangunan manusia di wilayah tersebut', 'Semakin tinggi inflasi', 'Semakin tinggi pengangguran', 'B', 'Semakin tinggi nilai IPM (Indeks Pembangunan Manusia) suatu wilayah menunjukkan bahwa kualitas hidup, tingkat kesejahteraan, dan pembangunan manusia di wilayah tersebut semakin baik.', 10),
(36, 3, 'Mudah', 'Kondisi ekonomi dengan pengangguran dan inflasi yang tinggi secara bersamaan disebut?', 'Deflasi', 'Stagflasi', 'Resesi', 'Depresiasi', 'B', 'Kata stagflasi berasal dari gabungan dua istilah ekonomi, yaitu Stagnasi (pertumbuhan ekonomi yang macet atau jalan di tempat) dan Inflasi (kenaikan harga barang yang tinggi).', 10),
(38, 1, 'Sedang', 'Perhatikan data ukuran baju dari kandidat mitra BPS berikut : M, L, S, M, XL, L, M, L, M, S. \r\nModus dari data tersebut adalah ...', 'S', 'M', 'L', 'XL', 'B', 'Mari kita hitung frekuensi kemunculan setiap ukuran baju dari kandidat mitra BPS tersebut :\r\n1. Ukuran S muncul sebanyak = 2 kali\r\n2. Ukuran M muncul sebanyak = 4 kali\r\n3. Ukuran L muncul sebanyak = 3 kali\r\n4. Ukuran XL muncul sebanyak = 1 kali\r\n\r\nKarena ukuran baju M memiliki jumlah kemunculan terbanyak yaitu 4 kali dibandingkan ukuran lainnya, maka modus dari kelompok data tersebut adalah M.', 10),
(39, 2, 'Mudah', 'Landasan Hukum Utama Undang-Undang di Indonesia yang mengatur tentang segala hal yang berkaitan dengan penyelenggaraan statistik adalah...', 'UU Nomor 5 Tahu 2014', 'UU Nomor 16 Tahun 1997', 'UU Nomor 17 Tahun 2003', 'UU Nomor 23 Tahun 2014', 'B', 'Landasan hukum utama dan tertinggi yang mengatur tentang segala urusan penyelenggaraan statistik di Indonesia adalah Undang-Undang Nomor 16 Tahun 1997 tentang Statistik. UU ini menjadi payung hukum bagi Badan Pusat Statistik (BPS) dalam melaksanakan tugasnya, menetapkan jenis-jenis statistik (dasar, sektoral, khusus), serta mengatur hak dan kewajiban masyarakat serta pemerintah dalam kegiatan perstatistikan.', 10),
(40, 1, 'Sedang', 'Apa perbedaan utama antara Statistika dan Statistik?', 'Statistika adalah kumpulan data, sedangkan Statistik adalah metode analisisnya', 'Statistika adalah ilmu yang mempelajari cara pengumpulan dan analisis data, sedangkan Statistik adalah hasil data atau ukuran yang diperoleh dari sampel', 'Tidak ada perbedaan di antara keduanya, keduanya adalah istilah yang sama', 'Statistik digunakan untuk data kualitatif, sedangkan Statistika untuk data kuantitatif', 'B', 'Perbedaan utamanya terletak pada cakupan ilmunya. Statistika adalah ilmu atau metode yang mempelajari cara mengumpulkan, mengolah, menganalisis, dan menginterpretasikan data. Sementara itu, statistik adalah hasil dari proses tersebut, berupa kumpulan data, angka, atau ukuran (seperti rata-rata) yang diperoleh dari sampel.', 10),
(41, 1, 'Sedang', 'Tentukan titik tengah (nilai tengah) dari kelas interval 45 – 53 pada tabel distribusi frekuensi!', '48', '49', '50', '51', 'B', 'Untuk mencari titik tengah (xi) dari sebuah kelas interval pada tabel distribusi frekuensi, kita menggunakan rumus rata-rata dari batas bawah dan batas atas kelas tersebut : \r\nTitik Tengah = Batas Bawah + Batas Atas / 2\r\n\r\n1. Batas Bawah kelas = 45\r\n2. Batas Atas kelas = 53\r\n3. Hitung Titik Tengahnya = \r\nTitik Tengah = 45+53/2 = 98/2 = 49', 10),
(42, 1, 'Mudah', 'Nilai yang letaknya tepat di tegah-tengah setelah seluruh data diurutkan disebut ...', 'Kuartil atas', 'Modus', 'Mean', 'Median', 'D', 'Median adalah ukuran pemusatan data yang membagi data menjadi dua bagian sama banyak. Syarat mutlak sebelum menentukan nilai median adalah data wajib diurutkan dari nilai terkecil hingga terbesar terlebih dahulu. Angka yang berada di tepat posisi tengah itulah yang menjadi median.', 10),
(43, 1, 'Mudah', 'Berapakah nilai rata-rata (mean) dari kelompok data sederhana berikut : 5, 6, 7?', '5', '6', '7', '8', 'B', 'Untuk mencari nilai rata-rata (mean) dari kelompok data tunggal menggunakan rumus penjumlahan seluruh nilai data dibagi degan banyakan data. \r\n1. Jumlahkan seluruh nilai data => 5 + 6 + 7 = 18\r\n2. Hitung banyaknya data => ada 3 buah angka (n = 3)\r\n3. Bagi hasil penjumlahan dengan banyaknya data => Mean = 18/3 = 6', 10),
(44, 1, 'Mudah', 'Jika diketahui urutan data adalah 2, 3, 5, 8, 9. \r\nNilai median dari data tersebut adalah ...', '5', '3', '8', '9', 'A', 'Karena data pada soal sudah dalam posisi berurutan dari yang terkecil hingga terbesar (2, 3, 5, 8, 9), kita bisa langsung mencari nilai tengahnya.\r\nJumlah data di atas adalah ganjil, yaitu sebanyak 5 angka (n = 5).\r\nNilai yang berada tepat di tengah-tengah kelompok data tersebut (urutan ke-3) adalah 5.', 10),
(45, 1, 'Mudah', 'Tentukan modus dari kumpulan angka berikut : 4, 5, 5, 6, 7, 5, 8.', '4', '6', '5', '7', 'C', 'Modus adalah nilai yang paling sering muncul atau memiliki frekuensi kemunculan terbanyak dalam suatu kumpulan data.\r\n1. Angka 4 muncul sebanyak 1 kali\r\n2. Angka 5 muncul sebanyak 3 kali\r\n3. Angka 6 muncul sebanyak 1 kali\r\n4. Angka 7 muncul sebanyak 1 kali\r\n5. Angka 8 muncul sebanyak 1 kali\r\n\r\nKarena angka 5 muncul paling banyak (3 kali) dibanding angka lainnya, maka modus dari kumpulan data tersebut adalah 5.', 10),
(46, 1, 'Mudah', 'Berapakah nilai rata-rata dari data : 4, 4, 4, 4?', '2', '4', '8', '16', 'B', 'Karakteristik khusus dari nilai rata-rata (mean) adalah jika semua angka di dalam kelompok data bernilai sama, maka nilai rata-ratanya pasti akan sama dengan angka tersebut tanpa perlu dihitung ulang.\r\nJika dibuktikan menggunakan rumus hitung :\r\n1. Jumlahkan seluruh data => 4 + 4+ 4+ 4 = 16\r\n2. Banyaknya data (n) => ada 4 buah angka\r\n3. Hitung rata-rata => Mean = 16/4 = 4', 10),
(47, 1, 'Mudah', 'Tentukan modus dari deret data huruf berikut : A, B, O, B, A, B.', 'O', 'A', 'Tidak ada', 'B', 'D', 'Modus tidak hanya berlaku untuk data angka (kuantitatif), tetapi juga berlaku untuk data kategori atau huruf (kualitatif). Modus ditentukan dengan mencari nilai yang paling sering muncul atau memiliki frekuensi tertinggi.\r\n1. Huruf A muncul sebanyak 2 kali\r\n2. Huruf B muncul sebanyak 3 kali\r\n3. Huruf O muncul sebanyak 1 kali\r\n\r\nkarena huruf B memiliki frekuensi kemunculan terbanyak (yaitu 3 kali), maka modus dari deret data di atas adalah B.', 10),
(48, 1, 'Mudah', 'Dalam penyajian data, baris dan kolom yang disusun secara sistematis dinamakan ...', 'Grafik', 'Bagan', 'Tabel', 'Diagram', 'C', 'Tabel merupakan susunan data dua dimensi yang diatur secara sistematis ke dalam bentuk baris (horizontal) dan kolom (vertikal). Struktur ini mempermudah pengelompokan frekuensi data secara rapi sehingga informasi yang kompleks lebih mudah dibaca, dibandingkan, dan dianalisis secara cepat.', 10),
(49, 1, 'Mudah', 'Data yang didapatkan secara langsung oleh peneliti dari objek yang diteliti dinamakan data ...', 'Sekunder', 'Primer', 'Kualitatif', 'Berkala', 'B', 'Data Primer adalah jenis data yang dikumpulkan secara langsung dari sumber utamanya atau objek yang diteliti tanpa melalui perantara. Peneliti terjun langsung ke lapangan menggunakan instrumen seperti wawancara, kuesioner, observasi, atau eksperimen untuk mendapatkan data mentah yang segar dan spesifik sesuai kebutuhan risetnya.', 10),
(50, 1, 'Mudah', 'Data yang diambil dari sumber atau dokumen instansi lain (seperti mengambil data inflasi dari website BPS) disebut data ...', 'Primer', 'Sekunder', 'Mentah', 'Sampel', 'B', 'Data Sekunder adalah data yang didapatkan oleh peneliti secara tidak langsung melalui perantara, media, atau dokumen pihak ketiga. Karena data inflasi tersebut sudah dikumpulkan, diolah, dan dipublikasikan secara resmi oleh Badan Pusat Statistik (BPS), peneliti yang mengambilnya dari website BPS bertindak sebagai pengguna kedua.', 10),
(51, 1, 'Mudah', 'Manakah kumpulan nilai di bawah ini yang tidak memiliki nilai modus sama sekali?', '1, 2, 2, 3', '4, 4, 5, 5', '1, 2, 3, 4', '7, 7, 7, 8', 'C', 'Sebuah kelompok data dikatakan tidak memiliki modus sama sekali jika seluruh angka di dalam data tersebut muncul dengan jumlah frekuensi yang sama persis (tidak ada satu pun angka yang mendominasi atau lebih sering muncul).\r\nPada pilihan C, angka 1, 2, 3, dan 4 masing-masing hanya muncul sebanyak 1 kali. Karena frekuensinya seragam, maka kelompok data ini tidak mempunyai modus.', 10),
(52, 1, 'Mudah', 'Berapakah rentang jawaban jangkauan (range) dari data : 100, 250, 50, 300?', '150', '200', '250', '300', 'C', 'Rentang jangkauan (range) adalah ukuran penyebaran data yang paling sederhana. Cara menghitungnya adalah dengan mencari selisih antara nilai terbesar (maksimum) dan nilai terkecil (minimum) di dalam kumpulan data tersebut.\r\nBerikut adalah langkah perhitungannya :\r\n1. Cari nilai terbesar (Maksimum) => Dari data di atas, nilai terbesarnya adalah 300.\r\n2. Cari nilai terkecil (Minimum) => Dari data di atas, nilai terkecilnya adalah 50.\r\n3. Hitung jangkauannya menggunakan rumus =>\r\nRange = Nilai Maksimum - Nilai Minimum\r\nRange = 300 - 50 = 250', 10),
(53, 1, 'Mudah', 'Rata-rata dari nilai data tunggal : 15 dan 25 adalah ...', '15', '20', '22', '25', 'B', 'Untuk menghitung nilai rata-rata (mean) dari kelompok data tunggal, kita menggunakan rumus dasar yaitu menjumlahkan semua nilai data kemudian membaginya dengan jumlah total data yang ada.\r\nBerikut adalah langkah perhitungannya :\r\n1. Jumlahkan seluruh nilai data => 15 + 25 = 40.\r\n2. Hitung banyaknya data (n) => ada 2 buah angka (n = 2).\r\n3. Bagi hasil penjumlahan dengan banyaknya data => \r\nMean = 40/2 = 20', 10),
(54, 1, 'Mudah', 'Urutan data terkecil ke terbesar: 2, 4, 6, 8. Yang menjadi angka dasar rumus mencari nilai median adalah ...', '2 dan 4', '2 dan 8', '6 dan 8', '4 dan 6', 'D', 'Jumlah data pada soal adalah genap, yaitu sebanyak 4 angka (n = 4). Jika jumlah data genap, kita tidak bisa langsung menunjuk satu angka tunggal di tengah. Kita harus mengambil dua angka yang berada tepat di tengah-tengah kelompok data, lalu merata-ratakannya. \r\nPada deret data 2, [4, 6], 8, dua angka yang mengapit posisi tengah tersebut adalah 4 dan 6. Untuk mencari nilai mediannya, kedua angka dasar ini dijumlahkan lalu dibagi dua :\r\nMedian = 4+6/2 = 10/2 =5', 10),
(55, 1, 'Mudah', 'Berapakah jangkauan dari deret data angka kembar: 7, 7, 7, 7, 7?', '0', '1', '7', '35', 'A', 'Jangkauan (range) dihitung dengan mencari selisih antara nilai terbesar (maksimum) dan nilai terkecil (minimum) di dalam kumpulan data. Karakteristik khusus dari deret angka kembar atau data homogen (semua angkanya sama) adalah nilai maksimum dan minimumnya sama persis.\r\n- Nilai terbesar (maksimum) => 7\r\n- Nilai terkecil (minimum) => 7\r\n\r\nJika dimasukkan ke dalam rumus jangkauan :\r\nRange = Nilai Maksimum - Nilai Minimum \r\nRange = 7 - 7 = 0', 10),
(56, 1, 'Sedang', 'Grafik berbentuk diagram garis sangat tidak cocok digunakan untuk menampilkan data berupa ...', 'Perkembangan suhu tubuh pasien dari jam ke jam', 'Tren jumlah penduduk dari tahun ke tahun', 'Jenis kerjaan orang tua dan murid di suatu kelas', 'Fluktuasi harga emas bulanan', 'C', 'Diagram garis dirancang khusus untuk menyajikan data yang sifatnya kontinu (berkelanjutan) dan bertujuan untuk melacak tren atau perubahan nilai dari waktu ke waktu (time series data).\r\nSementara itu, jenis pekerjaan (seperti PNS, Karyawan Swasta, Wiraswasta, TNI/Polri) merupakan data kategorikal/kualitatif yang tidak memiliki hubungan urutan waktu kronologis. \r\nJenis pekerjaan lebih tepat disajikan menggunakan Diagram Batang (untuk membandingkan jumlah antar-kategori) atau Diagram Lingkaran (untuk melihat persentase proporsi kelompok).', 10),
(57, 1, 'Sedang', 'Jika nilai terbesar adalah 50 dan jangkauannya adalah 35, berapakah nilai terkecil data tersebut?', '15', '20', '25', '35', 'A', 'Rumus dasar untuk mencari jangkauan (range) data adalah nilai terbesar dikurangi nilai terkecil.\r\n            Jangkauan = Nilai Terbesar - Nilai Terkecil\r\n\r\nJika kita masukkan angka yang diketahui dari soal ke dalam rumus :\r\n              35 = 50 - Nilai Terkecil\r\n\r\nUntuk mencari nilai terkecil, kita bisa memindahkan posisinya secara matematika :\r\n              Nilai Terkecil = 50 - 35 = 15', 10),
(58, 1, 'Sedang', 'Seorang pedagang membeli barang seharga Rp 200.000 dan menjualnya kembali seharga Rp 240.000. Berapa persentase keuntungan yang diperoleh pedagang tersebut?', '10%', '15%', '20%', '25%', 'C', '1. Hitung besar keuntungan => Keuntungan = Harga Jual - Harga Beli\r\n                                                    Keuntungan = Rp 240.000 - Rp 200.000 \r\n                                                                         = Rp 40.000\r\n2. Hitung persentase keuntungan => \r\n    Persentase Keuntungan = (Besar Keuntungan) / (Harga Beli) x 100%\r\n    Persentase Keuntungan = (40.000) / (200.000) x 100%\r\n                                           = 1/5 x 100% = 20%', 10),
(59, 1, 'Sedang', 'Dari 500 responden di suatu distrik, 12 persen di antaranya adalah lansia. Berapa jumlah lansia di distrik tersebut?', '50 orang', '60 orang', '70 orang', '80 orang', 'B', 'Untuk menghitung jumlah riil berdasarkan persentase yang diketahui dari total populasi/sampel, kita menggunakan rumus matematika dasar berikut :\r\n          Jumlah Objek = Persentase x Total Responden\r\n\r\n1. Total responden (n) => 500 orang\r\n2. Persentase lansia => 12% (12/100 = 0,12)\r\n3. Langkah perhitungan =>\r\n    Jumlah Warga Lansia = 12/100 x 500\r\n    Jumlah Warga Lansia = 12 x 5 = 60\r\n\r\nJadi, terdapat 60 warga lansia di kecamatan tersebut.', 10),
(60, 1, 'Mudah', 'Operasi Hitung Campuran Hasil dari (24 x 5) + (180 / 4) - 35 adalah ...', '110', '120', '130', '140', 'C', 'Berdasarkan aturan operasi hitung campuran (Kabataku : Kali, Bagi, Tambah, Kurang), operasi di dalam tanda kurung harus diselesaikan terlebih dahulu.\r\n1. Selesaikan operasi perkalian pertama => \r\n    24 x 5 = 120\r\n2. Selesaikan operasi pembagian kedua =>\r\n    180/4 = 45\r\n3. Gabungkan hasil ke dalam persamaan (operasi penjumlahan)   \r\n    => 120 + 45 = 165\r\n4. Selesaikan operasi terakhir (pengurangan) =>\r\n     165 - 35 = 130', 10),
(61, 1, 'Sedang', 'Perhitungan Rata-rata (Mean) Data jumlah anggota keluarga dari 5 rumah tangga adalah : 3, 5, 4, 6, 2. \r\nBerapakah rata-rata jumlah anggota keluarga per rumah tangga?', '3 orang', '4 orang', '5 orang', '6 orang', 'B', 'Untuk mencari nilai rata-rata (mean) dari kelompok data tunggal, kita menggunakan rumus menjumlahkan semua nilai data lalu membaginya dengan jumlah total rumah tangga.\r\n1. Jumlahkan seluruh nilai data =>\r\n    3 + 5 + 4+ 6+ 2 = 20\r\n2. Hitung banyaknya data (n) => ada 5 rumah tangga (n = 5)\r\n3. Bagi hasil penjumlahan dengan banyaknya data =>\r\n    Mean = 20/5 = 4\r\n\r\nJadi, rata-rata jumlah anggota keluarga per rumah tangga adalah 4 orang.', 10),
(62, 1, 'Mudah', 'Diketahui bahwa data umur 7 anak di bawah lima tahun di suatu posyandu adalah: 3, 1, 4, 2, 5, 3, 2 (dalam tahun). \r\nMedian dari data tersebut adalah ...', '2 tahun', '2,5 tahun', '3 tahun', '4 tahun', 'C', 'Untuk mencari nilai median (nilai tengah) dari sekumpulan data acak, langkah awal yang mutlak harus dilakukan adalah mengurutkan data tersebut dari nilai terkecil ke terbesar.\r\n1. Urutkan data dari yang terkecil ke terbesar =>\r\n     1, 2, 2, 3, 3, 4, 5\r\n2. Hitung banyaknya data (n) => ada 7 anak balita (n = 7, jumlah data ganjil)\r\n3. Tentukan posisi nilai tengah (Median) =>\r\n    karena jumlah datanya ganjil, posisi Median berada tepat di tengah-tengah   \r\n    kelompok data, yaitu data pada urutan ke-4.\r\n   - Data ke-1 = 1\r\n   - Data ke-2 = 2\r\n   - Data ke-3 = 2\r\n   - Data ke-4 = 3 (nilai tengah)\r\n   - Data ke-5 = 3\r\n   - Data ke-6 = 4\r\n   - Data ke-7 = 5\r\n\r\nJadi, Median dari data usia anak balita tersebut adalah 3 tahun.', 10),
(63, 1, 'Sulit', 'Seorang petugas lapangan mampu mencatat 15 kepala keluarga dalam 3 jam. Jika ia bekerja dengan kecepatan yang sama selama 7 jam, berapa banyak kepala keluarga yang dapat dihitung?', '30 kepala keluarga', '35 kepala keluarga', '40 kepala keluarga', '45 kepala keluarga', 'B', 'Soal ini diselesaikan menggunakan prinsip Perbandingan Senilai (proporsi langsung). Semakin lama waktu petugas tersebut bekerja, maka semakin banyak pula jumlah kepala keluarga (KK) yang bisa didata.\r\n1. Cari kecepatan pendataan per jam => \r\n     Kemampuan per jam = 15 KK/3 jam = 5 KK per jam\r\n2. Hitung total hasil pendataan selama 7 jam =>\r\n     Total KK yang didata = 5 KK/jam x 7 jam = 35 KK\r\n\r\nMenggunakan Rumus Perbandingan :\r\nX1/Y1 = X2/Y2 = 15/3 = X2/7\r\nX2 = 15x7/3 = 5 x 7 = 35', 10),
(64, 1, 'Mudah', 'Operasi Desimal Sederhana Hasil dari 0,75 + 1,25 x 0,4 adalah ...', '0,80', '1,25', '1,50', '2,00', 'B', 'Berdasarkan aturan operasi hitung campuran (Kabataku : Kali, Bagi, Tambah, Kurang), operasi perkalian harus dikerjakan terlebih dahulu sebelum operasi penjumlahan, kecuali jika ada tanda kurung.\r\n1. Selesaikan operasi perkalian terlebih dahulu =>\r\n     1,25 x 0,4 = 0,5\r\n2. Selesaikan operasi penjumlahan =>\r\n     0,75 + 0,5 = 1,25', 10),
(65, 1, 'Sulit', 'Sebuah proyek survei ditargetkan untuk diselesaikan dalam 12 hari oleh 6 anggota staf. Jika survei harus diselesaikan dalam 8 hari, berapa total staf yang dibutuhkan?', '8 orang', '9 orang', '10 orang', '12 orang', 'B', 'Karakteristik dari perbandingan berbalik nilai adalah jika salah satu variabel turun (dalam hal ini jumlah hari pengerjaan dipercepat), maka variabel lainnya justru harus naik (jumlah petugas harus bertambah agar survei selesai tepat waktu).\r\nPada perbandingan berbalik nilai, hasil kali antar-variabel selalu bernilai konstan (sama), karena total beban pekerjaan proyek tidak berubah.\r\n1. Gunakan rumus perbandingan berbalik nilai =>\r\n    X1 x Y1 = X2 x Y2\r\n    - X1 (Petugas awal) = 6 orang\r\n    - Y1 (Waktu awal) = 12 hari\r\n    - X2 ( Total petugas baru yang dicari) = ?\r\n    - Y2 (Waktu baru) = 8 hari\r\n\r\n2. Masukkan angka ke dalam rumus =>\r\n    6 x 12 = X2 x 8\r\n    72 = X2 x 8\r\n\r\n3. Cari nilai X2 => X2 = 72/8 = 9 orang\r\n\r\nJadi, total petugas yang dibutuhkan untuk menyelesaikan survei dalam waktu 8 hari adalah 9 orang.', 10),
(66, 1, 'Sulit', 'Seorang petugas penghitung suara mengendarai sepeda motor ke sebuah desa terpencil dengan kecepatan rata-rata 40 km/jam. Jika jarak ke desa tersebut adalah 60 km, berapa lama waktu yang dibutuhkan petugas tersebut untuk menempuh perjalanan?', '1 jam 15 menit', '1 jam 30 menit', '1 jam 45 menit', '2 jam', 'B', 'Untuk menyelesaikan soal yang berkaitan dengan hubungan antara kecepatan, jarak, dan waktu, kita menggunakan rumus fisika dasar :\r\n                     Waktu = Jarak/Kecepatan\r\n\r\n1. Identifikasi nilai yang diketahui =>\r\n    - Jarak (s) = 60 km\r\n    - Kecepatan (v) = 40 km/jam\r\n2. Masukkan angka ke dalam rumus :\r\n     Waktu = 60 km/(40 km/jam) = 1,5 jam\r\n3. Konversikan nilai desimal jam ke dalam satuan menit =>\r\n     1 jam = 60 menit\r\n     0,5 jam = 0,5 x 60 menit = 30 menit\r\n\r\nJadi, total waktu perjalanan yang dibutuhkan oleh petugas tersebut adalah 1 jam 30 menit.', 10),
(67, 1, 'Sulit', 'Perbandingan jumlah petani jagung dan petani padi di Desa Makmur adalah 3 : 5. Jika jumlah total petani dari kedua komoditas tersebut adalah 240 orang, berapa selisih antara jumlah petani padi dan petani jagung?', '30 orang', '40 orang', '60 orang', '120 orang', 'C', 'Soal ini diselesaikan menggunakan konsep Rasio (Perbandingan) Berdasarkan Total Anggota. Kita diminta mencari selisih jumlah riil kedua kelompok tani tersebut.\r\n1. Identifikasi rasio yang diketahui =>\r\n    - Rasio Petani Jagung = 3\r\n    - Rasio Petani Padi = 5\r\n2. Hitung total rasio dan selisih rasio =>\r\n    - Total rasio = 3 + 5 = 8 \r\n    - Selisih rasio = 5 - 3 = 2\r\n3. Hitung selisih jumlah petani nyata =>\r\n      Selisih Petani = Selisih Rasio/Total Rasio x Total Seluruh Petani\r\n      Selisih Petani = 2/8 x 240 = 1/4 x 240 = 60 orang\r\n\r\nJumlah Petani Jagung = 3/8 x 240 = 90 orang\r\nJumlah Petani Padi = 5/8 x 240 = 150 orang\r\nSelisihnya = 150 - 90 = 60 orang', 10),
(68, 1, 'Sulit', 'Pembagian dan Rasio Rasio jumlah petani jagung dan petani padi di Desa Makmur adalah 3 : 5. Jika jumlah seluruh petani dari kedua komoditas tersebut adalah 240 orang, berapa selisih jumlah petani padi dan jagung?', '30 orang', '40 orang', '60 orang', '120 orang', 'C', 'Soal ini diselesaikan menggunakan konsep Rasio (Perbandingan) Berdasarkan Total Anggota. Kita diminta mencari selisih jumlah riil kedua kelompok tani tersebut.\r\n1. Identifikasi rasio yang diketahui =>\r\n    - Rasio Petani Jagung = 3\r\n    - Rasio Petani Padi = 5\r\n2. Hitung total rasio dan selisih rasio =>\r\n    - Total rasio = 3 + 5 = 8 \r\n    - Selisih rasio = 5 - 3 = 2\r\n3. Hitung selisih jumlah petani nyata =>\r\n      Selisih Petani = Selisih Rasio/Total Rasio x Total Seluruh Petani\r\n      Selisih Petani = 2/8 x 240 = 1/4 x 240 = 60 orang\r\n\r\nJumlah Petani Jagung = 3/8 x 240 = 90 orang\r\nJumlah Petani Padi = 5/8 x 240 = 150 orang\r\nSelisihnya = 150 - 90 = 60 orang', 10),
(69, 3, 'Sedang', 'Dalam penghitungan Indeks Demokrasi Indonesia (IDI) yang rilis datanya dikelola secara berkala oleh BPS, pengumpulan data tidak hanya mengandalkan kuesioner wawancara lapangan. BPS juga menggunakan metode penelaahan mendalam terhadap berita media massa lokal/nasional serta dokumen resmi pemerintah.\r\nMetode pengumpulan data sekunder berbasis teks tersebut dalam metodologi BPS dikenal dengan istilah  ...', 'Focus Group Discussion (FGD)', 'Content Analysis (Analisis Konten/Media)', 'Desk Research (Studi Literatur)', 'Deep Interview (Wawancara Mendalam)', 'B', 'Dalam metodologi penghitungan Indeks Demokrasi Indonesia (IDI) oleh BPS, Analisis Konten adalah metode ilmiah yang digunakan untuk mengumpulkan data sekunder dengan cara menyisir, mengkaji, dan mengodekan (coding) informasi dari berita media massa (surat kabar, portal berita) serta dokumen hukum resmi (seperti Perda atau SK Kepala Daerah). Metode ini bertujuan untuk merekam peristiwa riil terkait indikator kebebasan sipil, hak-hak politik, dan lembaga demokrasi secara objektif dan sistematis dari teks media.', 10),
(70, 1, 'Sedang', 'Dua kali total populasi RT 01 ditambah 50 orang sama dengan total populasi RT 02. Jika populasi RT 02 adalah 250 orang, berapa total populasi RT 01?', '80 orang', '100 orang', '120 orang', '150 orang', 'B', '1. Misalkan =>\r\n    - Populasi RT 01 = x\r\n    - Populasi RT 02 = 250 orang\r\n2. Susun persamaannya => \"dua kali total populasi RT 01 ditambah 50 orang \r\n    sama dengan total populasi RT 02\"\r\n           2x + 50 = 250\r\n3. Pindahkan angka 50 ke ruas kanan => 2x = 150 - 50\r\n                                                                   2x = 200\r\n4. Cari nilai x (populasi RT 01) => x = 200/2 = 100 orang\r\n\r\nJadi, total populasi di RT 01 adalah 100 orang.', 10),
(71, 1, 'Sulit', 'Azam meminjam uang sebesar Rp2.000.000 di koperasi. Jika jumlah uang yang harus dibayar   Azam   setelah   meminjam   selama   15   bulan   adalah   Rp2.245.000,   besar persentase bunga pinjaman per tahun adalah ..', '9,8%', '10%', '12%', '13%', 'A', '1. Hitung total bunga (dalam Rp) => \r\n    Total Bunga = Total yang Dibayar - Pinjaman Awal\r\n    Total Bunga = Rp 2.245.000 - Rp 2.000.000 = Rp 245.000\r\n    Nominal Rp 245.000 ini adalah akumulasi bunga selama 15 bulan..\r\n2. Hitung bunga untuk jangka waktu 1 tahun (12 bulan) =>\r\n    Bunga 1 Tahun = 12 bulan/15 bulan x Total Bunga\r\n    Bunga 1 Tahun = 12/15 x 245.000 = 4/5 x 245.000 = Rp 196.000\r\n3. Hitung persentase bunga/tahun =>\r\n    Persentase Bunga = (Bunga 1 Tahun) / (Pinjaman Awal) x 100%\r\n    Persentase Bunga = 196/2.000 x 100% = 19,6/2 = 9,8%', 10),
(72, 1, 'Mudah', 'Jika sebuah data memiliki distribusi simetris, maka apa yang dapat dikatakan tentang modusnya?', 'Data tidak memiliki modus', 'Modus sama dengan Median', 'Modus lebih kecil daripada Median', '85', 'B', 'Pada data yang memiliki distribusi simetris sempurna (seperti Distribusi Normal atau kurva berbentuk lonceng), nilai ketiga ukuran pemusatan datanya akan saling berhimpit tepat di titik tengah kurva. \r\nHal ini menghasilkan karakteristik matematis yang baku, yaitu :\r\n           Mean = Median = Modus\r\n\r\nKarena nilai ketiganya sama besar, maka otomatis nilai Modus akan sama dengan Median (dan juga sama dengan nilai Mean-nya).', 10),
(73, 2, 'Mudah', 'Singkatan Lembaga Kepanjangan resmi dari instansi pemerintah nonkementerian BPS adalah ...', 'Badan Pusat Statistik', 'Badan Pengelola Statistik', 'Balai Pusat Statistik', 'Barometer Pusat Statistik', 'A', 'Berdasarkan Undang-Undang Nomor 16 Tahun 1997 tentang Statistik, nama resmi nomenklatur lembaga ini diubah dari yang semula bernama \"Biro Pusat Statistik\" menjadi Badan Pusat Statistik (BPS) [PPID BPS]. Perubahan kata \"Biro\" menjadi \"Badan\" menegaskan penguatan status kelembagaannya menjadi sebuah Lembaga Pemerintah Non Kementerian (LPNK) yang mandiri.', 10),
(74, 2, 'Mudah', 'Structure Kepemimpinan Badan Pusat Statistik (BPS) merupakan instansi vertikal yang dalam menjalankan tugas pokoknya bertanggung jawab langsung kepada ...', 'Menteri Dalam Negeri', 'Menteri Keuangan', 'Presiden', 'Gubernur', 'C', 'Berdasarkan Undang-Undang Nomor 16 Tahun 1997 tentang Statistik, Badan Pusat Statistik (BPS) ditetapkan sebagai sebuah Lembaga Pemerintah NonKementerian (LPNK) [PPID BPS]. Konsekuensi dari status kelembagaan ini adalah BPS sebagai instansi vertikal bertanggung jawab secara langsung kepada Presiden melalui menteri atau pejabat yang mengoordinasikannya.', 10),
(75, 2, 'Mudah', 'Istilah Teknis Lapangan Petugas yang bertanggung jawab melakukan pengawasan dan pemeriksaan terhadap hasil isian kuisioner oleh pencacah lapangan disebut ...', 'PCL (Petugas Pencacah Lapangan)', 'PML (Petugas Pemeriksa Lapangan)', 'Koseka (Koordinator Sensus Kecamatan)', 'Kepala BPS Kabupaten', 'B', 'Dalam manajemen lapangan kegiatan sensus atau survei BPS, PML (Petugas Pemeriksa Lapangan) atau terkadang disebut juga Pengawas Lapangan memiliki tugas pokok untuk mengawasi jalannya pengumpulan data serta melakukan pemeriksaan (editing/coding) secara saksama terhadap kualitas isian kuesioner yang telah dikumpulkan oleh tim pencacah di bawahnya. PML memastikan tidak ada data yang terlewat, tidak konsisten, atau salah tulis sebelum dokumen diserahkan ke tingkat kecamatan/kabupaten.', 10),
(76, 2, 'Mudah', 'Siapakah yang dimaksud dengan subjek \"Responden\" dalam kegiatan pengumpulan data atau survei BPS?', 'Orang atau lembaga yang memberikan informasi/data kepada petugas', 'Petugas yang melakukan pencacahan di lapangan', 'Pegawai organik BPS yang mengolah data komputer', 'Masyarakat umum yang membaca berita statistik', 'A', 'Dalam metodologi penelitian dan kegiatan perstatistikan (termasuk survei/sensus BPS), Responden adalah individu, kepala keluarga, anggota rumah tangga, kelompok orang, atau pihak lembaga/perusahaan yang terpilih menjadi objek penelitian dan bersedia memberikan jawaban, data, atau informasi yang diperlukan kepada petugas lapangan melalui instrumen wawancara atau pengisian kuesioner.', 10),
(77, 2, 'Mudah', 'Jenis Data Statistik Data yang diperoleh BPS secara langsung melalui proses wawancara tatap muka dengan responden di lapangan disebut sebagai ...', 'Data Sekunder', 'Data Tersier', 'Data Primer', 'Data Pendukung', 'C', 'Berdasarkan cara memperolehnya, data primer adalah jenis data yang dikumpulkan secara langsung dari sumber pertamanya (objek yang diteliti) oleh peneliti atau instansi penyelenggara [DQLab]. Ketika petugas lapangan BPS terjun langsung ke rumah-rumah atau perusahaan untuk melakukan wawancara tatap muka menggunakan kuesioner, data yang didapatkan tersebut berstatus sebagai data mentah utama yang segar dan orisinal (data primer).', 10),
(78, 2, 'Mudah', 'Istilah Susenas Salah satu survei rutin bulanan/tahunan BPS yang sangat penting untuk mengukur tingkat kemiskinan dan kesejahteraan sosial di Indonesia adalah ...', 'Sakernas', 'Susenas', 'SPHS', 'SBH', 'B', 'Susenas adalah singkatan dari Survei Sosial Ekonomi Nasional. Survei ini merupakan salah satu pilar utama pengumpulan data rutin oleh BPS yang sangat penting untuk menghasilkan indikator kesejahteraan rakyat. \r\nMelalui modul pengeluaran dan konsumsi rumah tangga yang ada di dalam Susenas, BPS dapat menghitung angka rata-rata pengeluaran penduduk per kapita yang menjadi dasar utama penetapan Garis Kemiskinan, Tingkat Kemiskinan (Kemiskinan Makro), serta angka ketimpangan pendapatan (Gini Ratio) di Indonesia.', 10),
(79, 2, 'Mudah', 'Istilah Ketenagakerjaan Survei yang dilakukan oleh BPS untuk mengumpulkan data mengenai tingkat pengangguran dan kondisi ketenagakerjaan di Indonesia adalah ...', 'Susenas', 'Sakernas', 'Sensus Ekonomi', 'Potensi Desa (Podes)', 'B', 'akernas merupakan singkatan dari Survei Angkatan Kerja Nasional. Survei berkala yang diselenggarakan oleh BPS ini dirancang khusus untuk mengumpulkan data mengenai indikator-indikator ketenagakerjaan di Indonesia. Hasil akhir yang paling krusial dari Sakernas adalah angka Tingkat Pengangguran Terbuka (TPT), jumlah angkatan kerja aktif, tingkat partisipasi angkatan kerja (TPAK), serta status pekerjaan utama masyarakat', 10),
(80, 1, 'Sedang', 'Deret Angka Lanjutan Kelanjutan dari deret pola angka berikut:  5, 10, 8, 16, 14, 28, ... adalah', '24', '26', '30', '32', 'B', 'Soal deret angka ini menggunakan pola operasi hitung campuran yang berulang secara bergantian (selang-seling). Jika kita bedah pergerakan angkanya dari kiri ke kanan, polanya adalah dikali dua (x2) kemudian dikurang dua (-2)\r\n1. 5 ke 10 => dikali 2 (5 x 2 = 10)\r\n2. 10 ke 8 => dikurang 2 (10 - 2 = 8)\r\n3. 8 ke 16 => dikali 2 (8 x 2 = 16)\r\n4. 16 ke 14 => dikurang 2 (16 -2 = 14)\r\n5. 14 ke 28 => dikali 2 (14 x 2 = 28)\r\n\r\nMengikuti urutan pola di atas, setelah operasi dikali 2 maka langkah selanjutnya yang mutlak harus dilakukan adalah dikurang 2 :\r\n28 ke angka berikutnya => dikurang 2 (28 - 2 = 26)', 10),
(81, 2, 'Mudah', 'Wilayah kerja terkecil yang digunakan oleh BPS sebagai dasar pembagian wilayah pendataan disebut dengan ...', 'RT/RW', 'Blok Sensus', 'Wilayah Administratif', 'Kelurahan', 'B', 'Dalam setiap pelaksanaan survei maupun sensus, Badan Pusat Statistik (BPS) menggunakan Blok Sensus (BS) sebagai wilayah kerja statistik (wilkerstat) terkecil. Blok Sensus merupakan bagian dari wilayah suatu desa atau kelurahan yang dibentuk berdasarkan hamparan geografis dengan batasan alam maupun buatan yang jelas (seperti jalan, sungai, atau batas RT/RW). \r\nSecara rata-rata, satu Blok Sensus dirancang untuk mencakup sekitar 80 hingga 120 muatan bangunan rumah tangga agar beban kerja petugas pencacah di lapangan menjadi terukur dan merata.', 10);
INSERT INTO `soal` (`id`, `kategori_id`, `level`, `pertanyaan`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `jawaban`, `pembahasan`, `xp`) VALUES
(82, 2, 'Sulit', 'Seorang petugas BPS mendata 40 rumah tangga di suatu kelurahan. Jika 60% dari rumah tangga tersebut memiliki kendaraan bermotor, berapa jumlah rumah tangga yang memiliki kendaraan bermotor?', '16', '24', '28', '32', 'B', '1. Identifikasi Data =>\r\n    - Total seluruh rumah tangga (N) = 40\r\n    - Persentase pemilik kendaraan (P) = 60%\r\n2. Ubah persen ke pecahan => 60% = 60/100 = 0,6\r\n3. Kalikan total dengan pecahan =>\r\n   Jumlah rumah tangga = 40 x 60/100 = 2400/100 = 24\r\n\r\nBerdasarkan perhitungan di atas, maka jumlah rumah tangga di kelurahan tersebut yang memiliki kendaraan bermotor adalah 24 rumah tangga.', 10),
(83, 1, 'Sulit', 'Dalam suatu kelas yang terdiri dari 30 siswa, nilai rata-rata ujian Matematika adalah 70. Jika nilai rata-rata siswa pria 75 dan nilai rata-rata siswa wanita 65, berapa jumlah siswa wanita di kelas tersebut?', '12', '15', '18', '20', 'B', '1. Membuat persamaan total siswa => \r\n    misalkan jumlah siswa laki-laki adalah Nm dan \r\n    jumlah siswa perempuan adalah Nf. \r\n    Total siswa di dalam kelas adalah 30 anak.\r\n              Nm + Nf = 30      =>       Nm = 30 - Nf\r\n2. Menggunakan rumus rata-rata gabungan =>\r\n     X = (Nm * Xm) + (Nf * Xf) / Nm + Nf\r\n    Substitusikan nilai yang diketahui dari soal\r\n    (X = 70, Xm = 75, Xf = 65, dan Nm + Nf = 30)\r\n    70 = (30 - Nf) * 75 + (Nf * 65) / 30\r\n3. Menyelesaikan operasi aljabar => 70 * 30 = 2250 - 75Nf + 65Nf\r\n                                                                2100 = 2250 - 10Nf\r\n                                                                10Nf = 2250 - 2100 = 150\r\n                                                                    Nf = 150/10 = 15\r\n\r\nBerdasarkan perhitungan aljabar di atas, jumlah siswa wanita di kelas tersebut adalah 15 siswa.', 10),
(84, 2, 'Mudah', 'Apa kepanjangan dari PAPI sebagai salah satu metode pengumpulan data BPS?', 'Paper and Pencil Interviewing', 'Personal Area Private Information', 'Paper and Program Integration', 'Pendataan Administrasi Penduduk Indonesia', 'A', 'PAPI (Paper and Pencil Interviewing) adalah metode pengumpulan data konvensional atau tradisional di mana petugas lapangan (pencacah) mewawancarai responden secara tatap muka dan mencatat setiap jawaban menggunakan kuesioner fisik berbahan kertas dan pensil/pulpen.', 10),
(85, 2, 'Mudah', 'Satuan wilayah kerja terkecil dari hasil pemetaan yang digunakan oleh BPS untuk mendata suatu wilayah disebut ...', 'Blok Sensus', 'Wilayah Kerja Statistik (Wilkerstat)', 'Area Sampel', 'Satuan Lingkungan Setempat', 'A', 'Blok Sensus (BS) => Merupakan satuan wilayah kerja statistik terkecil hasil pemetaan BPS yang digunakan sebagai dasar pencacahan sensus dan kerangka sampel survei. Satu desa/kelurahan akan dibagi habis menjadi beberapa Blok Sensus berdasarkan muatan jumlah bangunan atau rumah tangga di dalamnya.', 10),
(86, 1, 'Mudah', 'Tentukan angka selanjutnya dari deret berikut: 3, 5, 9, 17, 33, ...', '55', '60', '65', '70', 'C', 'Untuk menemukan angka selanjutnya, kita perlu melihat pola perubahan (selisih) dari satu angka ke angka berikutnya :\r\n1. Dari 3 ke 5 => ditambah 2 (2 pangkat 1)\r\n2. Dari 5 ke 9 => ditambah 4 (2 pangkat 2)\r\n3. dari 9 ke 17 => ditambah 8 (2 pangkat 3)\r\n4. Dari 17 ke 33 => ditambah 16 (2 pangkat 4)\r\n\r\nPola penambahannya adalah kelipatan 2 (perkalian dua dari selisih sebelumnya atau bilangan berpangkat dua). Maka, untuk mencari angka setelah 33, kita harus menambahkan angka 32 (yaitu 16 x 2 atau 2 pangkat 5) => 33 + 32 = 65', 10),
(87, 1, 'Sulit', 'Jika 5 orang pekerja dapat menyelesaikan pemetaan 10 Blok Sensus dalam waktu 4 hari, berapa hari yang dibutuhkan oleh 8 orang pekerja untuk menyelesaikan 16 Blok Sensus?', '3 hari', '4 hari', '5 hari', '6 hari', 'B', '1. Menghitung kecepatan kerja/orang => \r\n    Beban Kerja (Blok Sensus) = Pekerja x Waktu (Hari) x Kecepatan Konstan (k)\r\n    10 = 5 x 4 x k = 20k\r\n     k = 10/20 = 0,5 Blok sensus per orang per hari\r\n2. Menghitung waktu kondisi kedua => 16 = 8 x H x 0,5 \r\n                                                                 16 = 4 x H\r\n                                                                  H = 16/4 = 4 hari\r\n3. Rumus berpasangan => P1 x H1 / B1 = P2 x H2/B2\r\n                                            5 x 4/10 = 8 x H2/16 \r\n                                            20/10 = 8H2/16\r\n                                                   2 = 8H2/16\r\n                                            2 x 16 = 8H2\r\n    32 = 8H2 => H2 = 32/8 = 4 hari\r\n\r\nBerdasarkan perhitungan di atas, waktu yang dibutuhkan oleh 8 orang pekerja untuk menyelesaikan 16 Blok Sensus adalah 4 hari.', 10),
(88, 1, 'Mudah', 'Manakah di antara pilihan berikut yang termasuk ke dalam jenis data nominal?', 'Tingkat pendidikan (SD, SMP, SMA)', 'Jenis kelamin (Laki-laki, Perempuan)', 'Pendapatan bulanan (Rupiah)', 'Suhu udara (Celcius)', 'B', 'Data Nominal (Skala Nominal) => Data kategori yang berfungsi hanya untuk membedakan, melabeli, atau mengelompokkan objek tanpa adanya tingkatan, peringkat, atau urutan hierarki.\r\nContoh : Jenis kelamin (Laki-laki dan Perempuan). Posisi keduanya setara, tidak ada yang lebih tinggi atau lebih rendah tingkatannya. \r\nContoh lainnya adalah agama, warna mata, dan status pernikahan.', 10),
(89, 1, 'Sedang', 'Jika diketahui nilai median dari data terurut :  3, 5, x, 8, 10, 11 adalah 7.5, berapakah nilai x?', '6', '6,5', '7', '7,5', 'C', 'Median adalah nilai tengah dari suatu data yang telah diurutkan.\r\n1. Tentukan banyaknya data (n) => \r\n    Jumlah data dalam deret (3, 5, x, 8, 10, 11) adalah n= 6 (jumlah data genap)\r\n2. Gunakan rumus Median data genap => Median = Data ke-3 + Data ke-4 / 2\r\n3. Cari nilai x => 7,5 = x + 8 / 2 \r\n                           7,5 x 2 = x + 8\r\n                                  15 = x + 8\r\n                                    x = 15 - 8 = 7', 10),
(90, 2, 'Sedang', 'Apa singkatan dari CAPI yang menjadi salah satu metode modern pengumpulan data lapangan BPS menggunakan gawai/gadget?', 'Computer Assisted Personal Interviewing', 'Center of Area Population Integration', 'Central Application for Project Input', 'Core Advanced Population Indicator', 'A', 'CAPI (Computer Assisted Personal Interviewing) => adalah metode pengumpulan data lapangan di mana petugas (pencacah) melakukan wawancara langsung (tatap muka) dengan responden, namun proses perekaman atau pengisian jawaban tidak lagi menggunakan kertas melainkan langsung diinput ke dalam gawai/gadget (seperti smartphone, tablet, atau laptop) melalui aplikasi khusus.', 10),
(91, 1, 'Mudah', 'Diketahui data nilai ujian matematika sekelompok siswa : 70, 80, 60, 90, 85, 75, 65. Berapakah nilai median dari data tersebut?', '75', '70', '80', '85', 'A', '1. Urutkan data dari yang terkecil ke terbesar => \r\n    Data asli : 70, 80, 60, 90, 85, 75, 65\r\n    Data setelah diurutkan : 60, 65, 70, 75, 80, 85, 90\r\n2. Tentukan banyaknya data (n) => jumlah data (n) = 7 (ganjil)\r\n3. Cari posisi nilai tengah (Median) => n + 1 / 2 = 7 + 1 / 2 = Data ke-4\r\n    - Data ke-1 : 60\r\n    - Data ke-2 : 65\r\n    - Data ke-3 : 70\r\n    - Data ke-4 : 75 (Nilai Tengah)\r\n    - Data ke-5 : 80\r\n    - Data ke-6 : 85\r\n    - Data ke-7 : 90\r\n\r\nNilai yang berada tepat di tengah-tengah kelompok data tersebut adalah 75.', 10),
(92, 2, 'Sedang', 'Dalam survei berskala besar, BPS biasanya membagi wilayah menjadi beberapa strata (misalnya tingkat provinsi atau kabupaten) sebelum melakukan pengambilan sampel. Metode sampling ini disebut...', 'Simple Random Sampling', 'Cluster Sampling', 'Stratified Random Sampling', 'Quota Sampling', 'C', 'Dalam survei berskala besar seperti yang dilakukan oleh Badan Pusat Statistik (BPS), populasi sering kali bersifat sangat heterogen (beragam). Untuk memastikan setiap kelompok populasi terwakili dengan baik dan adil, digunakanlah metode Stratified Random Sampling.', 10),
(93, 1, 'Mudah', 'Nilai probabilitas (peluang) dari suatu kejadian yang tidak mungkin terjadi sama sekali adalah ...', '0,5', '0', '1', '100', 'B', 'Peluang = 0 (Kejadian Mustahil) => Berarti kejadian tersebut sama sekali tidak mungkin terjadi.\r\nContoh : Peluang munculnya angka 7 pada pelemparan sebuah dadu bersisi enam standar, atau peluang matahari terbit dari arah barat secara normal.', 10),
(94, 2, 'Mudah', 'Kegiatan pengumpulan data yang dilakukan oleh BPS secara menyeluruh kepada seluruh populasi di wilayah Indonesia setiap 10 tahun sekali untuk mencatat kependudukan disebut ...', 'Survei Sosial Ekonomi Nasional (Susenas)', 'Registrasi Penduduk', 'Sensus Penduduk (SP)', 'Survei Antar Sensus (SUPAS)', 'C', 'Sensus Penduduk (SP) =>  Dilaksanakan pada tahun bermutasi akhiran 0 (nol), seperti SP2010 dan SP2020. Tujuannya adalah mengumpulkan data dasar kependudukan di seluruh wilayah Indonesia', 10),
(95, 2, 'Sedang', 'Menurut konsep ketenagakerjaan BPS, penduduk usia kerja yang tidak bekerja sama sekali tetapi sedang mencari pekerjaan aktif atau sedang mempersiapkan usaha baru dikategorikan sebagai ...', 'Pengangguran terbuka', 'Bukan angkatan kerja', 'Setelah pengangguran', 'Pekerja paruh waktu', 'A', 'Berdasarkan indikator ketenagakerjaan resmi BPS, kelompok Pengangguran Terbuka diklasifikasikan ke dalam 4 kriteria utama :\r\n1. Mempersiapkan Usaha : Penduduk yang tidak bekerja tetapi sedang \r\n    melakukan persiapan untuk membuka usaha/pekerjaan baru.\r\n2. Merasa Tidak Mungkin Mendapat Pekerjaan : Penduduk yang tidak bekerja \r\n    dan tidak mencari kerja karena merasa putus asa atau tidak mungkin \r\n    memperoleh pekerjaan (discouraged workers).\r\n3. Sudah Diterima Bekerja : Penduduk yang tidak bekerja dan tidak mencari \r\n    kerja karena sudah diterima bekerja tetapi belum mulai melakukan pekerjaan \r\n    tersebut (future starts).', 10),
(96, 2, 'Mudah', 'Instrumen atau dokumen utama berupa daftar pertanyaan terstruktur yang digunakan oleh petugas pencacah lapangan (PPL) untuk mewawancarai responden disebut ...', 'Standar Operasional Prosedur (SOP)', 'Peta Blok Sensus', 'Buku Pedoman Pencacah', 'Kuesioner', 'D', 'Dalam setiap kegiatan pengumpulan data lapangan yang dilakukan oleh Badan Pusat Statistik (BPS), baik sensus maupun survei, Kuesioner memegang peranan krusial sebagai alat pengumpul data utama.', 10),
(97, 2, 'Sedang', 'Jika seorang petugas BPS (PPL) datang ke sebuah rumah tangga terpilih sampel, namun kepala rumah tangga menolak untuk diwawancara karena merasa terganggu, tindakan awal yang paling tepat dilakukan adalah ...', 'Memaksa responden untuk menjawab karena pendataan dilindungi oleh Undang-Undang', 'Melakukan pendekatan persuasif, menunjukkan surat tugas resmi, dan menjelaskan manfaat data bagi pemerintah', 'Meninggalkan rumah tersebut dan menggantinya dengan rumah tetangga lainnya secara acak', 'Melaporkan responden kepada pihak kepolisian setempat atas tuduhan menghalangi program pemerintah', 'B', 'Tindakan awal yang paling tepat dilakukan oleh petugas lapangan (PPL) adalah menjelaskan kembali tujuan, manfaat, dan dasar hukum penjaminan kerahasiaan data secara persuasif dan santun.', 10),
(98, 3, 'Mudah', 'Indeks Pembangunan Manusia (IPM) merupakan salah satu indikator strategis yang dirilis oleh BPS. Manakah di bawah ini yang bukan merupakan dimensi dasar pembentuk IPM?', 'Umur panjang dan hidup sehat', 'Pengetahuan / Pendidikan', 'Standar hidup layak', 'Tingkat kebahagiaan dan kriminalitas', 'D', 'Tingkat kebahagiaan dan kriminalitas tidak termasuk ke dalam variabel perhitungan IPM. BPS mengukur indikator kebahagiaan secara terpisah melalui rilis statistik khusus yang dinamakan Indeks Kebahagiaan, sedangkan data kriminalitas dihimpun dalam statistik Keamanan dan Kriminalitas.', 10),
(99, 2, 'Sedang', 'Dalam melakukan pendaftaran bangunan dan rumah tangga (Pencacahan Lapangan), petugas BPS sering menemukan kasus \"Rumah Tangga Khusus\". Manakah contoh di bawah ini yang dikategorikan sebagai rumah tangga khusus?', 'Keluarga inti yang tinggal di rumah kontrakan', 'Sekelompok mahasiswa yang ngekos dan mengurus makannya sendiri-sendiri', 'Penghuni panti asuhan, barak militer, atau lembaga pemasyarakatan', 'Pengusaha kaya yang memiliki asisten rumah tangga tinggal serumah', 'C', 'Rumah Tangga Khusus adalah sekelompok orang yang tinggal bersama di suatu tempat atau lembaga, di mana pengelolaan akomodasi dan pengurusan kebutuhan konsumsi sehari-harinya diatur oleh suatu yayasan, badan, lembaga, atau pengurus.\r\nContoh : Penghuni panti asuhan, barak militer (tangsi), lembaga pemasyarakatan (lapas), rumah tahanan (rutan), asrama mahasiswa/perawat yang dikelola yayasan, serta kelompok orang yang mondok dengan makan (indekos) berjumlah 10 orang atau lebih.', 10),
(100, 2, 'Sedang', 'Apa yang dimaksud dengan konsep \"Keberadaan Responden Berdasarkan De Jure\" dalam Sensus Penduduk BPS?', 'Pencatatan penduduk berdasarkan tempat mereka ditemukan saat hari pencacahan', 'Pencatatan penduduk berdasarkan tempat tinggal resminya (domisili hukum/KTP)', 'Pencatatan khusus bagi warga negara asing yang bekerja di Indonesia', 'Pendataan penduduk yang hanya memiliki pekerjaan tetap', 'B', 'Konsep De Jure adalah pencatatan atau pencacahan penduduk yang disesuaikan dengan tempat tinggal resmi atau legalitas hukumnya (biasanya dibuktikan dengan dokumen resmi seperti Kartu Tanda Penduduk/KTP atau Kartu Keluarga/KK) [Sensus Penduduk].', 10),
(101, 1, 'Sedang', 'Jika roda A berputar 9 kali maka roda B berputar 24 kali. Jika roda B berputar 32 kali, berapa kali roda A berputar?', '12 kali', '15 kali', '16 kali', '18 kali', 'A', '1. Rumus perbandingan senilai => \r\n    Putaran A1 / Putaran B1 = Putaran A2 / Putaran B2\r\n2. Masukkan angka => A1 = 9, \r\n                                      B1 = 24, \r\n                                      B2 = 32, \r\n                                      A2 = ?\r\n    9/24 = A2/32\r\n3. Sederhanakan pecahan & kalikan silang => 3/8 = A2/32\r\n                                                                          8 x A2 = 3 x 32 = 96\r\n                                                                                A2 = 96/8 = 12\r\n\r\nJika roda B berputar sebanyak 32 kali, maka roda A berputar sebanyak 12 kali.', 10),
(102, 1, 'Sulit', 'Sebuah survei pertanian mencatat 40 petani menanam padi, 25 petani menanam jagung, dan 12 petani menanam keduanya. Jika ada 7 petani yang tidak menanam padi maupun jagung, berapa total petani yang disurvei di desa tersebut?', '53 orang', '60 orang', '67 orang', '72 orang', 'B', '1. Hitung petani yang HANYA menanam satu jenis tanaman => \r\n    - Petani yang menanam padi keseluruhan = 40 orang\r\n    - Petani yang menanam padi dan jagung (kedua-duanya) = 12 orang\r\n    - Petani yang hanya menanam padi = 40 - 12 = 28 orang\r\n    - Petani yang menanam jagung keseluruhan = 25 orang\r\n    - Petani yang hanya menanam jagung = 25 - 12 = 13 orang\r\n2. Hitung total petani yang disurvei => \r\n    Total Petani = (Hanya Padi) + (Hanya Jagung) + (keduanya) + (Tidak  \r\n                           Keduanya)\r\n    Total Petani = 28 + 13 + 12 + 7 = 60 orang', 10),
(103, 3, 'Mudah', 'Indeks Harga Konsumen (IHK) digunakan oleh BPS sebagai indikator utama untuk mengukur ...', 'Pertumbuhan ekonomi', 'Tingkat inflasi', 'Tingkat Kemiskinan', 'Nilai tukar rupiah', 'B', 'Indeks Harga Konsumen (IHK) mencatat rata-rata perubahan harga eceran paket barang dan jasa yang dikonsumsi rumah tangga dari waktu ke waktu.\r\nPersentase perubahan IHK yang bernilai positif inilah yang digunakan BPS untuk menetapkan angka tingkat inflasi nasional maupun daerah.', 10),
(104, 1, 'Sedang', 'Dalam sebuah kotak terdapat 4 bola merah dan 6 bola biru. Jika diambil satu bola secara acak, berapakah peluang terambilnya bola merah?', '4/6', '4/10', '6/10', '1/4', 'B', '1. Jumlah bola merah (kejadian target) => 4 bola\r\n2. Total seluruh bola dalam kotak (ruang sampel) =>\r\n     4 bola merah + 6 bola biru = 10 bola\r\n3. Peluang terambil bola merah => Jumlah bola merah / Total seluruh bola \r\n                                                    = 4/10', 10),
(105, 2, 'Mudah', 'Pada pelaksanaan sensus atau survei lapangan BPS, dokumen atau daftar pertanyaan terstruktur yang digunakan petugas untuk mewawancarai responden disebut. ..', 'Buku Pedoman', 'Peta Blok Sensus', 'Kuesioner', 'Dokumen Administrasi', 'C', 'Kuesioner merupakan instrumen atau dokumen utama yang berisi daftar pertanyaan terstruktur untuk diisi oleh petugas saat mewawancarai responden agar data yang dihasilkan seragam dan standar.', 10),
(106, 2, 'Mudah', 'Dalam Survei Pertanian, BPS menggunakan metode Kerangka Sampel Area (KSA). Teknologi utama yang diandalkan dalam metode KSA untuk mendata luas panen adalah ...', 'Citra satelit', 'Telepon seluler', 'Kuesioner cetak', 'Data rekapitulasi desa', 'A', 'Metode KSA sangat mengandalkan teknologi foto citra satelit resolusi tinggi dari badan pemerintah terkait untuk menyusun kerangka peta (sampling frame), menetapkan koordinat batas hamparan lahan baku sawah, serta membagi wilayah menjadi peta grid/segmen sampel yang presisi secara objektif sebelum petugas turun ke lapangan.', 10),
(107, 1, 'Sulit', 'Sebuah survei ketenagakerjaan mengambil sampel 120 orang. Diketahui peluang seseorang berstatus menganggur di wilayah tersebut adalah 0,15. Berapa perkiraan jumlah orang yang menganggur dari sampel tersebut?', '15 orang', '18 orang', '20 orang', '22 orang', 'B', 'Rumus => E(X) = n x P(A)\r\nE(X) = Perkiraan jumlah kejadian atau nilai harapan (jumlah orang yang  \r\n           menganggur).\r\nn = Total jumlah sampel yang diambil.\r\nP(A)= Peluang terjadinya kejadian tersebut.\r\n\r\n1. Identifikasi Data dari Soal => \r\n    Jumlah sampel (n) = 120 orang\r\n    Peluang menganggur (P(A)) = 0,15\r\n2. Hitung Nilai Harapannya => \r\n    Perkiraan menganggur = 120 x 0,15 = 120 x 15/100 = 1800/100 = 18\r\n\r\nBerdasarkan perhitungan peluang di atas, perkiraan jumlah orang yang berstatus menganggur dari total sampel tersebut adalah 18 orang.', 10),
(108, 2, 'Mudah', 'Perbedaan mendasar antara metode Sensus dan Survei yang dilakukan oleh BPS terletak pada ...', 'Sensus menggunakan kuesioner, sedangkan survei hanya wawancara lisan', 'Sensus dilakukan untuk seluruh anggota populasi, sedangkan survei hanya mengambil sampel representatif', 'Sensus diawasi langsung oleh pemerintah pusat, sedangkan survei dikelola swasta', 'Sensus mengukur data kualitatif, sedangkan survei khusus data kuantitatif', 'B', 'Perbedaan paling mendasar dan utama antara sensus dan survei terletak pada cakupan objek penelitiannya (subjek). Sensus adalah pencacahan lengkap yang mengumpulkan data dari seluruh elemen populasi tanpa terkecuali (misalnya Sensus Penduduk untuk semua warga negara). Sementara itu, survei hanya mengambil sebagian kecil dari populasi yang disebut sampel representatif (contoh) untuk mewakili gambaran populasi tersebut', 10),
(109, 2, 'Sedang', 'Apa yang menjadi tujuan utama dilakukannya uji hipotesis dalam sebuah analisis statistik deskriptif/inferensial di BPS?', 'Mengubah data kualitatif lapangan menjadi data numerik komputer', 'Mempercepat durasi kontrak petugas entry data di kantor kabupaten', 'Membuktikan kebenaran statistik atau menguji signifikansi dugaan awal terhadap populasi', 'Menentukan besaran anggaran honorarium bagi para mitra lapangan', 'C', 'Uji hipotesis merupakan bagian dari statistika inferensial. Tujuan utamanya adalah untuk menentukan apakah dugaan/pernyataan awal (hipotesis) mengenai karakteristik populasi didukung secara signifikan oleh data sampel yang dikumpulkan. Di BPS, pengujian ini sangat krusial untuk memastikan bahwa kesimpulan, tren, atau indikator yang diperoleh dari sampel survei memang mencerminkan kondisi populasi yang sebenarnya dan bukan karena faktor kebetulan (error sampel).', 10),
(110, 2, 'Sedang', 'Pada logo resmi BPS, terdapat tiga warna utama berbentuk grafik batang yang merepresentasikan tiga pilar sensus nasional. Warna Orange pada logo tersebut secara spesifik melambangkan kegiatan ...', 'Sensus Penduduk', 'Sensus Pertanian', 'Sensus Ekonomi', 'Sensus Perumahan', 'C', 'Warna Orange \r\n=> Melambangkan kegiatan Sensus Ekonomi (diselenggarakan 10 tahun sekali pada tahun berakhiran angka 6, seperti yang dilaksanakan saat ini pada Sensus Ekonomi 2026).', 10),
(111, 2, 'Sulit', 'Seorang Mitra Statistik BPS menolak menerima pemberian uang tip atau bingkisan dari responden setelah melakukan wawancara, karena ia tahu hal tersebut melanggar aturan dan dapat merusak objektivitas data. Sikap petugas ini mencerminkan penerapan Core Values BerAKHLAK, khususnya pada pilar ...', 'Berorientasi Pelayanan', 'Akuntabel', 'Kompeten', 'Adaptif', 'B', 'Pilar Akuntabel dalam Core Values BerAKHLAK memiliki salah satu panduan perilaku (kode etik) utama yang berbunyi : \r\n\"Melaksanakan tugas dengan jujur, bertanggung jawab, cermat, disiplin, dan berintegritas tinggi\" serta \"Tidak menyalahgunakan kewenangan jabatan\". Menolak uang tip atau bingkisan (gratifikasi) dari responden demi menjaga objektivitas data dan mematuhi aturan adalah wujud nyata dari sikap integritas dan tanggung jawab (akuntabilitas) seorang petugas BPS.', 10),
(112, 3, 'Sedang', 'Dalam rilis Berita Resmi Statistik (BRS) mengenai ketenagakerjaan, BPS menghitung Tingkat Partisipasi Angkatan Kerja (TPAK). Formula atau rumus yang digunakan untuk menghitung TPAK adalah ...', '(Jumlah Pengangguran / Jumlah Penduduk Usia Kerja) × 100%', '(Jumlah Angkatan Kerja / Jumlah Penduduk Usia Kerja) × 100%', '(Jumlah Penduduk Bekerja / Total Seluruh Penduduk) × 100%', '(Jumlah Pengangguran / Jumlah Angkatan Kerja) × 100%', 'B', 'Tingkat Partisipasi Angkatan Kerja (TPAK) adalah indikator ekonomi yang menunjukkan persentase penduduk usia kerja yang aktif secara ekonomi dalam pasar kerja (baik yang sedang bekerja maupun yang sedang mencari pekerjaan/menganggur).\r\n- Angkatan Kerja = Penduduk bekerja + Pengangguran terbuka.\r\n- Penduduk Usia Kerja = Penduduk berusia 15 tahun ke atas', 10),
(113, 2, 'Sedang', 'Kode unik yang dicantumkan pada kuesioner BPS untuk mengidentifikasi identitas wilayah responden (mulai dari kode provinsi, kabupaten/kota, kecamatan, desa/kelurahan, hingga nomor urut sampel) secara sistematis disebut sebagai ...', 'Kode Etik Petugas', 'Nomor Identitas Pegawai (NIP)', 'ID Wilayah Sensus', 'Metadata / Wilkerstat ID', 'D', 'Kode unik tersebut mengacu langsung pada sistem Wilkerstat (Wilayah Kerja Statistik) milik BPS yang mengintegrasikan data wilayah (Provinsi hingga Blok Sensus) dengan peta digital. Kode ini juga berfungsi sebagai Metadata (data yang menjelaskan data lain) karena menjadi identitas terstandar yang memberi informasi rinci kepada sistem komputer mengenai lokasi geografis sampel data agar tidak tertukar saat diolah di pusat.', 10),
(114, 2, 'Sulit', 'Dalam kegiatan survei lapangan BPS, petugas sering kali menggunakan metode CAPI (Computer Assisted Personal Interviewing) untuk mengumpulkan data dari responden menggunakan gawai/tablet. Mengapa metode CAPI dianggap lebih unggul dibandingkan metode tradisional PAPI (Paper and Pencil Interviewing)?', 'CAPI menghemat anggaran belanja karena gawai yang dibeli petugas langsung menjadi hak milik responden', 'CAPI mempercepat proses data entry dan cleaning karena data yang diinput langsung masuk ke pelayan data (server) secara real-time disertai validasi otomatis', 'CAPI menjamin responden tidak perlu menjawab pertanyaan kuesioner yang sensitif', 'CAPI otomatis mengubah data kualitatif responden menjadi grafik lingkaran yang dapat dicetak langsung di lapangan', 'B', 'Metode CAPI memangkas jalur birokrasi pengolahan data tradisional. Pengisian data langsung ke aplikasi gawai membuat BPS tidak perlu lagi melakukan pemindaian (scanning) atau pengetikan ulang (data entry) dari kertas kuesioner. Selain itu, aplikasi CAPI sudah ditanami logika rule/validation otomatis (seperti peringatan jika ada jawaban yang tidak logis), sehingga proses pembersihan data (data cleaning) berjalan seketika saat wawancara berlangsung di lapangan.', 10),
(115, 2, 'Sedang', 'Dalam pengumpulan data harga komoditas pokok di pasar tradisional, BPS kini mengimplementasikan aplikasi berbasis web/mobile bernama SP2HP. Apa fungsi utama dari sistem/aplikasi ini dalam manajemen data BPS?', 'Memantau kehadiran dan posisi GPS petugas pencacah secara real-time', 'Melakukan pemantauan dan pelaporan perkembangan harga barang kebutuhan pokok dan barang penting secara digital', 'Menghitung otomatis formulasi angka kemiskinan makro tingkat nasional', 'Mengganti seluruh kuesioner kertas pada pelaksanaan Sensus Penduduk', 'B', 'SP2HP merupakan singkatan dari Sistem Pemantauan Pasar Kebutuhan Pokok. Fungsi utama aplikasi mobile/web ini memang dirancang khusus untuk memodernisasi cara kerja BPS dalam mencatat data harga komoditas (seperti beras, cabai, minyak goreng) secara harian atau mingguan dari pasar tradisional secara digital. Data real-time ini sangat penting untuk mendeteksi perubahan harga dan menghitung angka inflasi daerah dengan cepat.', 10),
(116, 1, 'Sedang', 'Perhatikan pola pasangan angka dalam tanda kurung berikut : \r\n(4, 9, 25) ➔ (6, 11, 27) ➔ (9, 14, 30) ➔ (13, 18, X)\r\nBerapakah nilai X yang paling tepat untuk melengkapi pola di atas?', '32', '33', '34', '35', 'C', 'Jika kita mengamati pergerakan angka pada posisi ketiga (angka paling kanan) di setiap tanda kurung, terdapat pola penjumlahan yang konstan dan berurutan :\r\n1. Dari tanda kurung pertama ke kedua => 25 ➔ 27 (ditambah 2)\r\n2. Dari tanda kurung kedua ke ketiga => 27 ➔ 30 (ditambah 3)\r\n3. Dari tanda kurung ketiga ke keempat => 30 ➔ x (mengikuti pola, harus ditambah 4)\r\n\r\nMaka, nilai x = 30 + 4 = 34', 10),
(117, 1, 'Sulit', 'Dari hasil seleksi administrasi di sebuah kabupaten, terdapat 3 calon petugas pria dan 3 calon petugas wanita yang memiliki nilai tes sama kuat. Jika pengawas hanya membutuhkan 2 orang petugas untuk mengisi 1 Blok Sensus secara acak, berapakah peluang terpilihnya keduanya adalah petugas wanita?', '1/5', '1/4', '1/3', '1/2', 'A', 'Untuk menghitung peluang ini, kita menggunakan rumus kombinasi karena urutan pemilihan petugas tidak diperhatikan :\r\n1. Langkah 1 (Menghitung Total Kemungkinan/Semesta) =>\r\n    Total ada 6 calon petugas (3 pria + 3 wanita). Jumlah cara memilih 2 orang dari total 6 orang secara acak adalah : C(6, 2) = 6 x 5 / 2 x 1 = 15 cara\r\n2. Langkah 2 (Menghitung Kejadian yang Diinginkan) =>\r\n    Kita ingin memilih 2 orang yang keduanya adalah wanita dari total 3 calon wanita yang tersedia. Jumlah caranya adalah : C(3, 2) = 3 x 2 / 2 x 1 = 3 cara\r\n3. Langkah 3 (Menghitung Peluang) =>\r\n    Peluang terpilih keduanya wanita adalah jumlah kejadian yang diinginkan dibagi dengan total kemungkinan : P = 3/15 = 1/5', 10),
(118, 3, 'Sedang', 'Pendapatan nasional yang dihitung berdasarkan nilai pasar dari seluruh barang dan jasa akhir yang diproduksi oleh faktor-faktor produksi yang dimiliki oleh warga negara suatu negara (baik yang tinggal di dalam negeri maupun di luar negeri) dalam periode tertentu disebut ...', 'Produk Domestik Bruto (PDB)', 'Produk Nasional Bruto (PNB / GNP)', 'Produk Domestik Regional Bruto (PDRB)', 'Pendapatan Per Kapita Nominal', 'B', 'Kunci utama dari definisi soal di atas terletak pada frasa \"dimiliki oleh warga negara\", baik mereka tinggal di dalam negeri maupun di luar negeri. PNB atau Gross National Product (GNP) adalah indikator ekonomi yang menghitung nilai produksi berdasarkan faktor kewarganegaraan (nationality). Jadi, pendapatan tenaga kerja Indonesia (TKI) di luar negeri ikut dihitung ke dalam PNB Indonesia, sedangkan pendapatan warga negara asing (WNA) yang bekerja di dalam wilayah Indonesia dikeluarkan dari perhitungan ini.', 10),
(119, 2, 'Sedang', 'Menurut Undang-Undang No. 16 Tahun 1997 tentang Statistik, BPS wajib menjamin kerahasiaan data individu responden. Jika seorang petugas membocorkan rincian aset atau omzet pendapatan suatu perusahaan sampel kepada pihak luar, sanksi apa yang dapat dijatuhkan?', 'Tidak ada sanksi selama data tersebut tidak disalahgunakan untuk kriminal', 'Teguran lisan dari kepala desa setempat', 'Sanksi pidana kurungan dan/atau denda finansial sesuai ketentuan hukum', 'Pemotongan honorarium bulanan sebesar 50%', 'C', 'Berdasarkan Pasal 37 UU No. 16 Tahun 1997 tentang Statistik, tindakan petugas statistik yang sengaja membocorkan atau memberikan keterangan data individu responden (baik omzet usaha, aset, maupun identitas pribadi) kepada pihak luar yang tidak berwenang merupakan bentuk pelanggaran kejahatan hukum. Petugas yang melanggar ketentuan kerahasiaan ini dapat dijatuhi hukuman pidana penjara paling lama 1 tahun 6 bulan dan denda paling banyak Rp15.000.000,00 (lima belas juta rupiah).', 10),
(120, 1, 'Sulit', 'Jika semua nilai dari suatu kumpulan data pengamatan dikurangi dengan sebuah konstanta positif yang sama sebesar K, bagaimana perubahan yang terjadi pada nilai Rata-rata (Mean) dan Varians (Ragam) dari data tersebut?', 'Rata-rata berkurang sebesar K, Varians tetap tidak berubah', 'Rata-rata tetap, Varians berkurang sebesar K', 'Rata-rata berkurang sebesar K, Varians berkurang sebesar K²', 'Baik Rata-rata maupun Varians tidak mengalami perubahan', 'A', 'Berdasarkan sifat-sifat ukuran pemusatan dan penyebaran data dalam statistik : \r\n1. Rata-rata (Mean) adalah ukuran pemusatan yang sangat sensitif terhadap perubahan setiap nilai data. Jika semua data digeser (dikurangi) sebesar bilangan konstan  \r\n    K, maka titik pusat atau nilai rata-rata barunya otomatis akan ikut bergeser turun sejauh nilai  K tersebut.\r\n2. Varians (Ragam) adalah ukuran penyebaran yang menghitung seberapa jauh jarak antardata terhadap rata-ratanya. Karena semua data dikurangi dengan angka \r\n    yang sama besar (K), jarak atau celah relatif antar-angka dalam kumpulan data tersebut tidak berubah sama sekali. Oleh karena itu, tingkat kerapatan data (varians) \r\n    nilainya tetap sama seperti semula.', 10),
(121, 1, 'Sulit', 'Sebuah tim pengolah data di kantor BPS Kabupaten terdiri dari pegawai senior dan mitra kerja. Total upah untuk 3 orang pegawai senior dan 4 orang mitra kerja dalam sehari adalah Rp950.000. Jika upah 2 orang pegawai senior sama dengan upah 3 orang mitra kerja, berapakah upah untuk 1 orang pegawai senior dalam sehari?', 'Rp100.000', 'Rp120.000', 'Rp150.000', 'Rp180.000', 'C', 'Kita dapat menyelesaikan soal ini menggunakan metode Sistem Persamaan Linear Dua Variabel (SPLDV).\r\n1. Misalkan upah 1 Pegawai Senior = S\r\n2. Misalkan upah 1 Mitra Kerja = M\r\n\r\nDari data soal, kita mendapatkan dua persamaan dasar :\r\n1. 2S = 3M ➔ M = 2/3 S (Persamaan 1)\r\n2. 3S + 4M = Total Upah (Persamaan 2)\r\n\r\nMaka upah Mitra (M) adalah 2/3 x 150.000 = Rp 100.000\r\n\r\nHubungan ini memenuhi syarat perbandingan di lapangan di mana upah 2 pegawai senior (2 x 150.000 = 300.000) tepat sama nilainya dengan upah 3 orang mitra kerja (3 x 100.000 = 300.000).', 10),
(122, 3, 'Sedang', 'BPS mengukur tingkat kebahagiaan masyarakat melalui Indeks Kebahagiaan yang dirilis secara berkala. Di bawah ini yang merupakan salah satu dari 3 dimensi utama penyusun Indeks Kebahagiaan BPS adalah ...', 'Dimensi Kepuasan Hidup (Life Satisfaction)', 'Dimensi Tingkat Religiositas Fisik', 'Dimensi Kebebasan Politik dan Keamanan Nasional', 'Dimensi Konsumsi Barang Mewah', 'A', 'Menurut Metadata Indikator Statistik BPS, Indeks Kebahagiaan yang dirilis oleh BPS merupakan indeks komposit yang tersusun atas 3 dimensi utama =>\r\n1. Dimensi Kepuasan Hidup (Life Satisfaction) (Mencakup sub-dimensi personal dan sosial seperti pendidikan, pekerjaan, pendapatan, rumah, hubungan sosial, dan \r\n    keadaan lingkungan).\r\n2. Dimensi Perasaan (Affect) (Mencakup perasaan senang, tidak cemas, dan tidak tertekan).\r\n3. Dimensi Makna Hidup (Eudaimonia) (Mencakup kemandirian, penguasaan lingkungan, pengembangan diri, tujuan hidup, dan penerimaan diri).', 10),
(123, 2, 'Sulit', 'Saat melakukan proses cleaning data hasil survei industri, seorang petugas menemukan isian kuesioner sebagai berikut :\r\nKolom A (Status Kepemilikan): Usaha Mandiri/Perorangan\r\nKolom B (Bentuk Badan Hukum): Perseroan Terbuka (Tbk)\r\nMengapa data di atas dinyatakan tidak konsisten (error logical)?', 'Karena badan hukum Tbk tidak boleh bergerak di bidang industri', 'Karena usaha mandiri/perorangan tidak mungkin berbentuk badan hukum Perseroan Terbuka (Tbk)', 'Karena kolom B harusnya diisi dengan jumlah omzet tahunan perusahaan', 'Karena nama pemilik usaha tidak dicantumkan di kedua kolom tersebut', 'B', 'Dalam aturan hukum bisnis dan metodologi survei ekonomi BPS, status kepemilikan dan bentuk badan hukum memiliki hubungan logika yang mutlak. Usaha Mandiri/Perorangan adalah usaha yang modalnya dimiliki oleh satu orang individu secara pribadi. Sementara itu, Perseroan Terbuka (Tbk) adalah perusahaan berbadan hukum PT yang sebagian sahamnya sudah dijual kepada masyarakat luas di bursa efek. Suatu usaha tidak bisa berstatus milik perorangan sekaligus menjadi perusahaan publik (Tbk) di saat yang sama. Isian ini menunjukkan adanya kesalahan pengisian (rule validation error) yang harus diperbaiki pada tahap cleaning data.', 10),
(124, 1, 'Sedang', 'Dalam kuesioner Survei Sosial Ekonomi Nasional (Susenas) BPS, terdapat pertanyaan mengenai tingkat pendidikan tertinggi yang ditamatkan oleh responden (1. SD, 2. SMP, 3. SMA, 4. Perguruan Tinggi). \r\nDitinjau dari ilmu statistik, variabel tingkat pendidikan tersebut termasuk ke dalam jenis skala pengukuran data ...', 'Nominal', 'Ordinal', 'Interval', 'Rasio', 'B', 'Skala ordinal adalah skala pengukuran data yang tidak hanya berfungsi untuk mengelompokkan data ke dalam kategori, tetapi juga memiliki unsur tingkatan, urutan, atau jenjang (order) di antara kategori-kategori tersebut. Variabel tingkat pendidikan (SD, SMP, SMA, Perguruan Tinggi) merupakan contoh klasik skala ordinal karena terdapat urutan logis di mana lulusan SMP memiliki jenjang pendidikan yang lebih tinggi daripada SD, lulusan SMA lebih tinggi daripada SMP, dan seterusnya.', 10),
(125, 1, 'Sulit', 'Sebuah tim pencacah lapangan BPS yang terdiri dari 3 orang ditargetkan untuk menyelesaikan pendataan di 12 Blok Sensus dalam waktu 4 hari. Karena salah satu petugas mendadak jatuh sakit pada hari pertama, tim tersebut kini hanya tersisa 2 orang. \r\nDengan asumsi kecepatan kerja setiap orang sama, berapa harikah yang dibutuhkan oleh 2 orang petugas tersebut untuk menyelesaikan target 12 Blok Sensus yang sama?', '5 hari', '6 hari', '7 hari', '8 hari', 'B', 'Kasus ini diselesaikan menggunakan konsep Perbandingan Berbalik Nilai. Karena jumlah Blok Sensus yang dikerjakan tetap sama (12 Blok Sensus), hubungan antara jumlah petugas dengan waktu penyelesaian berbanding terbalik (makin sedikit petugas, makin banyak waktu yang dibutuhkan).\r\n- Waktu awal (H1) = 4 hari\r\n- Petugas awal (P1) = 3 orang\r\n- Petugas tersisa (P2) = 2 orang\r\n\r\nRumus Perbandingan Berbalik Nilai => P1 x H1 = P2 x H2\r\n                                                                    3 x 4 = 2 x H2\r\n                                                                        12 = 2 x H2\r\n                                                                         H2 = 12/2 = 6 hari', 10),
(126, 3, 'Sulit', 'BPS rutin merilis data tentang Nilai Tukar Petani (NTP) setiap bulan. Indikator ini digunakan untuk mengukur tingkat kesejahteraan petani di suatu wilayah.\r\nSecara konsep, jika nilai NTP suatu daerah berada di angka 95 (NTP < 100), maka kesimpulan yang paling tepat tentang kondisi petani di daerah tersebut adalah ...', 'Petani mengalami surplus/keuntungan karena indeks harga yang diterima lebih besar daripada yang dibayar', 'Petani berada dalam kondisi impas/seimbang antara pendapatan dan pengeluaran', 'Petani mengalami defisit karena kenaikan harga barang yang dibayar lebih cepat daripada kenaikan harga hasil produksinya', 'Petani tidak melakukan aktivitas produksi sama sekali pada bulan tersebut', 'C', 'Nilai Tukar Petani (NTP) dihitung berdasarkan rasio antara Indeks Harga yang Diterima Petani (It) dengan Indeks Harga yang Dibayar Petani (lb), dikalikan 100.\r\nJika NTP < 100 (dalam soal nilainya 95), artinya indeks harga yang harus dibayar petani (untuk konsumsi rumah tangga dan biaya produksi) lebih tinggi daripada indeks harga yang diterima dari penjualan hasil panennya. Kondisi ini menunjukkan bahwa kemampuan daya beli petani menurun dan mereka mengalami defisit/kerugian.', 10),
(127, 1, 'Mudah', 'Dalam metodologi survei BPS, kesalahan atau selisih yang timbul karena pendataan hanya dilakukan pada sebagian populasi (sampel) dan bukan pada keseluruhan objek populasi disebut sebagai ...', 'Non-Sampling Error', 'Measurement Error', 'Sampling Error', 'Response Error', 'C', 'Sesuai dengan prinsip dasar metodologi survei BPS, sampling error adalah variabilitas atau selisih numerik yang terjadi secara alami murni karena peneliti hanya mengamati sebagian elemen populasi (sampel) dan bukan keseluruhan populasi. Sifat kesalahan ini tidak bisa dihindari dalam sebuah metode survei sampel, namun nilainya dapat diperkecil dengan cara memperbesar ukuran sampel atau menggunakan teknik penarikan sampel yang representatif.', 10),
(128, 1, 'Sedang', 'Seorang fungsional statistisi di BPS menganalisis data pendapatan rumah tangga hasil survei di suatu wilayah. Setelah diplot ke dalam grafik, distribusi data tersebut menunjukkan bentuk Menjengker Kanan (Positively Skewed), di mana terdapat segelintir rumah tangga yang memiliki pendapatan sangat tinggi (ekstrem kanan) dibandingkan mayoritas warga lainnya.\r\nDalam kondisi distribusi data menjengker kanan seperti ini, hubungan antara nilai Mean (Rata-rata), Median (Nilai Tengah), dan Modus yang paling tepat adalah ...', 'Mean < Median < Modus', 'Mean = Median = Modus', 'Mean > Median > Modus', 'Median > Mean > Modus', 'C', 'Pada distribusi data yang menjengker kanan (positively skewed), ekor grafik memanjang ke arah kanan karena adanya nilai-nilai ekstrem yang sangat tinggi (dalam kasus ini, segelintir rumah tangga dengan pendapatan luar biasa besar).\r\n- Mean (Rata-rata) nilainya akan menjadi yang paling besar karena sifatnya yang sangat sensitif dan ikut tertarik ke arah kanan oleh angka-angka ekstrem tersebut.\r\n- Median (Nilai Tengah) posisinya cenderung lebih stabil di tengah karena hanya mengandalkan urutan posisi data, sehingga tidak terlalu terpengaruh oleh nilai \r\n   ekstrem.\r\n- Modus (Nilai yang Paling Sering Muncul) tetap berada di puncak kuruk (area kiri), mencerminkan pendapatan mayoritas warga yang berada di kelas bawah atau \r\n  menengah.\r\n\r\nOleh karena itu, urutan besaran nilainya secara matematis pasti membentuk pola => Mean > Median > Modus.', 10),
(129, 1, 'Sulit', 'Sebuah Kantor BPS Kabupaten harus mengirimkan delegasi berpasangan yang terdiri dari 1 orang Pengawas (PML) dan 1 orang Pencacah (PPL) untuk menghadiri rapat koordinasi nasional (Rakornas). \r\nJika di kantor tersebut tersedia 4 orang kandidat Pengawas (PML) yang kompeten dan 5 orang kandidat Pencacah (PPL) yang berpengalaman, berapa banyak variasi pasangan delegasi (PML - PPL) berbeda yang mungkin dibentuk?', '9 variasi pasangan', '12 variasi pasangan', '20 variasi pasangan', '40 variasi pasangan', 'C', 'Kasus pemilihan pasangan delegasi ini diselesaikan dengan menggunakan Aturan Perkalian (Kaidah Pencacahan) dasar dalam teori peluang. Karena delegasi harus terdiri dari 1 orang Pengawas (PML) dan 1 orang Pencacah (PPL), kita tinggal mengalikan jumlah kandidat yang tersedia dari masing-masing kelompok jabatan tersebut : Total Variasi Pasangan = Jumlah Kandidat PML x Jumlah Kandidat PPL\r\n  Total Variasi Pasangan = 4 x 5 = 20 variasi pasangan', 10),
(130, 3, 'Sedang', 'Dalam melakukan analisis demografi, BPS sering menggunakan indikator Rasio Ketergantungan (Dependency Ratio). Indikator ini sangat krusial untuk menganalisis kesiapan suatu wilayah dalam menghadapi masa Bonus Demografi.\r\nSecara formula, kelompok penduduk usia berapakah yang dikategorikan sebagai penduduk usia produktif (penyebut dalam rumus) oleh BPS?', '15 – 59 Tahun', '15 – 64 Tahun', '17 – 60 Tahun', '20 – 65 Tahun', 'B', 'Berdasarkan konsep standardisasi demografi resmi yang digunakan oleh BPS, Rasio Ketergantungan (Dependency Ratio) dihitung dengan membagi jumlah penduduk usia non-produktif dengan jumlah penduduk usia produktif, kemudian dikalikan 100.\r\nDalam formula ini, Penduduk Usia Produktif (yang diletakkan sebagai angka penyebut) mutlak didefinisikan sebagai penduduk yang berada pada rentang usia 15 hingga 64 tahun. Kelompok inilah yang dinilai secara ekonomi mampu menghasilkan barang atau jasa untuk menopang kelompok usia non-produktif (anak-anak usia 0–14 tahun dan lansia usia 65 tahun ke atas).', 10),
(131, 3, 'Sedang', 'Dalam merilis data pertumbuhan ekonomi atau inflasi bulanan, BPS sering menggunakan penyesuaian yang disebut Seasonal Adjustment (Penyesuaian Musiman). \r\nApa tujuan utama BPS melakukan penyesuaian musiman pada data time series ekonomi tersebut?', 'Menghilangkan efek fluktuasi rutin tahunan (seperti momen Lebaran atau Tahun Baru) agar tren ekonomi yang sebenarnya terlihat jelas', 'Memastikan jumlah sampel yang diambil di lapangan selalu sama di setiap bulannya', 'Menaikkan angka pertumbuhan ekonomi agar terlihat lebih tinggi dari realisasinya', 'Mengubah data makro menjadi data mikro agar mudah dipahami masyarakat awam', 'A', 'Data ekonomi bulanan atau triwulanan (time series) sangat sering dipengaruhi oleh efek musiman (seasonal effect) yang berulang pada waktu yang sama setiap tahun, misalnya lonjakan konsumsi saat Hari Raya Idulfitri, Natal, Tahun Baru, atau musim panen raya [A]. Tujuan utama dari Seasonal Adjustment (Penyesuaian Musiman) adalah untuk membersihkan dan membuang faktor gangguan rutin tahunan tersebut. Dengan hilangnya efek musiman, para pengambil kebijakan dan ekonom dapat melihat arah tren, siklus ekonomi, serta pertumbuhan yang murni dan objektif dari satu bulan ke bulan berikutnya (month-on-month).', 10),
(132, 2, 'Mudah', 'Saat pelaksanaan Sensus Ekonomi atau survei industri, BPS mengelompokkan jenis kegiatan ekonomi responden berdasarkan sebuah buku panduan standar yang berlaku nasional. Buku panduan tersebut memuat kode-kode kategori lapangan usaha (seperti Pertanian, Industri Pengolahan, Perdagangan, dll).\r\nApa nama buku standar klasifikasi yang digunakan BPS tersebut?', 'KBBI (Kamus Besar Bahasa Indonesia)', 'KBLI (Klasifikasi Baku Lapangan Usaha Indonesia)', 'KKNI (Kerangka Kualifikasi Nasional Indonesia)', 'KBLK (Klasifikasi Baku Komoditas Indonesia)', 'B', 'KBLI adalah sistem pengodean terstandar resmi yang diterbitkan dan dimutakhirkan oleh BPS untuk mengelompokkan aktivitas ekonomi/bisnis di Indonesia ke dalam kategori lapangan usaha yang homogen. Buku ini menjadi acuan mutlak nasional termasuk untuk perizinan usaha di sistem OSS agar terdapat keseragaman konsep saat BPS melakukan Sensus Ekonomi, sensus pertanian, maupun survei industri.', 10),
(133, 1, 'Sedang', 'Hasil kajian statistik sosial BPS menunjukkan hubungan antarvariabel berikut :\r\n1. Jika indeks kesehatan masyarakat meningkat, maka produktivitas tenaga kerja akan meningkat.\r\n2. Jika produktivitas tenaga kerja meningkat, maka Produk Domestik Bruto (PDB) per kapita akan tumbuh positif.\r\n\r\nFakta di lapangan menunjukkan bahwa saat ini PDB per kapita tidak tumbuh positif. Kesimpulan yang paling logis adalah ...', 'Indeks kesehatan masyarakat meningkat tetapi produktivitas tenaga kerja menurun', 'Produktivitas tenaga kerja meningkat tetapi indeks kesehatan masyarakat menurun', 'Indeks kesehatan masyarakat tidak mengalami peningkatan', 'Pemerintah harus mengubah metode penghitungan PDB per kapita', 'C', 'Soal logika ini diselesaikan menggunakan metode penarikan kesimpulan Modus Tollens dalam logika matematika (silogisme bertingkat). Misalkan :\r\n- p = = Indeks kesehatan masyarakat meningkat\r\n- q = Produktivitas tenaga kerja meningkat\r\n- r = PDB per kapita tumbuh positif\r\n- Dari premis pertama dan kedua, kita dapat menggabungkan hubungan sebab-akibat menjadi : Jika p maka r (Jika indeks kesehatan meningkat, maka PDB per kapita \r\n   tumbuh positif).\r\n- Fakta di lapangan memberikan premis penegasi : Negasi r (PDB per kapita tidak tumbuh positif).\r\n- Berdasarkan aturan Modus Tollens, jika akibatnya tidak terjadi (tidak r), maka penyebab awalnya juga pasti tidak terjadi (negasi p). Maka kesimpulan mutlaknya adalah \r\n   indeks kesehatan masyarakat tidak mengalami peningkatan.', 10),
(134, 1, 'Sedang', 'Di sebuah desa sampel Susenas BPS, terdapat 500 kepala keluarga (KK). Berdasarkan garis kemiskinan yang ditetapkan, tercatat 20% dari total KK di desa tersebut dikategorikan sebagai KK miskin. Setelah pemerintah menyalurkan bantuan modal usaha, 1/4 bagian dari KK miskin tersebut berhasil naik kelas dan tidak lagi dikategorikan sebagai KK miskin.\r\nBerapakah jumlah KK yang masih berada di bawah garis kemiskinan (tetap miskin) di desa tersebut?', '25 KK', '75 KK', '80 KK', '100 KK', 'B', '- Langkah 1 (Mencari total KK miskin awal) => Diketahui 20% dari total 500 KK di desa tersebut berstatus miskin.\r\n   KK Miskin Awal = 20% x 500 = 100 KK\r\n- Langkah 2 (Mencari jumlah KK yang naik kelas) => Diketahui 1/4 bagian dari KK miskin berhasil lepas dari kategori miskin setelah mendapat bantuan.\r\n   KK Naik Kelas = 1/4 x 100 = 25 KK\r\n- Langkah 3 (Mencari KK yang tetap berada di bawah garis kemiskinan) => Kurangi jumlah KK miskin awal dengan jumlah KK yang sudah naik kelas.\r\n   KK Tetap Miskin = 100 - 25 = 75 KK', 10),
(135, 2, 'Mudah', 'Pada pelaksanaan Sensus Penduduk, BPS menerapkan metode kombinasi di mana masyarakat dapat mengisikan data silsilah keluarga mereka secara mandiri melalui laman resmi internet tanpa perlu menunggu kedatangan petugas pencacah ke rumah\r\nDalam metodologi pengumpulan data moderen BPS, metode pengisian mandiri secara daring (online) ini disebut sebagai ...', 'CAPI (Computer Assisted Personal Interviewing)', 'PAPI (Paper and Pencil Interviewing)', 'CAWI (Computer Assisted Web Interviewing)', 'CATI (Computer Assisted Telephone Interviewing)', 'C', 'Dalam metode pengumpulan data modern BPS, CAWI adalah moda pendataan di mana responden melakukan pengisian kuesioner secara mandiri secara daring (online) melalui platform atau laman situs web resmi yang disediakan (seperti pada pelaksanaan Sensus Penduduk Online atau Sensus Ekonomi 2026 CAWI). Karakteristik utama CAWI adalah tidak diperlukannya kehadiran fisik petugas wawancara di rumah responden karena proses input dilakukan langsung oleh responden yang memiliki akses internet.', 10),
(136, 2, 'Mudah', 'Ketika seorang responden melakukan pengisian data mandiri melalui aplikasi berbasis web milik BPS, keamanan transmisi data dari peretas (hacker) diatur dengan enkripsi protokol khusus pada bilah alamat browser (ditandai dengan ikon gembok terkunci). Protokol standar internet yang wajib digunakan untuk menjamin keamanan pengiriman data kuesioner digital BPS tersebut adalah ...', 'HTTP', 'HTTPS', 'FTP', 'SMTP', 'B', 'HTTPS (Hypertext Transfer Protocol Secure) => Merupakan protokol standar internet untuk komunikasi data yang aman di dalam jaringan komputer. HTTPS menggunakan sistem enkripsi menggunakan Secure Sockets Layer (SSL) atau Transport Layer Security (TLS). Di BPS, penggunaan HTTPS pada aplikasi kuesioner mandiri berbasis web (seperti moda CAWI) sangat wajib digunakan untuk memastikan data rahasia yang diinput oleh responden (seperti nomor NIK, pendapatan, atau data industri) diacak (di-enkripsi) selama proses pengiriman dari gawai responden menuju peladen (server) pusat, sehingga aman dari ancaman penyadapan atau peretas (hacker). Tanda visual protokol ini adalah munculnya awalan https:// dan ikon gembok terkunci pada bilah alamat (address bar) peramban web.', 10),
(137, 2, 'Sedang', 'Saat responden mengisikan data pada aplikasi kuesioner elektronik BPS (baik CAWI maupun CAPI), sistem secara otomatis menolak (error message) jika responden memasukkan angka 25 pada kolom Usia Anak Kandung Pertama, sementara pada kolom Usia Ibu Kandung diisi angka 30. Fitur otomatis dalam pemrograman aplikasi kuesioner digital BPS yang berfungsi untuk mencegah kesalahan entri akibat ketidakselarasan logika jawaban ini disebut ...', 'Auto-Save System', 'Consistency Check / Skip Logic Validation', 'Data Mining Feature', 'User Interface Formatting', 'B', 'Fitur ini merupakan pilar utama dalam akurasi pengumpulan data digital (CAPI/CAWI) di BPS. Consistency Check (Cek Konsistensi) secara otomatis membandingkan keselarasan logika antara dua variabel yang saling berhubungan. Secara biologis dan hukum, tidak logis seorang ibu melahirkan anak kandung pertama pada usia 5 tahun (30 - 25 = 5). Ketika mendeteksi ketidakselarasan ini, sistem pemrograman aplikasi kuesioner akan mengunci isian dan memunculkan pesan kesalahan (error message) agar petugas atau responden langsung memperbaiki data yang keliru sebelum beralih ke pertanyaan selanjutnya.', 10);
INSERT INTO `soal` (`id`, `kategori_id`, `level`, `pertanyaan`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `jawaban`, `pembahasan`, `xp`) VALUES
(138, 2, 'Sedang', 'Dalam diagram alur (flowchart) sistem pengolahan data kuesioner elektronik BPS, terdapat aturan kondisional (if-else statement) berikut :\r\n1. JIKA status responden = \"Bekerja\", MAKA aplikasi akan membuka blok pertanyaan mengenai Kolom Pendapatan dan Jam Kerja.\r\n2. JIKA status responden = \"Sekolah/Tidak Bekerja\", MAKA aplikasi akan otomatis melompati (skip) blok pendapatan dan langsung menuju ke Kolom Pendidikan.\r\n\r\nJika seorang responden adalah seorang mahasiswa yang sedang menempuh kuliah penuh waktu dan sama sekali tidak bekerja, alur data manakah yang akan dilewati oleh sistem aplikasi?', 'Mengisi Kolom Pendapatan dan Jam Kerja, lalu melompati Kolom Pendidikan', 'Melompati Kolom Pendapatan dan Jam Kerja, lalu langsung menuju Kolom Pendidikan', 'Mengisi kedua kolom secara bersamaan tanpa ada yang dilompati', 'Aplikasi akan otomatis berhenti (hang/error) karena responden memiliki dua status', 'B', 'Logika program aplikasi kuesioner elektronik BPS bekerja secara ketat berdasarkan aturan kondisional (if-else statement atau skip logic) yang telah ditanamkan dalam kode programnya.\r\n1. Kondisi responden dalam soal : Seorang mahasiswa penuh waktu dan sama sekali tidak bekerja. Artinya, ia masuk ke dalam kategori kondisi kedua, yaitu \r\n    \"Sekolah/Tidak Bekerja\".\r\n2. Berdasarkan perintah flowchart : Jika masuk kondisi ini, aplikasi akan mengeksekusi perintah melompati (skip) blok pendapatan dan jam kerja, lalu memindahkan  \r\n    kursor data langsung ke pertanyaan mengenai Kolom Pendidikan. Hal ini dilakukan agar proses wawancara menjadi efisien dan responden tidak ditanyakan hal yang\r\n    tidak relevan dengan kondisinya.', 10),
(139, 2, 'Mudah', 'Salah satu lompatan terbesar BPS dalam memodernisasi pengumpulan data lapangan melalui metode digital (seperti penggunaan gawai CAPI/CAWI) adalah tersedianya fitur Geotagging. Apa fungsi dan kegunaan utama dari implementasi fitur geotagging tersebut bagi kualitas data BPS?', 'Menghitung otomatis perkiraan berat badan dan tinggi badan responden dari foto', 'Mengunci dan merekam titik koordinat geografis (lintang dan bujur) lokasi rumah tangga sampel secara presisi saat didata oleh petugas', 'Mempercepat pengiriman dana insentif pulsa internet bagi responden secara otomatis', 'Mengubah format kuesioner bahasa Indonesia menjadi bahasa daerah secara instan', 'B', 'Geotagging adalah proses penambahan informasi identifikasi geografis (meta data spasial) ke dalam data digital kuesioner. Di BPS, fitur ini memanfaatkan sensor GPS pada gawai petugas untuk mengunci titik koordinat lokasi tepat di mana wawancara berlangsung. \r\nFungsi utamanya sangat krusial bagi kualitas data : memastikan bahwa petugas benar-benar mendatangi rumah tangga sampel di lapangan (mencegah manipulasi data/data fiktif di atas meja) serta memungkinkan hasil sensus/survei tersebut diintegrasikan ke dalam peta digital Wilkerstat untuk analisis spasial', 10),
(140, 1, 'Sedang', 'Seorang peneliti di BPS ingin mengetahui kekuatan hubungan antara Tingkat Pendapatan Bulanan (X) dan Jumlah Pengeluaran Konsumsi (Y) di suatu wilayah menggunakan Koefisien Korelasi Pearson (r). Setelah dihitung, nilai korelasi yang didapatkan adalah r = -0,85.\r\nBagaimana interpretasi atau kesimpulan yang paling tepat mengenai hubungan kedua variabel tersebut?', 'Hubungan antara pendapatan dan pengeluaran sangat lemah dan hampir tidak ada arti statistiknya', 'Terdapat hubungan yang sangat kuat dan berbanding lurus (jika pendapatan naik, pengeluaran pasti naik)', 'Terdapat hubungan yang sangat kuat tetapi berbanding terbalik (jika pendapatan naik, pengeluaran justru turun signifikan)', 'Terjadi kesalahan perhitungan karena nilai koefisien korelasi tidak boleh bernilai negatif', 'C', 'Koefisien Korelasi Pearson (r)) memiliki rentang nilai antara -1 hingga +1. Interpretasi nilainya dibagi menjadi dua komponen : \r\na. Tanda Negatif (-) => Menunjukkan arah hubungan yang berbanding terbalik (negatif). Artinya, jika nilai variabel X naik, maka nilai variabel Y cenderung turun, dan   \r\n    sebaliknya.\r\nb. Nilai Mutlak (0,85)) => Menunjukkan kekuatan hubungan. Nilai 0,85 berada dalam kategori sangat kuat (umumnya nilai di atas 0,70 atau 0,80 diartikan sebagai \r\n    hubungan yang kuat hingga sangat kuat).Maka, kombinasi tanda negatif dan angka \\(0,85\\) mengindikasikan adanya hubungan linear negatif yang sangat kuat \r\n    antara kedua variabel tersebut.', 10),
(141, 1, 'Sedang', 'Kantor BPS Kabupaten menetapkan bahwa target entri data kuesioner Sensus Pertanian harus selesai dalam waktu 12 hari jika dikerjakan oleh 6 orang operator komputer. Setelah bekerja selama 4 hari, pekerjaan terpaksa dihentikan total selama 2 hari karena pemeliharaan rutin server (server maintenance). \r\nAgar target entri data tetap selesai tepat waktu sesuai jadwal semula, berapa orangkah operator tambahan yang harus segera direkrut?', '2 orang operator', '4 orang operator', '6 orang operator', '8 orang operator', 'A', 'Kasus ini diselesaikan dengan rumus Perbandingan Berbalik Nilai untuk sisa pekerjaan yang harus diselesaikan.\r\n1. Kondisi Awal => Pekerjaan harus selesai dalam 12 hari oleh 6 orang.\r\n2. Setelah 4 hari berjalan => Sisa waktu normal adalah 12 - 4 = 8 hari. Jika kondisi normal, sisa pekerjaan ini cukup diselesaikan oleh 6 orang operator.\r\n3. Setelah libur 2 hari => Sisa waktu berkurang lagi menjadi 8 - 2 = 6 hari. Kita harus mencari berapa jumlah total operator (X) yang dibutuhkan agar pekerjaan selesai  \r\n    dalam 6 hari ini.\r\n\r\nGunakan persamaan perbandingan berbalik nilai untuk sisa hari : \r\nSisa Hari Normal x Operator Awal = Sisa Hari Aktual x Total Operator Baru\r\n                                              8 x 6 = 6 x X\r\n                                                  48 = 6X\r\n                                                    X = 48/6 = 8 orang operator (total yang dibutuhkan)\r\n\r\nKarena di kantor sudah ada 6 orang operator awal, maka jumlah operator tambahan yang harus direkrut adalah : \r\nOperator Tambahan = 8 -6 = 2 orang operator', 10),
(142, 3, 'Mudah', 'Dalam penghitungan Indeks Pembangunan Teknologi Informasi dan Komunikasi (IP-TIK), BPS membagi indikator penyusunnya menjadi 3 sub-indeks utama untuk melihat kesiapan infrastruktur dan keahlian digital masyarakat suatu daerah.\r\nDi bawah ini yang merupakan salah satu dari 3 sub-indeks penyusun IP-TIK BPS adalah ...', 'Sub-indeks Kecepatan Keuangan Digital (Financial Speed)', 'Sub-indeks Pemanfaatan / Penggunaan (Use)', 'Sub-indeks Keamanan Jaringan Siber (Cyber Security)', 'Sub-indeks Anggaran Pendapatan Operator Telekomunikasi', 'B', 'Berdasarkan metode resmi BPS yang mengadopsi standar internasional International Telecommunication Union (ITU), Indeks Pembangunan Teknologi Informasi dan Komunikasi (IP-TIK) merupakan indeks komposit yang disusun oleh 11 indikator dan dibagi ke dalam 3 sub-indeks utama :\r\n1. Sub-indeks Akses dan Infrastruktur (Access) => Mengukur kesiapan fisik (seperti persentase rumah tangga yang memiliki komputer atau akses internet fixed \r\n    broadband).\r\n2. Sub-indeks Pemanfaatan/Penggunaan (Use) => Mengukur seberapa aktif masyarakat menggunakannya (seperti persentase penduduk yang menggunakan internet \r\n    atau langganan telepon seluler aktif).\r\n3. Sub-indeks Keahlian (Skills) => Mengukur kapasitas atau literasi digital masyarakat (seperti angka melek huruf dan tingkat partisipasi sekolah).', 10),
(143, 2, 'Mudah', 'Dalam pelaksanaan Survei Sosial Ekonomi Nasional (Susenas) Modul Konsumsi dan Pengeluaran, BPS mencatat rincian konsumsi makanan responden. Rentang waktu acuan (recall period) yang digunakan petugas untuk menanyakan pengeluaran makanan rumah tangga adalah ...', '1 hari terakhir', '7 hari terakhir', '30 hari terakhir', '1 tahun terakhir', 'B', 'Dalam metodologi Survei Sosial Ekonomi Nasional (Susenas) Modul Konsumsi dan Pengeluaran yang diselenggarakan oleh BPS, rentang waktu acuan (recall period) untuk komoditas makanan, minuman, dan rokok mutlak ditetapkan selama 7 hari terakhir (seminggu ke belakang sebelum hari pencacahan). Rentang waktu 7 hari dianggap paling optimal dan akurat secara statistik: tidak terlalu pendek sehingga bisa menangkap pola konsumsi mingguan rumah tangga secara representatif, dan tidak terlalu panjang sehingga meminimalisir risiko responden salah ingat atau lupa (memory lapse) terhadap jenis dan volume makanan yang dikonsumsi.', 10),
(144, 3, 'Mudah', 'Dalam menyusun indikator sosial yang berkaitan dengan harmoni masyarakat, BPS bekerja sama dengan Kementerian Agama secara periodik merilis Indeks Kerukunan Umat Beragama (KUB). Di bawah ini yang merupakan salah satu dari 3 dimensi utama penyusun Indeks KUB tersebut adalah ...', 'Dimensi Kecepatan Pendirian Rumah Ibadah', 'Dimensi Anggaran Bantuan Sosial Keagamaan', 'Dimensi Toleransi, Kesetaraan, dan Kerja Sama', 'Dimensi Jumlah Pemuka Agama Terdaftar', 'C', 'Berdasarkan Detail Metadata Indikator Statistik BPS, Indeks Kerukunan Umat Beragama (IKUB/KUB) dirumuskan sebagai indeks komposit nasional untuk mengukur tingkat harmoni sosial lintas iman. Formulasi indeks ini mutlak ditopang oleh 3 dimensi utama yang saling mengikat :\r\n1. Toleransi =>Mengukur sikap saling menerima, menghormati, dan memberi ruang kebebasan beribadah bagi pemeluk agama lain.\r\n2. Kesetaraan => Mengukur pandangan masyarakat dalam melindungi hak, kedudukan hukum, serta kesempatan sosial yang sama tanpa memandang superioritas \r\n    mayoritas.\r\n3. Kerja Sama => Mengukur aksi nyata gotong royong dan partisipasi lintas komunitas agama dalam kehidupan bermasyarakat.', 10),
(145, 1, 'Mudah', 'Perhatikan tiga pernyataan berikut :\r\n1. Pengolahan data survei BPS dilakukan melalui aplikasi komputer atau menggunakan kuesioner kertas (PAPI).\r\n2. Jika pengolahan data dilakukan melalui aplikasi komputer, maka validasi data berjalan otomatis.\r\n3. Saat ini, pengolahan data survei tidak menggunakan kuesioner kertas (PAPI).\r\n\r\nKesimpulan yang paling sah dan logis dari ketiga pernyataan di atas adalah ...', 'Validasi data tidak berjalan otomatis', 'Validasi data berjalan otomatis', 'Petugas lapangan menolak menggunakan aplikasi komputer', 'Pengolahan data survei ditunda hingga waktu yang belum ditentukan', 'B', 'Soal penalaran logis ini diselesaikan menggunakan metode penarikan kesimpulan Silogisme Disjungtif dan Modus Ponens :\r\n- Langkah 1 (Silogisme Disjungtif) => Pernyataan pertama berbentuk pilihan (disjungsi) : \"Aplikasi Komputer ATAU Kuesioner Kertas (PAPI)\". Pernyataan ketiga \r\n   memberikan fakta penegasi (negasi) : \"TIDAK menggunakan kuesioner kertas (PAPI)\". Berdasarkan hukum silogisme disjungtif, jika salah satu pilihan dieliminasi/salah, \r\n   maka pilihan satunya lagi pasti benar. Kesimpulan antara : Pengolahan data dilakukan melalui aplikasi komputer.\r\n- Langkah 2 (Modus Ponens) => Hubungkan kesimpulan antara tersebut dengan pernyataan kedua yang berbentuk implikasi : \"Jika pengolahan dilakukan melalui \r\n   aplikasi komputer, maka validasi data berjalan otomatis.\" Karena syarat di depan (anteseden) terbukti terjadi, maka akibat di belakang (konsekuen) secara mutlak \r\n   juga ikut terjadi. Maka, kesimpulan akhir yang paling sah adalah validasi data berjalan otomatis.', 10),
(146, 3, 'Sedang', 'Dalam mengukur tingkat kesejahteraan masyarakat dari aspek non-ekonomi, BPS merilis indikator Indeks Perilaku Anti Korupsi (IPAK). Indeks ini mengukur persepsi dan pengalaman masyarakat terhadap perilaku koruptif skala kecil (petty corruption) di fasilitas publik. Rentang nilai (skala) indeks IPAK BPS berkisar antara 0 sampai 5. Jika suatu daerah memiliki nilai IPAK mendekati angka 5, apa arti dari capaian tersebut?', 'Masyarakat di daerah tersebut sangat permisif (memaklumi) tindakan korupsi', 'Perilaku korupsi skala kecil di fasilitas publik daerah tersebut dinilai semakin parah', 'Masyarakat di daerah tersebut berperilaku semakin anti-korupsi (bersih dari korupsi)', 'Anggaran pemberantasan korupsi di daerah tersebut mengalami defisit', 'C', 'Berdasarkan landasan metodologi resmi BPS, nilai Indeks Perilaku Anti Korupsi (IPAK) berkisar antara skala 0 sampai 5.\r\nSifat hubungan skala ini adalah searah dengan nama indeksnya. Artinya, semakin angka indeks mendekati nilai maksimal (5), menunjukkan tingkat budaya dan perilaku masyarakat yang semakin bersih dan menolak keras (anti) terhadap praktik korupsi kecil seperti penyuapan, gratifikasi, pungutan liar, maupun nepotisme di fasilitas publik.', 10),
(147, 3, 'Sedang', 'BPS rutin merilis angka Produk Domestik Bruto (PDB) yang dihitung menggunakan dua pendekatan, yaitu PDB Atas Dasar Harga Berlaku (ADHB) dan PDB Atas Dasar Harga Konstan (ADHK). Jika Anda ingin menganalisis pertumbuhan ekonomi murni (riil) suatu negara dari tahun ke tahun tanpa terpengaruh oleh faktor kenaikan harga (inflasi), pendekatan PDB manakah yang wajib Anda gunakan?', 'PDB Atas Dasar Harga Berlaku (ADHB)', 'PDB Atas Dasar Harga Konstan (ADHK)', 'PDB Per Kapita Nominal', 'PDB Sektoral Lapangan Usaha', 'B', 'PDB ADHK (sering disebut PDB Riil) menghitung nilai barang dan jasa menggunakan harga pada satu tahun dasar yang tetap (konstan). Karena harga yang digunakan dikunci pada tahun acuan tersebut, perubahan angka PDB dari tahun ke tahun murni mencerminkan perubahan dalam volume fisik atau kuantitas produksi (pertumbuhan ekonomi riil), tanpa terdistorsi oleh fluktuasi harga pasar atau laju inflasi [A].', 10),
(148, 1, 'Sedang', 'Empat orang petugas lapangan BPS (Rian, Soni, Tio, dan Utami) ditugaskan untuk mencacah empat Blok Sensus yang letaknya berurutan dari barat ke timur (Blok 101, Blok 102, Blok 103, dan Blok 104).\r\n1. Rian bertugas di sebelah timur Soni.\r\n2. Tio bertugas di Blok Sensus ganjil.\r\n3. Utami bertugas tepat di antara Soni dan Rian.\r\n\r\nSiapakah petugas yang memegang tanggung jawab mencacah di Blok 104?', 'Rian', 'Soni', 'Tio', 'Utami', 'A', 'Mari kita bedah posisi urutan Blok Sensus dari barat ke timur (101, 102, 103, 104) => \r\n1. Petunjuk 3 menyatakan Utami berada tepat di antara Soni dan Rian. Polanya adalah : Soni - Utami - Rian (karena Rian di sebelah timur Soni). Pola ini membutuhkan 3 \r\n    kotak berurutan.\r\n2. Petunjuk 2 menyatakan Tio berada di Blok ganjil (antara Blok 101 atau 103). Jika Tio di 103, pola 3 kotak di atas tidak akan muat. Maka, Tio pasti berada di Blok 101.\r\n3. Sisa 3 kotak berikutnya (102, 103, 104) diisi oleh susunan : Soni (102) - Utami (103) - Rian (104). Jadi, yang bertugas di Blok 104 adalah Rian.', 10),
(149, 3, 'Sedang', 'BPS menggunakan instrumen khusus yang disebut Tabel Input-Output (I-O) untuk menyajikan gambaran tentang keterkaitan antar-sektor ekonomi secara komprehensif di Indonesia. Di bawah ini, kegunaan utama dari Tabel Input-Output (I-O) yang dirilis oleh BPS adalah ...', 'Menentukan batasan geografis pemetaan Blok Sensus terbaru', 'Menganalisis dampak pengganda (multiplier effect) suatu kebijakan ekonomi (seperti investasi atau subsidi) terhadap sektor-sektor lainnya', 'Mencatat daftar nama dan alamat (by name by address) seluruh penduduk miskin ekstrem', 'Menghitung jumlah peredaran uang kartal dan uang giral di perbankan', 'B', 'Tabel Input-Output (I-O) yang disusun oleh BPS adalah instrumen statistik ekonomi makro yang menggambarkan aliran barang dan jasa antar-sektor produksi dalam perekonomian. Kegunaan utama dari Tabel I-O adalah untuk mengukur keterkaitan ke depan (forward linkage) dan keterkaitan ke belakang (backward linkage) antar-sektor. Melalui analisis ini, simulasi dampak pengganda (multiplier effect) dapat dihitung dengan presisi, misalnya untuk memprediksi seberapa besar suntikan investasi atau subsidi pada satu sektor (seperti sektor industri otomotif) akan memicu pertumbuhan produksi di sektor-sektor penyokongnya (seperti sektor baja, ban, dan jasa transportasi).', 10),
(150, 3, 'Mudah', 'Angka yang menunjukkan rata-rata jumlah anak yang akan dilahirkan oleh seorang wanita pada akhir masa reproduksinya disebut ...', 'Crude Birth Rate (CBR)', 'Age Specific Fertility Rate (ASFR)', 'Total Fertility Rate (TFR)', 'Infant Mortality Rate (IMR)', 'C', 'Total Fertility Rate (TFR) (Angka Kelahiran Total) adalah rata-rata jumlah anak yang dilahirkan hidup oleh seorang wanita selama masa reproduksinya (usia 15–49 tahun) dengan asumsi ia mengikuti pola fertilitas pada saat TFR dihitung [1].', 10),
(151, 3, 'Mudah', 'Indikator yang menunjukkan persentase kamar yang terjual/dipakai dibandingkan dengan total kapasitas kamar yang tersedia pada hotel dalam periode tertentu adalah ...', 'Tingkat Penghunian Kamar (TPK)', 'Rata-rata Lama Menginap Tamu (RLMT)', 'Jumlah Kunjungan Wisman', 'Tingkat Okupansi Destinasi', 'A', 'Tingkat Penghunian Kamar (TPK) (atau sering disebut Room Occupancy Rate) adalah indikator produktivitas perhotelan yang mengukur persentase kamar yang terjual atau digunakan dibandingkan dengan seluruh kapasitas kamar yang siap dijual dalam periode tertentu.', 10),
(152, 3, 'Mudah', 'Penduduk yang bekerja di bawah jam kerja normal (kurang dari 35 jam seminggu) dan masih mencari pekerjaan atau masih bersedia menerima pekerjaan tambahan disebut ...', 'Penganggur Terbuka', 'Setengah Penganggur', 'Pekerja Paruh Waktu', 'Pekerja Informal', 'B', 'Setengah Penganggur (Underemployment) =>Menurut konsep Badan Pusat Statistik (BPS), kelompok ini mencakup penduduk yang bekerja di bawah jam kerja normal (kurang dari 35 jam seminggu), tetapi masih mencari pekerjaan atau masih bersedia menerima pekerjaan tambahan (dahulu kerap diistilahkan sebagai setengah pengangguran terpaksa).', 10),
(153, 3, 'Mudah', 'BPS menghitung pertumbuhan ekonomi menggunakan PDRB atas dasar harga konstan. Komponen yang dikeluarkan dari perhitungan PDRB ini agar mencerminkan pertumbuhan riil adalah ...', 'Pengaruh ekspor', 'Pengaruh investasi mata uang', 'Pengaruh perubahan harga (inflasi/deflasi)', 'Pengaruh subsidi pemerintah', 'C', 'Pengaruh perubahan harga (inflasi/deflasi) =>PDRB Atas Dasar Harga Konstan (ADHK) dihitung dengan menggunakan harga pada tahun dasar tertentu yang dinilai tetap. Penghitungan ini sengaja dilakukan untuk mengeliminasi atau menghilangkan faktor perubahan harga (inflasi maupun deflasi). Dengan begitu, angka yang didapat murni mencerminkan peningkatan atau penurunan volume produksi (pertumbuhan ekonomi riil).', 10),
(154, 3, 'Mudah', 'Dalam penghitungan Indeks Harga Konsumen (IHK) dan inflasi di Indonesia, BPS mengelompokkan barang dan jasa ke dalam beberapa kelompok pengeluaran. Kelompok pengeluaran manakah yang biasanya memberikan andil (bobot) terbesar terhadap inflasi umum (Headline Inflation) di Indonesia?', 'Perumahan, air, listrik dan bahan bakar rumah tangga', 'Makanan, minuman, dan tembakau', 'Transportasi', 'Penyediaan makanan dan minuman/restoran', 'B', 'Berdasarkan data Survei Biaya Hidup (SBH) terbaru yang dirilis oleh Badan Pusat Statistik (BPS), kelompok pengeluaran ini memiliki bobot atau andil terbesar terhadap Indeks Harga Konsumen (IHK) nasional, yaitu sekitar 25 persen dari total pembobotan inflasi umum. Hal ini dikarenakan pengeluaran masyarakat Indonesia porsi terbesarnya dialokasikan untuk kebutuhan konsumsi makanan dasar.', 10),
(155, 3, 'Mudah', 'Dalam metode penghitungan penduduk miskin, BPS menggunakan pendekatan kebutuhan dasar (basic needs approach). Garis Kemiskinan (GK) merupakan penjumlahan dari dua komponen utama, yaitu ...', 'Garis Kemiskinan Makanan dan Garis Kemiskinan Perumahan', 'Garis Kemiskinan Primer dan Garis Kemiskinan Sekunder', 'Garis Kemiskinan Makanan dan Garis Kemiskinan Bukan Makanan', 'Garis Kemiskinan Konsumsi dan Garis Kemiskinan Produksi', 'C', 'Berdasarkan metodologi Badan Pusat Statistik (BPS), Garis Kemiskinan (GK) diperoleh dari penjumlahan GKM + GKNM. \r\n- GKM merupakan nilai pengeluaran minimum untuk memenuhi makanan yang disetarakan dengan 2.100 kilokalori (kkal) per kapita per hari (diwakili oleh paket 52 \r\n   komoditi dasar makanan). \r\n- GKNM merupakan nilai pengeluaran minimum untuk memenuhi kebutuhan non-makanan pokok seperti perumahan, sandang, pendidikan, kesehatan, dan \r\n   transportasi (diwakili 51 jenis komoditi di perkotaan dan 47 di perdesaan).', 10),
(156, 3, 'Mudah', 'Berdasarkan konsep ketenagakerjaan BPS, penduduk usia kerja yang selama seminggu sebelum pencacahan tidak bekerja, tetapi sedang mencari pekerjaan, disebut sebagai ...', 'Pekerja Paruh Waktu', 'Setengah Penganggur', 'Pengangguran Terbuka', 'Bukan Angkatan Kerja', 'C', 'Menurut konsep BPS (melalui Sakernas), Pengangguran Terbuka mencakup penduduk usia kerja yang selama seminggu sebelum pencacahan tidak bekerja, tetapi sedang mencari pekerjaan. Konsep ini juga mencakup mereka yang sedang mempersiapkan usaha baru atau sudah punya pekerjaan tapi belum mulai bekerja.', 10),
(157, 3, 'Sedang', 'Rasio Gini adalah indikator yang digunakan BPS untuk mengukur tingkat ketimpangan pengeluaran penduduk. Jika nilai Rasio Gini suatu wilayah semakin mendekati angka 1 (satu), maka hal ini mengindikasikan ...', 'Distribusi pendapatan penduduk semakin merata', 'Ketimpangan distribusi pengeluaran semakin tinggi', 'Pendapatan rata-rata seluruh penduduk mengalami penurunan', 'Tingkat kemiskinan di wilayah tersebut sudah nol persen', 'B', 'Nilai Rasio Gini berkisar antara 0 hingga 1.\r\na. Jika angka mendekati 0, artinya distribusi pengeluaran/pendapatan semakin merata sempurna.\r\nb. Jika angka mendekati 1, artinya distribusi semakin timpang sempurna (sebagian besar pengeluaran hanya dikuasai oleh segelintir kelompok penduduk atas). Oleh \r\n    karena itu, nilai yang semakin mendekati 1 menunjukkan ketimpangan yang semakin tinggi.', 10),
(158, 2, 'Mudah', 'Dalam pelaksanaan Sensus Penduduk 2020, BPS melakukan inovasi dengan menggunakan Metode Kombinasi (Combined Method). Data dasar utama apakah yang digunakan sebagai titik awal dalam metode kombinasi tersebut?', 'Data hasil Survei Sosial Ekonomi Nasional (Susenas)', 'Data Pendaftaran Penduduk dari RT/RW setempat', 'Data Administrasi Kependudukan (Adminduk) dari Ditjen Dukcapil', 'Data Potensi Desa (Podes) terbaru', 'C', 'Sensus Penduduk 2020 (SP2020) mengukir sejarah sebagai sensus pertama di Indonesia yang menggunakan Metode Kombinasi (Combined Method). Titik awal atau basis data utama dari metode ini adalah memanfaatkan data registrasi kependudukan milik Ditjen Dukcapil Kementerian Dalam Negeri sebagai prelist (daftar awal) yang kemudian diverifikasi dan dilengkapi di lapangan. Langkah ini ditujukan demi mewujudkan visi Satu Data Kependudukan Indonesia.', 10),
(159, 2, 'Mudah', 'Manakah indikator berikut yang TIDAK bersumber dari pendataan Survei Sosial Ekonomi Nasional (Susenas)?', 'Angka Partisipasi Sekolah (APS)', 'Persentase Penduduk Miskin', 'Angka Keluhan Kesehatan', 'Tingkat Pengangguran Terbuka (TPT)', 'D', 'Indikator ketenagakerjaan utama ini TIDAK bersumber dari Susenas, melainkan bersumber sepenuhnya dari Survei Angkatan Kerja Nasional (Sakernas). Sakernas dirancang secara khusus oleh BPS untuk mengumpulkan data ketenagakerjaan secara mendalam (Februari dan Agustus), mencakup angkatan kerja, pengangguran, dan upah buruh.', 10),
(160, 3, 'Mudah', 'Subsektor pertanian manakah yang TIDAK dihitung dalam penyusunan angka Nilai Tukar Petani (NTP) oleh BPS?', 'Tanaman Pangan', 'Hortikultura', 'Jasa Penunjang Pertanian', 'Perikanan', 'C', 'Sektor pertanian yang dicakup dalam perhitungan Nilai Tukar Petani (NTP) BPS hanya terdiri dari 5 subsektor utama, yaitu :\r\n1. Tanaman Pangan (NTPP) : Mencakup komoditas padi dan palawija.\r\n2. Hortikultura (NTPH) : Mencakup sayur-sayuran, buah-buahan, dan tanaman obat.T\r\n3. anaman Perkebunan Rakyat (NTPR) : Mencakup karet, kelapa sawit, kopi, cokelat, dll.\r\n4. Peternakan (NTPT) : Mencakup ternak besar, ternak kecil, unggas, dan hasil ternak.\r\n5. Perikanan (NTNP) : Dibagi lagi menjadi kelompok perikanan tangkap dan perikanan budidaya.\r\n\r\nMeskipun merupakan bagian dari sektor pertanian dalam klasifikasi lapangan usaha (KBLI), aktivitas jasa penunjang pertanian (seperti jasa sewa traktor, jasa penggilingan, atau buruh tani) tidak dimasukkan sebagai subsektor tersendiri dalam diagram timbang perhitungan rumah tangga produsen komoditas NTP. Oleh karena itu, pilihan ini menjadi indikator yang TIDAK dihitung secara terpisah dalam subsektor NTP.', 10),
(161, 2, 'Mudah', 'Berdasarkan konsep BPS, kapankah batasan periode waktu \"Seminggu yang Lalu\" yang digunakan sebagai acuan dalam wawancara ketenagakerjaan?', '7 hari kalender sebelum hari pencacahan', '7 hari berturut-turut yang berakhir sehari sebelum hari pencacahan', 'Senin sampai Minggu pada minggu pelaksanaan survei', '30 hari sebelum pencacahan', 'B', 'Berdasarkan metodologi baku Badan Pusat Statistik (BPS) yang mengadopsi standar International Labour Organization (ILO), periode referensi pendek (short recent reference period) dirancang untuk meminimalkan kesalahan ingatan (recall bias) dari responden. Oleh karena itu, frasa \"seminggu yang lalu\" secara teknis diartikan sebagai jangka waktu 7 hari berturut-turut yang dihitung mundur dan berakhir tepat satu hari (kemarin) sebelum tanggal wawancara/pencacahan dilakukan.', 10),
(162, 3, 'Mudah', 'Istilah untuk angka yang menunjukkan banyaknya jumlah penduduk laki-laki per 100 penduduk perempuan di suatu wilayah adalah ...', 'Angka Beban Ketergantungan', 'Rasio Pola Penduduk', 'Rasio Jenis Kelamin (Sex Ratio)', 'Angka Maskulinitas Kasar', 'C', 'Rasio Jenis Kelamin (Sex Ratio) =>Adalah indikator kependudukan yang membandingkan jumlah penduduk laki-laki dengan jumlah penduduk perempuan di suatu wilayah pada waktu tertentu, yang dinyatakan dalam rasio per 100 penduduk perempuan.\r\nContoh : Jika suatu daerah memiliki Sex Ratio sebesar 102, artinya terdapat 102 penduduk laki-laki untuk setiap 100 penduduk perempuan di daerah tersebut.', 10),
(163, 3, 'Mudah', 'Indeks yang dirilis BPS untuk mengukur tingkat kesetaraan dan keadilan gender dalam capaian pembangunan di suatu wilayah adalah ...', 'Indeks Pembangunan Manusia (IPM)', 'Indeks Pembangunan Gender (IPG)', 'Indeks Ketimpangan Gender (IKG)', 'Indeks Pemberdayaan Gender (IDG)', 'B', 'Indeks Pembangunan Gender (IPG) =>Adalah indikator komposit yang dirilis BPS untuk mengukur kesetaraan, keadilan, atau disparitas pencapaian pembangunan antara laki-laki dan perempuan. Indikator penyusun IPG sama persis dengan dimensi dasar IPM (kesehatan, pendidikan, dan standar hidup layak), tetapi dihitung secara terpisah per jenis kelamin untuk melihat rasionya. Semakin dekat angka IPG ke nilai 100, berarti pencapaian pembangunan semakin setara dan adil.', 10),
(164, 2, 'Mudah', 'Dalam portal data resmi BPS, kode unik yang diberikan kepada setiap wilayah administrasi dari tingkat Provinsi hingga Desa diatur dalam standar yang disebut ...', 'Kode POS', 'Kode Registrasi Penduduk', 'Master File Desa (MFD) / Kode Wilayah Kerja Statistik', 'Kode Unik Kewilayahan (KUK)', 'C', 'Master File Desa (MFD) / Kode Wilayah Kerja Statistik => BPS mengelola database wilayah administrasi seluruh Indonesia yang diperbarui secara berkala dalam sistem Master File Desa (MFD). Kode wilayah kerja statistik ini terdiri dari susunan angka digital berpasangan dari kiri ke kanan yang menunjukkan hierarki kewilayahan :\r\n- 2 digit pertama : Provinsi\r\n- 2 digit berikutnya : Kabupaten/Kota\r\n- 3 digit berikutnya : Kecamatan\r\n- 3 digit terakhir : Desa/Kelurahan\r\n   Standardisasi kode wilayah ini sangat krusial di BPS agar data dari berbagai survei dan sensus dapat diintegrasikan secara geospasial dengan konsisten.', 10),
(165, 2, 'Mudah', 'Manakah di bawah ini yang merupakan produk hukum utama yang melandasi tugas BPS sebagai Pembina Data dalam program Satu Data Indonesia?', 'UU No. 16 Tahun 1997 tentang Statistik', 'Perpres No. 39 Tahun 2019 tentang Satu Data Indonesia', 'Perpres No. 95 Tahun 2018 tentang SPBE', 'UU No. 14 Tahun 2008 tentang KIP', 'B', 'Perpres No. 39 Tahun 2019: Merupakan payung hukum utama pelaksanaan Satu Data Indonesia (SDI). Peraturan Presiden ini secara spesifik memberikan mandat penuh kepada Badan Pusat Statistik (BPS) untuk bertindak sebagai Pembina Data Statistik di tingkat pusat. Tugas utama BPS dalam peran ini meliputi menetapkan standar data, menetapkan struktur dan format baku metadata, serta memberikan rekomendasi dalam penyelenggaraan statistik sektoral.', 10),
(166, 2, 'Sedang', 'Jika seorang petugas BPS mendatangi sebuah rumah tangga namun seluruh anggotanya sedang bepergian selama masa pencacahan, metode yang digunakan untuk memperoleh informasi dasar adalah ...', 'Wawancara imajinatif', 'Proxy Interview (Wawancara melalui tetangga/pengurus RT)', 'Pengisian mandiri (Self-Enumeration)', 'Penghapusan sampel otomatis', 'B', 'Dalam metodologi lapangan BPS, jika responden utama (key respondent) atau seluruh anggota keluarga inti tidak dapat ditemui setelah dilakukan kunjungan ulang berkali-kali karena bepergian, petugas diizinkan melakukan proxy interview. Petugas akan menggali informasi dasar (seperti jumlah anggota keluarga atau status keberadaan) melalui orang lain yang dianggap mengetahui karakteristik rumah tangga tersebut, seperti tetangga terdekat, pemilik kontrakan, atau pengurus RT/RW setempat.', 10),
(167, 2, 'Mudah', 'Dalam struktur organisasi lapangan sensus/survei BPS, petugas yang bertanggung jawab mengawasi dan memeriksa kebenaran hasil isian kuesioner dari beberapa Pencacah Lapangan (PCL) disebut. ..', 'Koseka (Koordinator Sensus Kecamatan)', 'PML (Pengawas Sektor Lapangan / Pemeriksa Lapangan)', 'Kortim (Koordinator Tim)', 'Penanggung Jawab Teknis (PJT)', 'B', 'PML / Pemeriksa Lapangan: Berada satu tingkat di atas PCL. Tugas utamanya adalah mendampingi PCL saat awal pencacahan, menerima berkas kuesioner yang telah selesai diisi oleh PCL, dan melakukan pemeriksaan kelengkapan serta konsistensi logika isian (editing-coding) sebelum diserahkan ke tingkat kecamatan/kabupaten.', 10),
(168, 2, 'Mudah', 'Kegiatan pengecekan kembali ke lapangan oleh pengawas terhadap sebagian sampel yang sudah selesai dicacah oleh petugas untuk memastikan validitas data disebut ...', 'Re-entri data', 'Spotcheck (Pemeriksaan acak lapangan)', 'Sensus ulang mini', 'Pre-test metodologi', 'B', 'Spotcheck =>Merupakan bagian dari prosedur pengendalian mutu data (Quality Control) yang wajib dilakukan oleh Pengawas/Pemeriksa Lapangan (PML) atau tim penjamin kualitas dari BPS Kabupaten/Provinsi. Pengawas akan memilih beberapa sampel rumah tangga yang sudah selesai didatangi oleh Pencacah Lapangan (PCL) secara acak, lalu mendatangi rumah tersebut kembali untuk mencocokkan apakah PCL benar-benar melakukan wawancara langsung dan memastikan isian variabel penting (seperti jumlah anggota keluarga atau status bekerja) sudah diisi dengan valid dan jujur.', 10),
(169, 3, 'Mudah', 'Dalam rilis statistik industri, BPS mengategorikan industri pengolahan berdasarkan jumlah tenaga kerjanya. Industri yang memiliki tenaga kerja sebanyak 20 sampai 99 orang masuk ke dalam kelompok ...', 'Industri Mikro', 'Industri Kecil', 'Industri Sedang / Menengah', 'Industri Besar', 'C', 'a. Industri Sedang / Menengah => Memiliki tenaga kerja sebanyak 20 sampai 99 orang.\r\nb. Industri Mikro => Memiliki tenaga kerja sebanyak 1 sampai 4 orang.\r\nc. Industri Kecil => Memiliki tenaga kerja sebanyak 5 sampai 19 orang.\r\nd. Industri Besar => Memiliki tenaga kerja sebanyak 100 orang atau lebih', 10),
(170, 3, 'Mudah', 'Untuk mengukur perkembangan sektor pariwisata selain hotel bintang, BPS juga menghitung Tingkat Penghunian Kamar (TPK) untuk jenis akomodasi ...', 'Homestay luar negeri', 'Hotel Non-Bintang / Akomodasi Lainnya', 'Rumah susun sewa', 'Perkemahan alam bawah sadar', 'B', 'Dalam rilis berkala Statistik Pariwisata dan Transportasi, Badan Pusat Statistik (BPS) membagi pelaporan Tingkat Penghunian Kamar (TPK) menjadi dua kelompok akomodasi utama, yaitu Hotel Bintang (menggunakan klasifikasi bintang 1 hingga 5) dan Hotel Non-Bintang / Akomodasi Lainnya (mencakup losmen, penginapan remaja, wisma, dan sejenisnya yang terdaftar resmi). Langkah ini dilakukan agar potret pergerakan wisatawan domestik di akomodasi skala kecil tetap terekam dengan akurat.', 10),
(171, 3, 'Sedang', 'Dalam indikator perumahan sehat menurut BPS, luas lantai minimal per kapita (per orang) yang dianggap layak untuk hunian adalah ...', '4 meter persegi', '6 meter persegi', '7,2 hingga 8 meter persegi', '12 meter persegi', 'A', 'Berdasarkan metodologi Badan Pusat Statistik (BPS) untuk mengukur Indikator Tujuan Pembangunan Berkelanjutan (SDGs) dan ketahanan sosial, sebuah rumah dikategorikan memenuhi kecukupan luas tempat tinggal (sufficient living space) apabila memiliki luas lantai per kapita minimal 7,2 meter persegi.\r\nAsal-usul angka : Angka ini merujuk pada ketentuan UU No. 1 Tahun 2011 tentang Perumahan dan Kawasan Permukiman serta Kepmen Kimpraswil No. 403/2002. Standar rumah sehat sederhana paling minimal adalah tipe 36 m² yang idealnya dihuni oleh maksimal 5 orang anggota keluarga (36 ÷ 5 = 7,2 m²). Jika luas per kapita di bawah 7,2 m², maka rumah tersebut dikategorikan mengalami kepadatan hunian tidak layak.', 10),
(172, 3, 'Mudah', 'Angka Beban Ketergantungan (Dependency Ratio) suatu daerah adalah 50. Apa arti dari angka tersebut secara ekonomi?', 'Ada 50 orang miskin di antara 100 penduduk', 'Ada 50 pengangguran di antara 100 angkatan kerja', 'Setiap 100 orang usia produktif menanggung beban 50 orang usia non-produktif', '50 persen penduduk daerah tersebut bergantung pada bantuan pemerintah', 'C', 'Dalam demografi dan ekonomi makro, Dependency Ratio dihitung dengan membagi jumlah penduduk usia non-produktif (anak-anak usia 0–14 tahun ditambah lansia usia 65 tahun ke atas) dengan jumlah penduduk usia produktif (usia 15–64 tahun), lalu dikalikan 100. Jika hasilnya adalah 50, artinya secara rata-rata ekonomi, setiap 100 orang yang berada di usia kerja (produktif) harus menopang atau menanggung beban hidup 50 orang yang belum/tidak lagi bekerja (non-produktif). Semakin rendah angka ini, semakin ringan beban ekonomi daerah tersebut (potensi Bonus Demografi).', 10),
(173, 2, 'Mudah', 'Dokumen publikasi resmi tahunan paling komprehensif yang dirilis BPS berisi rangkuman data geografi, pemerintahan, penduduk, sosial, dan ekonomi suatu daerah dinamakan ...', 'Berita Resmi Statistik (BRS)', 'Daerah Dalam Angka (DDA) seperti Provinsi Dalam Angka', 'Analisis Hasil Sensus', 'Jurnal Statistik Ekonomi', 'B', 'Daerah Dalam Angka (DDA) => Merupakan produk publikasi tahunan BPS yang paling populer, lengkap, dan bersifat rujukan utama komprehensif untuk setiap tingkatan wilayah administrasi (misalnya: Indonesia Dalam Angka, Provinsi Jawa Timur Dalam Angka, atau Bangkalan Dalam Angka). Dokumen ini menyajikan data sekunder lintas sektoral mulai dari keadaan iklim/geografi, struktur kepegawaian pemerintah, kependudukan, kesehatan, pendidikan, pertanian, hingga indikator makroekonomi regional yang dikumpulkan baik dari instansi vertikal (Sektoral) maupun hasil survei mandiri BPS [bps.go.id]. Sesuai standar pelayanan, dokumen ini rutin dirilis serentak setiap akhir bulan Februari.', 10),
(174, 2, 'Sedang', 'Dalam prinsip Satu Data Indonesia (SDI), data yang dihasilkan oleh produsen data harus memiliki penjelasan terstruktur mengenai latar belakang, definisi, cakupan, dan metodologi data tersebut. Penjelasan ini disebut ...', 'Kode Sumber Data', 'Master Data Wilayah', 'Metadata Statistik', 'Kamus Data Elektronik', 'C', 'Secara sederhana sering diartikan sebagai \"data tentang data\". Metadata merupakan informasi terstruktur yang memuat karakteristik data, meliputi definisi operasional, latar belakang pengumpulan, cakupan wilayah, metodologi penghitungan, hingga pembatasan teknis lainnya. Sebagai Pembina Data Statistik, BPS bertugas memeriksa dan menyetujui struktur metadata ini agar data antar-instansi dapat saling terintegrasi tanpa salah tafsir.', 10),
(175, 2, 'Mudah', 'Siapakah yang bertindak sebagai Pembina Data Statistik tingkat nasional dalam struktur penyelenggaraan Satu Data Indonesia?', 'Kementerian Komunikasi dan Digital (Kemenkomdigi)', 'Badan Pusat Statistik (BPS)', 'Badan Informasi Geospasial (BIG)', 'Kementerian Perencanaan Pembangunan Nasional (Bappenas)', 'B', 'Ditetapkan secara resmi sebagai Pembina Data Statistik tingkat nasional. BPS bertanggung jawab memberikan pembinaan, menetapkan standar data, merumuskan struktur metadata baku, serta memberikan rekomendasi statistik kepada seluruh produsen data di instansi pemerintah.', 10),
(176, 2, 'Sedang', 'Manakah di bawah ini yang dikategorikan sebagai \"Statistik Sektoral\" dalam sistem statistik nasional?', 'Statistik yang pemanfaatannya ditujukan untuk keperluan luas (seperti Sensus Penduduk oleh BPS)', 'Statistik yang diselenggarakan oleh Kementerian/Lembaga pemerintah untuk tugas pokok instansinya sendiri', 'Statistik yang dikumpulkan oleh lembaga swasta atau universitas untuk riset mandiri', 'Statistik tentang perdagangan internasional regional saja', 'B', 'Statistik Sektoral => Adalah statistik yang pemanfaatannya ditujukan untuk memenuhi kebutuhan instansi pemerintah tertentu dalam rangka penyelenggaraan tugas-tugas pemerintahan dan pembangunan yang menjadi tugas pokok instansi yang bersangkutan.\r\nContoh : Data luasan lahan sawah oleh Kementerian Pertanian, data jumlah sekolah oleh Kemendikbudristek, atau data penyakit menular oleh Kementerian Kesehatan.', 10),
(177, 2, 'Mudah', 'Apa aplikasi portal web berbasis data geospasial dan statistik wilayah terintegrasi milik BPS yang menyajikan visualisasi peta indikator daerah?', 'Sirusa BPS', 'Berita Resmi Statistik Online', 'Satu Data Portal', 'WebGIS BPS / Silastik', 'D', 'BPS menyediakan layanan Sistem Informasi Geospasial (SIG-BPS) yang mengintegrasikan data atribut statistik dengan data keruangan (spasial) berbasis web (WebGIS). Portal ini memungkinkan masyarakat, peneliti, dan pemerintah daerah untuk melihat fenomena sosial, ekonomi, hingga infografis laju inflasi kota dalam wujud visualisasi peta interaktif digital (peta tematik).', 10),
(178, 2, 'Mudah', 'Sesuai Perpres No. 39 Tahun 2019, unit kerja pada instansi pemerintah yang memiliki tugas untuk mengumpulkan, memeriksa, dan mengelola data yang disampaikan oleh Produsen Data disebut ...', 'Pembina Data', 'Koordinator Data', 'Walidata', 'Pengguna Data', 'C', 'Walidata => Merupakan unit kerja yang ditunjuk pada instansi pusat atau instansi daerah (misalnya Kementerian Komdigi di tingkat pusat, atau Dinas Kominfo di tingkat Provinsi/Kabupaten) yang bertugas untuk mengumpulkan, memeriksa kesesuaian data dengan standar, mengelola, serta menyebarluaskan data yang diproduksi oleh berbagai unit kerja.', 10),
(179, 2, 'Mudah', 'Manakah di bawah ini yang TIDAK termasuk dalam 4 Pilar Prinsip Satu Data Indonesia (SDI)?', 'Data harus memenuhi Standar Data', 'Data harus memiliki Metadata', 'Data harus bersifat rahasia dan tidak boleh dibagikan', 'Data harus menggunakan Kode Referensi dan/atau Data Induk', 'C', 'Berdasarkan Pasal 11 Perpres No. 39 Tahun 2019 tentang Satu Data Indonesia, untuk mewujudkan keterpaduan perencanaan dan evaluasi pembangunan, data yang dihasilkan oleh produsen data wajib memenuhi 4 Pilar Prinsip Satu Data Indonesia, yaitu :\r\n1. Memenuhi Standar Data : Data harus memiliki konsep, definisi, cakupan, klasifikasi, ukuran, dan satuan yang baku.\r\n2. Memiliki Metadata : Data harus disertai dengan informasi terstruktur yang menjelaskan latar belakang, metodologi, dan karakteristik teknis dari data tersebut.\r\n3. Memenuhi Kaidah Interoperabilitas Data : Data harus memiliki kemampuan untuk dibagi pakaikan atau saling ditukarkan antar-sistem elektronik tanpa kendala \r\n    format.\r\n4. Menggunakan Kode Referensi dan/atau Data Induk : Data harus menggunakan sandi atau kode unik yang disepakati (seperti Master File Desa) agar sinkron secara \r\n    spasial dan administratif.', 10),
(180, 2, 'Sedang', 'Struktur data atau format data yang digunakan dalam Satu Data Indonesia harus memenuhi prinsip \"Interoperabilitas\".  Apa arti dari Interoperabilitas Data?', 'Data disimpan di dalam server komputer lokal yang aman', 'Data dienkripsi agar tidak bisa dibaca oleh pihak lain', 'Data dapat dengan mudah dibagikan, diakses, dan dibaca antar-sistem elektronik yang berbeda tanpa hambatan teknis', 'Data dihitung menggunakan rumus statistik yang rumit', 'C', 'Interoperabilitas Data => Berarti data yang diproduksi oleh suatu instansi memiliki karakteristik struktur yang konsisten dan menggunakan format terbuka (seperti format yang mudah dibaca mesin/aplikasi lain), sehingga data tersebut dapat saling ditukarkan, diakses, dan dibagipakaikan secara otomatis antar-sistem elektronik milik kementerian, lembaga, atau daerah yang berbeda. Prinsip ini bertujuan menghilangkan ego sektoral \"silodata\" (data yang terisolasi di masing-masing instansi) agar pemerintah bisa mengambil keputusan cepat berbasis data lintas sektor.', 10),
(181, 2, 'Sedang', 'Menurut UU No. 16 Tahun 1997 tentang Statistik, jenis statistik dibagi menjadi tiga. Manakah pilihan di bawah ini yang merupakan pembagian resmi tersebut?', 'Statistik Dasar, Statistik Sektoral, dan Statistik Khusus', 'Statistik Makro, Statistik Mikro, dan Statistik Sektoral', 'Statistik Pemerintah, Statistik Swasta, dan Statistik Internasional', 'Statistik Deskriptif, Statistik Inferensial, dan Statistik Terapan', 'A', 'Berdasarkan Bab II Pasal 5 Undang-Undang Nomor 16 Tahun 1997 tentang Statistik, jenis statistik di Indonesia secara legal formal dibagi menjadi tiga kategori utama 1, Statistik Dasar : Statistik yang pemanfaatannya ditujukan untuk keperluan luas, baik bagi pemerintah maupun masyarakat, yang memiliki ciri lintas sektoral, berskala \r\n    nasional, makro, dan diselenggarakan oleh Badan Pusat Statistik (BPS).\r\n    Contoh : Sensus Penduduk, Angka Inflasi, dan Data Kemiskinan.\r\n2. Statistik Sektoral : Statistik yang pemanfaatannya ditujukan untuk memenuhi kebutuhan instansi pemerintah tertentu dalam rangka penyelenggaraan tugas pokok \r\n    pemerintahan dan pembangunan sektor yang bersangkutan.\r\n    Contoh : Data jumlah guru oleh Kemendikbudristek atau data luasan sawah oleh Kementan.\r\n3. Statistik Khusus : Statistik yang pemanfaatannya ditujukan untuk memenuhi kebutuhan spesifik sektor tertentu di masyarakat, yang diselenggarakan oleh lembaga \r\n    swasta, organisasi, universitas, atau perorangan.\r\n    Contoh : Survei indeks kepuasan konsumen oleh perusahaan riset swasta atau survei elektabilitas politik.', 10),
(182, 2, 'Mudah', 'Jika sebuah lembaga swasta atau perusahaan melakukan survei pasar secara mandiri untuk kepentingan bisnis internal mereka sendiri, kegiatan tersebut masuk ke dalam kategori ...', 'Statistik Sektoral', 'Statistik Dasar', 'Statistik Khusus', 'Statistik Komersial', 'C', 'Statistik Khusus => Ditujukan untuk memenuhi kebutuhan spesifik sektor tertentu di masyarakat. Penyelenggaranya bisa berasal dari lembaga swasta, organisasi masyarakat, perguruan tinggi, maupun perorangan [bps.go.id]. Sifat datanya digunakan untuk internal organisasi atau dipublikasikan secara mandiri guna mengedukasi segmen pasar tertentu.', 10),
(183, 2, 'Sedang', 'Berdasarkan UU No. 16 Tahun 1997, BPS wajib menjaga kerahasiaan data individu responden. Petugas statistik dilarang keras membocorkan data pribadi responden kepada pihak mana pun. Aturan ini disebut dengan ...', 'Hak Kekayaan Intelektual Data', 'Asas Keterbukaan Publik', 'Jaminan Kerahasiaan Responden (Kerahasiaan Data Individu)', 'Protokol Akses Terbatas', 'B', 'Berdasarkan Pasal 21 UU No. 16 Tahun 1997 tentang Statistik, penyelenggara statistik (baik BPS, instansi sektoral, maupun statistik khusus) wajib merahasiakan data pribadi responden atau data individu dari unit usaha yang dikumpulkan [bps.go.id]. Data tersebut dilindungi oleh hukum dan tidak boleh dipublikasikan atau diberikan kepada pihak lain dalam bentuk data mikro yang dapat diidentifikasi secara personal (identifiable data). Kuesioner individu juga dilindungi dan tidak dapat digunakan sebagai pembuktian di pengadilan untuk perkara apa pun.', 10),
(184, 2, 'Mudah', 'Dalam pelaksanaan Evaluasi Penyelenggaraan Statistik Sektoral (EPSS), BPS menilai berapa banyak domain (aspek utama) pada instansi pemerintah?', '2 Domain', '3 Domain', '4 Domain', '5 Domain (Prinsip SDI, Kualitas Data, Proses Bisnis Statistik, Kelembagaan, Statistik Nasional)', 'D', 'Berdasarkan Peraturan Badan Pusat Statistik Nomor 3 Tahun 2022 tentang Evaluasi Penyelenggaraan Statistik Sektoral, penilaian kematangan instansi pemerintah pusat maupun daerah diukur melalui struktur penilaian bertingkat. Struktur ini terdiri dari 5 Domain, 19 Aspek, dan 38 Indikator.\r\nRincian 5 Domain utama yang dinilai dalam kriteria EPSS meliputi :\r\n1. Domain 1 : Prinsip Satu Data Indonesia (SDI) => Menilai kepatuhan instansi terhadap standardisasi data, pengelolaan metadata statistik, serta kapabilitas \r\n    interoperabilitas pembagian data.\r\n2. Domain 2 : Kualitas Data => Menilai aspek relevansi data, akurasi, aktualitas (ketepatan waktu rilis), serta kemudahan akses data untuk publik.\r\n3. Domain 3 : Proses Bisnis Statistik => Menilai kepatuhan alur kerja statistik mulai dari tahapan perencanaan kebutuhan data, perancangan instrumen, pengumpulan, \r\n    pengolahan, analisis, hingga diseminasi hasil.\r\n4. Domain 4 : Kelembagaan => Menilai kekuatan internal instansi seperti optimalisasi peran Tim Penilai Internal (TPI), kualitas SDM statistisi, dan tata kelola organisasi \r\n    data.\r\n5. Domain 5 : Statistik Nasional =>Menilai kontribusi instansi dalam Sistem Statistik Nasional, salah satunya keaktifan dalam mengajukan permohonan rekomendasi \r\n    kegiatan statistik kepada BPS.', 10),
(185, 2, 'Mudah', 'Tingkat kematangan (maturity level) dalam penilaian EPSS dibagi menjadi beberapa level. Level berapakah yang menunjukkan bahwa pengelolaan data statistik sektoral di instansi tersebut sudah \"Terdefinisi\" secara baku?', 'Level 1', 'Level 2', 'Level 3', 'Level 5', 'C', 'Level 3 – Terdefinisi (Defined) : Proses bisnis statistik sektoral sudah didefinisikan secara baku, formal, dan menyeluruh di tingkat instansi. Aturan, kebijakan, panduan teknis, dan standar metadata telah disahkan oleh pimpinan lembaga dan diterapkan oleh seluruh unit kerja.', 10),
(186, 2, 'Sedang', 'Apakah sanksi hukum terberat bagi seseorang atau pihak yang dengan sengaja memalsukan atau merusak data hasil sensus BPS yang sah menurut undang-undang statistik?', 'Hanya teguran lisan', 'Pemecatan dari PNS saja', 'Sanksi pidana denda dan/atau hukuman penjara sesuai ketentuan UU No. 16 Tahun 1997', 'Pencabutan hak pilih dalam pemilu', 'C', 'Berdasarkan Bab X mengenai Ketentuan Pidana (khususnya Pasal 37 dan Pasal 38), siapa saja yang dengan sengaja memalsukan, mengubah, meniru, merusak, atau menghilangkan dokumen, kuesioner, maupun data hasil statistik resmi (sensus/survei) yang diselenggarakan oleh BPS dapat dikenai sanksi pidana kurungan/penjara dan/atau denda materiil hingga puluhan juta rupiah. Sanksi ini berlaku mutlak bagi masyarakat umum, pelaku usaha, maupun petugas internal BPS yang terbukti memanipulasi isian data.', 10),
(187, 2, 'Mudah', 'Sensus Pertanian (ST) mencakup seluruh usaha pertanian di Indonesia. Manakah di bawah ini yang merupakan unit pencacahan utama dalam Sensus Pertanian BPS?', 'Hanya petani pemilik lahan luas', 'Perusahaan perkebunan kelapa sawit saja', 'Usaha Pertanian Perorangan (UTP), Usaha Perusahaan Pertanian Berbadan Hukum (UPB), dan Usaha Pertanian Lainnya (UTL)', 'Seluruh penduduk yang tinggal di pedesaan', 'C', 'Sensus Pertanian (ST) yang diselenggarakan oleh BPS setiap sepuluh tahun sekali (berakhiran angka 3, seperti ST2023) dirancang untuk memotret struktur pertanian nasional secara menyeluruh. Untuk mencakup seluruh aktivitas pertanian, BPS membagi unit pencacahannya ke dalam tiga jenis sub-sektor usaha (konstituen) utama : 1. Usaha Pertanian Perorangan (UTP) : Usaha pertanian yang dilakukan oleh satu orang atau sekelompok orang dalam satu rumah tangga tangga (petani kecil/rakyat).\r\n2. Usaha Perusahaan Pertanian Berbadan Hukum (UPB) : Usaha pertanian yang dikelola oleh suatu perusahaan atau badan hukum resmi, seperti PT, CV, atau Koperasi.\r\n3. Usaha Pertanian Lainnya (UTL) : Usaha pertanian yang dilakukan oleh kelompok non-rumah tangga dan non-perusahaan berbadan hukum, seperti pondok \r\n    pesantren, kelompok tani, panti asuhan, atau instansi pemerintah.', 10),
(188, 3, 'Mudah', 'Petani yang melakukan usaha pertanian dengan tujuan utama untuk memenuhi kebutuhan konsumsi rumah tangganya sendiri (bukan untuk dijual) disebut sebagai ...', 'Petani Komersial', 'Petani Subsisten', 'Petani Gurem', 'Buruh Tani Tani', 'B', 'Dalam konsep ekonomi pertanian dan standardisasi BPS, petani subsisten adalah pelaku usaha pertanian yang orientasi atau tujuan utama dari kegiatan produksinya adalah untuk memenuhi kebutuhan pangan dan konsumsi rumah tangganya sendiri. Hasil panen mereka jarang atau hampir tidak pernah masuk ke pasar komersial, kecuali jika ada sedikit kelebihan surplus musiman.', 10),
(189, 3, 'Mudah', 'BPS mengategorikan Rumah Tangga Usaha Pertanian (RTUP) sebagai \"Petani Gurem\" jika mereka menguasai atau mengelola lahan pertanian kurang dari ...', '0,25 hektar', '0,50 hektar', '1,00 hektar', '2,00 hektar', 'B', 'Berdasarkan konsep dan definisi resmi Badan Pusat Statistik (BPS) yang digunakan dalam Sensus Pertanian, Petani Gurem adalah kepala rumah tangga usaha pertanian yang menguasai atau mengelola lahan (baik milik sendiri, sewa, maupun bagi hasil) dengan luas kurang dari 0,50 hektar (di luar lahan untuk bangunan tempat tinggal). Indikator ini sangat penting dipantau karena mencerminkan tingkat keterbatasan aset produksi petani di Indonesia, terutama di pulau Jawa yang mengalami fragmentasi lahan sangat tinggi.', 10);
INSERT INTO `soal` (`id`, `kategori_id`, `level`, `pertanyaan`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `jawaban`, `pembahasan`, `xp`) VALUES
(190, 3, 'Mudah', 'Sektor pertanian dalam Sensus Pertanian dibagi menjadi beberapa subsektor. Kegiatan budidaya tanaman hias, tanaman obat, buah-buahan, dan sayuran masuk ke dalam subsektor ...', 'Tanaman Pangan', 'Tanaman Perkebunan', 'Kehutanan', 'Hortikultura', 'D', 'Hortikultura => Subsektor yang mencakup budidaya tanaman musiman atau tahunan yang meliputi kelompok sayur-sayuran, buah-buahan, tanaman obat/biofarmaka, dan tanaman hias.', 10),
(191, 3, 'Mudah', 'Komoditas pertanian berikut ini yang masuk ke dalam cakupan subsektor Tanaman Pangan menurut klasifikasi BPS adalah ...', 'Karet, Kelapa Sawit, dan Kopi', 'Cabai, Bawang Merah, dan Mangga', 'Padi, Jagung, dan Kedelai', 'Rumput Laut, Tongkol, dan Udang', 'C', 'Tanaman Pangan => Subsektor ini mencakup tanaman yang menjadi sumber karbohidrat dan protein nabati utama bagi pemenuhan pangan pokok penduduk. Komoditas utamanya meliputi padi (padi sawah dan padi ladang) serta kelompok palawija seperti jagung, kedelai, kacang tanah, kacang hijau, ubi kayu (singkong), dan ubi jalar', 10),
(192, 3, 'Sedang', 'Sebuah Provinsi memiliki data Nilai Tukar Petani (NTP) sebesar 98,5. Bagaimana kesimpulan mengenai tingkat kesejahteraan ekonomi petani di provinsi tersebut secara relatif?', 'Petani mengalami keuntungan besar', 'Harga jual produk pertanian naik lebih tinggi dari harga konsumsi mereka', 'Petani mengalami defisit/penurunan daya beli karena harga yang dibayar lebih tinggi dari yang diterima', 'Pendapatan petani sama dengan pengeluaran mereka (impas)', 'C', 'Analisis Angka 98,5 : Karena angka 98,5 berada di bawah 100, maka secara relatif daya beli petani di provinsi tersebut sedang mengalami penurunan atau mengalami defisit ekonomi akibat tekanan inflasi barang kebutuhan yang dibayar lebih tinggi daripada hasil penjualan komoditas pertanian mereka.', 10),
(193, 3, 'Mudah', 'Jika suatu daerah memiliki tingkat pertumbuhan ekonomi negatif (minus) selama dua kuartal berturut-turut berdasarkan data PDRB ADHK, fenomena ekonomi ini disebut sebagai ...', 'Inflasi Tinggi', 'Stagflasi', 'Resesi Ekonomi', 'Deflasi Struktural', 'C', 'Secara teknis dan standar makroekonomi internasional, sebuah wilayah atau negara dinyatakan mengalami resesi apabila pertumbuhan ekonomi riilnya (PDRB/PDB ADHK) bernilai negatif (mengalami kontraksi/minus) selama minimal dua kuartal (triwulan) berturut-turut. Fenomena ini mencerminkan kelesuan aktivitas produksi, penurunan daya beli, serta peningkatan angka pengangguran.', 10),
(194, 3, 'Mudah', 'Dalam penyusunan PDRB menurut Lapangan Usaha, industri pengolahan yang bahan baku utamanya berasal dari gas bumi dan minyak bumi dikelompokkan ke dalam kategori ...', 'Industri Barang Galian Bukan Logam', 'Industri Kimia, Farmasi, dan Obat Tradisional', 'Industri Logam Dasar', 'Sektor Pertambangan dan Penggalian', 'B', 'Berdasarkan sistem Klasifikasi Baku Lapangan Usaha Indonesia (KBLI) milik BPS, pengolahan gas dan minyak bumi terbagi menjadi dua subkategori utama di bawah sektor Industri Pengolahan :\r\n1. Industri Batubara dan Pengilangan Migas : Khusus untuk aktivitas pemurnian/penyulingan produk BBM langsung (seperti bensin, solar, minyak tanah, LPG).\r\n2. Industri Kimia, Farmasi, dan Obat Tradisional : Khusus untuk aktivitas pengolahan tingkat lanjut (seperti industri petrokimia dasar, pembuatan plastik, resin, senyawa \r\n    organik, dan bahan kimia yang bahan baku utamanya bersumber dari turunan minyak dan gas bumi).', 10),
(195, 3, 'Mudah', 'Pada indikator Indeks Pembangunan Manusia (IPM), angka capaian maksimum ideal untuk dimensi pengeluaran per kapita disesuaikan dihitung menggunakan skala ...', 'Skala linear langsung tanpa batas', 'Transformasi logaritma natural (Ln)', 'Pembagian dengan nilai inflasi global', 'Perkalian dengan angka harapan hidup', 'B', 'Dalam metodologi perhitungan IPM (baik standar UNDP maupun Badan Pusat Statistik), penentuan nilai indeks untuk dimensi standar hidup layak (pengeluaran per kapita disesuaikan) tidak dihitung secara linear langsung.\r\nAlasan Penggunaan Logaritma Natural (Ln) : Dimensi ekonomi menggunakan transformasi logaritma natural (ln) karena adanya teori ekonomi yang menyatakan bahwa manfaat atau utilitas dari pendapatan/pengeluaran akan mengalami penurunan marginal seiring bertambahnya kekayaan (diminishing marginal utility of income).\r\nArtinya, tambahan uang sebesar Rp1.000.000 bagi penduduk miskin akan meningkatkan kualitas hidupnya secara luar biasa signifikan, sedangkan tambahan uang Rp1.000.000 bagi penduduk yang sudah sangat kaya pengaruhnya terhadap kualitas hidup cenderung kecil. Transformasi logaritma menjembatani perbedaan ekstrem ini agar angka indeks tetap objektif.', 10),
(196, 3, 'Mudah', 'Survei BPS yang khusus digunakan untuk mengumpulkan data volume, frekuensi, dan nilai transaksi perdagangan antar-wilayah di dalam negeri Indonesia dinamakan ...', 'Survei Harga Perdagangan Besar (SHPB)', 'Survei Perdagangan Antar Wilayah (SPAW)', 'Survei Distribusi Perdagangan (SDP)', 'Sensus Ekonomi Lanjutan', 'B', 'Survei Perdagangan Antar Wilayah (SPAW / PAW)V => Merupakan bagian dari program Statistik Distribusi BPS yang bertujuan untuk mendapatkan data nilai, volume, alur peta, frekuensi, hingga jenis moda transportasi yang digunakan dalam transaksi perdagangan barang lintas wilayah/provinsi di Indonesia. Survei ini sangat vital untuk memetakan ketergantungan pasokan komoditas strategis antar-daerah serta mendukung analisis konektivitas logistik nasional.', 10),
(197, 3, 'Mudah', 'Indikator ketenagakerjaan yang mengukur persentase jumlah penduduk yang bekerja formal terhadap total penduduk yang bekerja disebut sebagai ...', 'Tingkat Partisipasi Angkatan Kerja', 'Rasio Kesempatan Kerja', 'Persentase Pekerja Formal', 'Tingkat Pengembalian Tenaga Kerja', 'C', 'Persentase Pekerja Formal => Merupakan indikator untuk melihat porsi jaminan kualitas dan stabilitas pasar kerja. Pekerja dikategorikan Formal jika berstatus sebagai Buruh/Karyawan/Pegawai atau Berusaha dibantu buruh tetap/dibayar. Rumusnya membandingkan total kelompok ini dengan basis pembagi yaitu total seluruh orang yang bekerja.', 10),
(198, 3, 'Mudah', 'BPS menggunakan data proyeksi penduduk untuk mengestimasi jumlah warga di tahun-tahun mendatang. Metode standar yang digunakan BPS bersama Bappenas untuk menghitung proyeksi penduduk antarsensus adalah ...', 'Metode Matematik Geometrik', 'Metode Lestari Eksponensial', 'Metode Interpolasi Garis Lurus', 'Metode Komponen (Cohort Component Method)', 'D', 'Metode Komponen (Cohort Component Method) => Dalam menyusun buku rilis resmi Proyeksi Penduduk Indonesia jangka panjang (seperti periode 2020–2050), BPS bersama Kementerian PPN/Bappenas menggunakan Metode Komponen Kohor sebagai standar utama.', 10),
(199, 3, 'Sedang', 'Jika jumlah wisman yang berkunjung ke suatu destinasi naik, namun Tingkat Penghunian Kamar (TPK) hotel bintang menurun, parameter akomodasi apa yang paling mungkin menjelaskan fenomena ini?', 'Angka Kematian Bayi meningkat', 'Tingkat Pertumbuhan Ekonomi minus', 'Rata-rata Lama Menginap Tamu (RLMT) wisman menjadi lebih pendek', 'Jumlah hotel bintang berkurang drastis', 'C', 'Rata-rata Lama Menginap Tamu (RLMT) Menjadi Lebih Pendek => TPK tidak hanya dipengaruhi oleh berapa banyak orang yang datang, tetapi juga oleh berapa lama mereka memesan kamar tersebut. Jika jumlah wisman melesat tinggi namun mereka hanya menginap dalam waktu singkat (misal : hanya 1 malam dari yang biasanya 3 malam), maka akumulasi jumlah malam kamar terjual dalam satu bulan akan merosot, sehingga menurunkan persentase TPK. (Catatan : Faktor lain di dunia nyata adalah adanya pergeseran minat wisman ke akomodasi alternatif non-bintang seperti villa/homestay).', 10),
(200, 3, 'Mudah', 'Indikator yang digunakan BPS untuk mengukur volume aktivitas pengiriman barang melalui moda transportasi laut domestik antar-pelabuhan di Indonesia disebut ...', 'Arus Penumpang Udara Regional', 'Cargo International Load', 'Bongkar Muat Angkutan Laut Dalam Negeri', 'Tonase Ekspor Migas Berjalan', 'C', 'Dalam rilis bulanan Statistik Pariwisata dan Transportasi, Badan Pusat Statistik (BPS) menggunakan indikator Bongkar/Muat Barang Angkutan Laut Antar Pulau / Dalam Negeri untuk merekam volume komoditas domestik yang dikirim secara legal lewat jalur laut.\"\r\nBongkar\" mencerminkan volume barang yang diturunkan (pembongkaran kargo) di pelabuhan tujuan, sedangkan \"Muat\" mencerminkan volume barang yang dinaikkan (pemuatan kargo) dari pelabuhan asal. Indikator ini sangat penting untuk melihat intensitas logistik dan perdagangan domestik di negara kepulauan seperti Indonesia.', 10),
(201, 3, 'Mudah', 'Nilai transaksi bruto dari seluruh penjualan barang dan jasa melalui platform digital/e-commerce di suatu wilayah diukur dengan indikator makro ekonomi digital yang disebut ...', 'GMV (Gross Merchandise Value)', 'Net Income Margin', 'Indeks Harga Konsumen Digital', 'PDRB Sektoral Jasa', 'A', 'GMV (Gross Merchandise Value) => Merupakan indikator utama dalam ekonomi digital untuk mengukur total nilai moneter kotor (bruto) dari seluruh barang atau jasa yang terjual melalui situs/aplikasi belanja online (e-commerce atau marketplace) dalam periode waktu tertentu. Nilai GMV dihitung sebelum dikurangi biaya operasional, diskon, pengembalian barang (refund), atau biaya pengiriman, sehingga menjadi cerminan utama seberapa besar perputaran uang dan skala pertumbuhan ekosistem ekonomi digital di suatu wilayah.', 10),
(202, 1, 'Sedang', 'Sebuah survei BPS menggunakan metode Stratified Random Sampling. Apa tujuan utama dilakukannya stratifikasi (pengelompokkan) populasi sebelum penarikan sampel dilakukan?', 'Memperbanyak jumlah responden agar petugas mendapat honor lebih', 'Meningkatkan presisi estimasi dengan membuat kelompok yang homogen di dalam strata', 'Mempercepat proses pencetakan dokumen kuesioner fisik', 'Menghilangkan penduduk usia produktif dari daftar pencacahan', 'B', 'Metode Stratified Random Sampling (Pengambilan Sampel Acak Berstrata) digunakan ketika populasi yang diteliti bersifat heterogen (beragam). Konsep utama metode ini adalah membagi populasi ke dalam beberapa tingkatan atau kelompok subpopulasi (strata).\r\n1. Pembagian ini dilakukan sedemikian rupa agar elemen di dalam satu strata bersifat homogen (mirip/serupa), sementara karakteristik antarstrata berbeda secara \r\n     nyata.\r\n2. Dengan membuat kelompok yang homogen di dalam strata, variasi (variance) data di dalam kelompok terkontrol dengan baik. Efeknya, presisi (ketepatan) nilai \r\n    estimasi statistik meningkat jauh lebih tinggi dan sampel yang diambil menjadi sangat representatif mencerminkan struktur populasi asli. (Contoh klasiknya di BPS \r\n    adalah pengelompokan wilayah sampel ke dalam strata Perkotaan/Urban dan Perdesaan/Rural).', 10),
(203, 3, 'Sedang', 'Di suatu wilayah, Laju Pertumbuhan Ekonomi tahun 2024 adalah 5,0% dan tahun 2025 adalah 4,8%. Pernyataan yang paling tepat mengenai kondisi ekonomi wilayah tersebut adalah ...', 'Ekonomi wilayah tersebut mengalami resesi dan penurunan nilai riil', 'Nilai PDRB ADHK tahun 2025 lebih kecil daripada tahun 2024', 'Ekonomi tetap tumbuh positif pada tahun 2025, namun dengan kecepatan yang sedikit melambat', 'Terjadi deflasi massal di seluruh lapangan usaha', 'C', 'Angka pertumbuhan ekonomi tahun 2025 adalah +4,8%. Karena nilainya masih positif (di atas 0%), artinya volume produksi barang dan jasa (PDRB ADHK) wilayah tersebut tetap mengalami peningkatan atau tumbuh dibandingkan tahun sebelumnya. Namun, karena angka 4,8% lebih kecil dibanding angka 5,0% pada tahun 2024, kecepatan akselerasi pertumbuhannya saja yang sedikit melambat.', 10),
(204, 3, 'Sedang', 'Indeks Kebahagiaan Provinsi X naik dari 71,2 menjadi 72,5. Peningkatan ini paling valid dikaitkan dengan perbaikan pada aspek ...', 'Kenaikan harga barang impor non-migas di pasar lokal', 'Peningkatan jumlah produksi padi gurem saja', 'Peningkatan kepuasan hidup, pengelolaan emosi positif, dan pemaknaan hidup masyarakat', 'Penurunan jumlah blok sensus dalam pemutakhiran wilayah', 'C', 'Sejak adanya pembaruan metodologi, indeks ini disusun berdasarkan 3 dimensi utama :\r\n1. Dimensi Kepuasan Hidup (Life Satisfaction) : Mencakup kepuasan personal (pendidikan, pekerjaan, pendapatan, kesehatan, rumah) dan kepuasan sosial (hubungan \r\n    sosial, keamanan, kondisi lingkungan).\r\n2. Dimensi Perasaan (Affect) / Pengelolaan Emosi : Mencakup perasaan senang, tidak cemas/khawatir, dan tingkat stres masyarakat sehari-hari.\r\n3. Dimensi Makna Hidup (Eudaimonia) / Pemaknaan Hidup : Mencakup kemandirian, penguasaan lingkungan, pengembangan diri, hubungan positif dengan orang lain, \r\n    dan tujuan hidup.', 10),
(205, 2, 'Mudah', 'Saat melakukan pengawasan, PML menemukan bahwa PCL mengisi kuesioner tanpa mendatangi responden (melakukan copy-paste data/menebak isian). Pelanggaran kode etik petugas ini disebut sebagai ...', 'Non-Response Bias', 'Sampling Error', 'Pencil Cavity / Fabrication (Fabrikasi Data)', 'Undercoverage', 'C', 'Pencil Cavity / Fabrication (Fabrikasi Data) => Merupakan pelanggaran kode etik dan integritas paling berat yang dilakukan oleh petugas pencacah lapangan (PCL). Istilah pencil cavity atau dikenal juga dengan sebutan \"pencacahan di atas meja\" merujuk pada tindakan manipulasi di mana petugas tidak mendatangi rumah responden sama sekali, melainkan mengarang, menebak, atau menyalin (copy-paste) data isian kuesioner secara sepihak. Tindakan ini merusak validitas data nasional dan dapat berujung pada pemutusan kontrak kerja serta sanksi hukum sesuai UU No. 16 Tahun 1997.', 10),
(206, 2, 'Mudah', 'Apa yang harus dilakukan pertama kali oleh seorang petugas pencacah (PCL) jika mendapatkan penolakan keras (hard refusal) dari sebuah rumah tangga sampel?', 'Mengganti sampel tersebut dengan tetangganya secara sepihak', 'Memaksa masuk ke dalam rumah dan mengisi kuesioner secara sepihak', 'Melaporkan kepada Pengawas (PML) atau Ketua RT setempat untuk melakukan pendekatan ulang', 'Mengosongkan kuesioner dan menganggap survei selesai', 'C', 'Berdasarkan Standard Operating Procedure (SOP) pencacahan lapangan BPS, jika PCL menghadapi penolakan keras (hard refusal), tindakan pertama yang harus diambil adalah tetap bersikap sopan, menahan diri, dan segera melaporkan kendala tersebut kepada Pengawas Lapangan (PML) atau berkoordinasi dengan Ketua RT/RW setempat. PML atau pengurus wilayah akan membantu melakukan pendekatan ulang (refusal conversion) dengan memberikan penjelasan yang lebih persuasif mengenai urgensi data, legalitas tugas (membawa surat tugas resmi), serta jaminan keamanan kerahasiaan data sesuai undang-undang.', 10),
(207, 2, 'Sedang', 'Tahapan dalam pengolahan data BPS di mana petugas melakukan pengecekan konsensus logis antar-isian pertanyaan di dalam kuesioner (misal : usia anak tidak boleh lebih tua dari usia ibu) dinamakan ...', 'Data Entry', 'Scanning Dokumen', 'Editing & Coding (Penyuntingan dan Penyandian)', 'Tabulasi Makro', 'C', 'Tahapan ini merupakan langkah awal yang krusial dalam proses pengolahan dokumen fisik hasil pencacahan lapangan.\r\n- Editing (Penyuntingan) bertugas memeriksa kelengkapan isian kuesioner, keterbacaan tulisan petugas, dan konsistensi logis antar-jawaban (seperti contoh pada soal : \r\n   memastikan keogisan umur, atau jika statusnya \"belum kawin\" maka kolom info anak harus kosong).\r\n- Coding (Penyandian) bertugas mengubah jawaban tekstual dari responden menjadi kode angka digital standar baku BPS (seperti kode jenis pekerjaan, kode \r\n   pendidikan, atau kode wilayah MFD) agar mudah dimasukkan ke dalam sistem komputer.', 10),
(208, 3, 'Mudah', 'Dalam statistik keuangan pemerintah daerah yang disusun BPS, komponen Pendapatan Asli Daerah (PAD) terkecil umumnya bersumber dari ...', 'Pajak Daerah', 'Retribusi Daerah', 'Lain-lain PAD yang Sah dengan nilai nominal fluktuatif kecil', 'Dana Alokasi Umum (DAU) dari Pemerintah Pusat', 'B', 'Secara umum di hampir seluruh pemerintah daerah (Provinsi maupun Kabupaten/Kota) di Indonesia, kontribusi Retribusi Daerah (seperti retribusi parkir, pelayanan kesehatan, atau pasar) mencatatkan persentase dan nilai nominal paling kecil dibandingkan komponen PAD lainnya. Hal ini terjadi karena banyak penyesuaian regulasi (seperti UU HKPD) yang menghapus beberapa jenis retribusi daerah demi mengurangi beban ekonomi masyarakat.', 10),
(209, 3, 'Mudah', 'Dalam mengukur kemiskinan, BPS menggunakan konsep kemampuan memenuhi kebutuhan dasar (basic needs approach). Penduduk dikategorikan sebagai penduduk miskin jika ...', 'Memiliki pengeluaran per kapita per bulan di bawah Garis Kemiskinan', 'Tidak memiliki pekerjaan tetap atau berstatus pengangguran', 'Memiliki pendapatan di bawah Upah Minimum Regional (UMR)', 'Tidak memiliki aset berupa tanah atau kendaraan pribadi', 'A', 'BPS mengukur pemenuhan kebutuhan tersebut bukan berdasarkan lembar pendapatan, melainkan dari sisi pengeluaran riil masyarakat. Garis Kemiskinan (GK) ditetapkan sebagai nilai minimum rupiah yang harus dikeluarkan seseorang setiap bulannya untuk bertahan hidup layak. Oleh karena itu, siapa saja yang rata-rata pengeluaran per kapita per bulannya berada di bawah angka batas (Garis Kemiskinan) tersebut secara otomatis akan dikategorikan sebagai penduduk miskin.', 10),
(210, 3, 'Mudah', 'Indikator statistik yang digunakan untuk mengukur rata-rata jumlah anak yang akan dilahirkan oleh seorang wanita sepanjang masa reproduksinya disebut ...', 'Crude Birth Rate (CBR)', 'Total Fertility Rate (TFR)', 'Age Specific Fertility Rate (ASFR)', 'Infant Mortality Rate (IMR)', 'B', 'Total Fertility Rate (TFR) atau Angka Kelahiran Total adalah indikator demografi yang mengukur rata-rata jumlah anak yang akan dilahirkan oleh seorang wanita sepanjang masa reproduksinya (usia 15–49 tahun). Nilai TFR diperoleh dari penjumlahan angka kelahiran menurut kelompok umur (Age Specific Fertility Rate). Indikator ini sangat penting bagi Badan Pusat Statistik (BPS) dan pemerintah untuk memproyeksikan pertumbuhan penduduk masa depan.', 10),
(211, 3, 'Sedang', 'Untuk mengukur aktivitas sektor pariwisata, BPS menggunakan indikator TPK. Apa kepanjangan dan fungsi dari indikator TPK tersebut?', 'Tingkat Pemesanan Kamar; mengukur jumlah turis yang memesan hotel via daring', 'Tingkat Pengeluaran Konsumen; mengukur rata-rata belanja wisatawan asing', 'Tingkat Kunjungan Pelancong; mengukur jumlah total pergerakan wisatawan domestik', 'Tingkat Penghunian Kamar; mengukur persentase malam kamar yang terpakai pada usaha akomodasi', 'D', 'TPK adalah singkatan dari Tingkat Penghunian Kamar (Room Occupancy Rate). Indikator ini digunakan oleh Badan Pusat Statistik (BPS) untuk mengukur produktivitas dan aktivitas ekonomi di sektor akomodasi pariwisata.', 10),
(212, 3, 'Sedang', 'Dalam statistik perdagangan luar negeri yang dirilis BPS, nilai ekspor barang dicatat menggunakan sistem penilaian tertentu, sedangkan nilai impor dicatat menggunakan sistem penilaian yang berbeda. Sistem penilaian tersebut adalah ...', 'Ekspor menggunakan CIF (Cost, Insurance, and Freight), Impor menggunakan FOB (Free on Board)', 'Ekspor menggunakan FOB (Free on Board), Impor menggunakan CIF (Cost, Insurance, and Freight)', 'Ekspor dan Impor keduanya menggunakan nilai FOB (Free on Board)', 'Ekspor dan Impor keduanya menggunakan nilai CIF (Cost, Insurance, and Freight)', 'B', 'Dalam menyusun Statistik Perdagangan Luar Negeri, Badan Pusat Statistik (BPS) mengadopsi standar internasional pencatatan nilai barang sebagai berikut : \r\n- Nilai Ekspor dicatat dalam FOB (Free on Board) : Nilai yang dinilai adalah harga barang murni hingga komoditas tersebut selesai dimuat ke atas kapal di pelabuhan \r\n   keberangkatan Indonesia. Nilai ini belum termasuk ongkos kirim laut (freight) dan asuransi perjalanan ke negara tujuan.\r\n- Nilai Impor dicatat dalam CIF (Cost, Insurance, and Freight) : Nilai yang dinilai mencakup harga barang (cost), ditambah biaya asuransi (insurance), serta biaya \r\n  pengangkutan kapal (freight) dari negara asal hingga barang tersebut tiba di pelabuhan pembongkaran Indonesia.', 10),
(213, 3, 'Mudah', 'Indikator ketenagakerjaan BPS yang menunjukkan beban ekonomi yang harus ditanggung oleh penduduk usia produktif untuk membiayai penduduk usia non-produktif disebut ...', 'Dependency Ratio (Rasio Ketergantungan)', 'Employment-to-Population Ratio (EPR)', 'Labor Force Participation Rate (LFPR)', 'Rasio Ketimpangan Produktivitas', 'A', 'Rasio Ketergantungan (Dependency Ratio) atau rasio beban tanggungan adalah indikator demografi dan ketenagakerjaan yang menyatakan perbandingan antara jumlah penduduk usia non-produktif dengan jumlah penduduk usia produktif.\r\n- Penduduk Usia Non-Produktif : Anak-anak berusia 0–14 tahun dan lansia berusia 65 tahun ke atas.\r\n- Penduduk Usia Produktif : Penduduk usia kerja yang berumur 15–64 tahun.', 10),
(214, 3, 'Sedang', 'BPS merilis Indeks Perilaku Anti Korupsi (IPAK) secara berkala. Apa skala penilaian yang digunakan dalam IPAK dan bagaimana interpretasi hasilnya?', 'Skala 0 - 1; semakin mendekati 1 artinya masyarakat semakin permisif terhadap korupsi', 'Skala 0 - 5; semakin mendekati 5 artinya masyarakat semakin anti terhadap perilaku korupsi', 'Skala 0 - 100; semakin mendekati 100 artinya instansi pemerintah semakin bebas korupsi', 'Skala persen (%); semakin tinggi persentasenya artinya tingkat korupsi semakin menurun', 'B', 'Berdasarkan ketentuan Badan Pusat Statistik (BPS), Indeks Perilaku Anti Korupsi (IPAK) diukur menggunakan skala rentang 0 hingga 5. Interpretasi dari indikator ini dinilai linier dengan besaran angkanya:\r\n- Semakin mendekati angka 5 : Menunjukkan performa yang semakin baik, artinya tingkat kesadaran masyarakat semakin tinggi dan semakin anti terhadap perilaku \r\n   korupsi.\r\n- Semakin mendekati angka 0 : Menunjukkan kondisi yang buruk, artinya masyarakat cenderung semakin permisif (memaklumi atau menganggap wajar) terhadap \r\n   tindakan korupsi skala kecil (petty corruption) dalam kehidupan sehari-hari.', 10),
(215, 3, 'Mudah', 'Indikator statistik ekonomi yang dirilis BPS untuk memantau fluktuasi harga bahan mentah dan barang grosir yang diperdagangkan di tingkat produsen sebelum masuk ke pasar konsumen adalah ...', 'Indeks Harga Konsumen (IHK)', 'Indeks Harga Produsen Manufaktur (IHPM)', 'Indeks Harga Perdagangan Besar (IHPB)', 'Indeks Nilai Tukar Perdagangan (NTP)', 'C', 'Indeks Harga Perdagangan Besar (IHPB) atau dikenal secara internasional sebagai Wholesale Price Index (WPI) merupakan indeks yang mengukur perubahan harga dari paket barang yang diperdagangkan di tingkat grosir/agen/perdagangan besar. Barang-barang yang dicakup meliputi bahan mentah, bahan baku, dan barang hasil olahan dari sektor pertanian, pertambangan/penggalian, serta industri. Fluktuasi pada IHPB berfungsi sebagai indikator dini (early warning) untuk memprediksi perubahan harga di pasar konsumen (IHK) di masa mendatang.', 10),
(216, 3, 'Sedang', 'Pemerintah Indonesia menargetkan penghapusan kemiskinan ekstrem. Berdasarkan metodologi yang digunakan BPS (merujuk standar Bank Dunia), seorang penduduk dikategorikan berada dalam kemiskinan ekstrem jika pengeluarannya per hari berada di bawah ...', 'USD 1,90 Purchasing Power Parity (PPP)', 'USD 2,15 Purchasing Power Parity (PPP)', 'USD 3,20 Purchasing Power Parity (PPP)', 'USD 5,50 Purchasing Power Parity (PPP)', 'B', 'Badan Pusat Statistik (BPS) mengadopsi standar internasional terbaru dari Bank Dunia untuk mengukur tingkat kemiskinan ekstrem di Indonesia. Bank Dunia telah menaikkan garis kemiskinan ekstrem internasional dari batas lama USD 1,90 menjadi USD 2,15 per kapita per hari dengan basis penyesuaian daya beli atau Purchasing Power Parity (PPP).\r\nUSD 2,15 PPP : Batas konversi daya beli yang digunakan sebagai indikator utama untuk memantau agenda global penghapusan kemiskinan ekstrem.', 10),
(217, 3, 'Mudah', 'Jika BPS merilis data Neraca Perdagangan Indonesia mengalami surplus, maka kondisi yang menggambarkan indikator tersebut adalah ...', 'Nilai ekspor barang dan jasa lebih besar daripada nilai impornya', 'Nilai investasi asing yang masuk lebih besar daripada investasi keluar', 'Jumlah cadangan devisa di Bank Indonesia mengalami penurunan', 'Pendapatan pajak negara lebih tinggi daripada belanja APBN', 'A', 'Neraca Perdagangan (Balance of Trade) adalah indikator ekonomi yang menghitung selisih antara nilai total ekspor dan nilai total impor suatu negara dalam jangka waktu tertentu.\r\n- Surplus Perdagangan : Terjadi apabila pendapatan negara dari hasil penjualan (ekspor) barang dan jasa ke luar negeri jauh lebih besar dibandingkan pengeluaran \r\n   untuk membeli (impor) produk asing. Kondisi ini bersifat positif karena menambah akumulasi aliran modal masuk ke dalam perekonomian domestik.\r\n- Defisit Perdagangan : Kondisi sebaliknya, yaitu ketika nilai barang/jasa yang dibeli dari luar negeri (impor) lebih tinggi daripada komoditas yang berhasil dijual \r\n   (ekspor).', 10),
(218, 3, 'Mudah', 'Indikator statistik ekonomi BPS yang mengukur rata-rata perubahan harga yang diterima oleh produsen domestik atas barang yang mereka hasilkan (sering dianggap sebagai indikator awal inflasi sebelum menyentuh konsumen) adalah ...', 'Indeks Harga Konsumen (IHK)', 'Indeks Harga Produsen (IHP)', 'Indeks Harga Perdagangan Besar (IHPB)', 'Indeks Nilai Tukar Petani (NTP)', 'B', 'Indeks Harga Produsen (IHP) atau Producer Price Index (PPI) adalah indikator ekonomi yang secara spesifik mengukur rata-rata perubahan harga yang diterima oleh produsen domestik ketika mereka menjual hasil produksinya pada tingkat tangan pertama (pasar primer).\r\nIHP mencakup sektor-sektor produksi hulu hingga hilir seperti pertanian, pertambangan, dan industri pengolahan. Fluktuasi pada IHP sangat penting karena menjadi indikator awal (early warning) pergerakan inflasi. Ketika biaya produksi di tingkat produsen naik, kenaikan harga tersebut lambat laun akan dibebankan kepada konsumen akhir di pasar eceran.', 10),
(219, 3, 'Mudah', 'Dalam Sakernas (Survei Angkatan Kerja Nasional) yang diselenggarakan oleh BPS, konsep \"Bekerja\" didefinisikan sebagai kegiatan melakukan pekerjaan dengan maksud memperoleh atau membantu memperoleh pendapatan atau keuntungan, dengan durasi minimal ...', 'Minimal 1 jam dalam seminggu yang lalu (secara berturut-turut maupun tidak)', 'Minimal 2 jam per hari selama seminggu yang lalu', 'Minimal 35 jam dalam seminggu yang lalu (standar pekerja penuh)', 'Minimal 15 jam dalam seminggu yang lalu tanpa terputus', 'A', 'Menurut konsep BPS, seseorang dikategorikan Bekerja jika ia melakukan kegiatan ekonomi dengan maksud memperoleh atau membantu memperoleh pendapatan, keuntungan, atau upah/gaji, dengan durasi minimal 1 jam selama seminggu (tujuh hari berturut-turut) yang lalu sebelum pencacahan. Durasi 1 jam ini boleh dilakukan secara kumulatif (total waktu) dan tidak harus dilakukan dalam satu waktu yang sama tanpa terputus.', 10),
(220, 2, 'Mudah', 'BPS membagi wilayah sensus/survei menjadi unit-unit geografis terkecil yang homogen untuk memudahkan proses pencacahan oleh petugas di lapangan. Unit geografis terkecil ini disebut dengan istilah ...', 'Blok Sensus (BS)', 'Satuan Lingkungan Setempat (SLS)', 'Kluster Wilayah (KW)', 'Daerah Cacah Eksklusif (DCE)', 'A', 'Blok Sensus (BS) adalah unit geografis terkecil yang dibentuk oleh Badan Pusat Statistik (BPS) untuk keperluan pemetaan dan pengumpulan data lapangan (sensus maupun survei). Sebuah Blok Sensus dirancang sedemikian rupa agar bersifat homogen dan memiliki batas-batas alam (seperti sungai, jalan, atau parit) atau batas buatan yang jelas di lapangan. Umumnya, satu Blok Sensus memuat muatan sekitar 80 hingga 120 rumah tangga agar beban kerja pencacahan bagi seorang petugas lapangan menjadi terukur dan efisien.', 10),
(221, 3, 'Mudah', 'Dalam penyusunan Produk Domestik Bruto (PDB), metode yang menghitung nilai tambah bruto yang dihasilkan oleh seluruh lapangan usaha (sektor ekonomi) di suatu wilayah dalam kurun waktu tertentu disebut PDB berdasarkan pendekatan ...', 'Pengeluaran (Expenditure Approach)', 'Pendapatan (Income Approach)', 'Produksi/Lapangan Usaha (Production Approach)', 'Konsumsi (Consumption Approach)', 'C', 'Pendekatan Produksi (Production Approach) => Menghitung total nilai output barang dan jasa yang dihasilkan seluruh unit produksi dikurangi biaya antara (bahan baku/penolong) untuk mendapatkan nilai tambah bersih di setiap lapangan usaha.', 10),
(222, 3, 'Sedang', 'BPS mengukur keterlibatan perempuan dalam posisi pengambilan keputusan dan peran aktif ekonomi melalui sebuah indikator khusus. Indikator yang mengukur persentase sumbangan pendapatan perempuan, keterwakilan di parlemen, serta posisi sebagai manajer/profesional dinamakan ...', 'Indeks Ketimpangan Gender (IKG)', 'Indeks Pemberdayaan Gender (IDG)', 'Indeks Pembangunan Gender (IPG)', 'Indeks Keadilan Gender (IKeG)', 'B', 'Indeks Pemberdayaan Gender (IDG) adalah indikator komposit BPS yang mengukur apakah perempuan dapat memainkan peran aktif dalam kehidupan ekonomi, politik, serta pengambilan keputusan. IDG menitikberatkan pada aspek partisipasi dan kekuasaan dengan menggunakan tiga komponen indikator penyusun, yaitu :\r\n1. Partisipasi Politik : Diukur dari persentase keterwakilan perempuan di parlemen.\r\n2. Pengambilan Keputusan Ekonomi : Diukur dari persentase perempuan yang bekerja pada posisi manajerial, profesional, administrasi, dan teknisi.\r\n3. Penguasaan Sumber Daya Ekonomi : Diukur dari persentase sumbangan pendapatan perempuan dari total pendapatan kerja.', 10),
(223, 2, 'Sedang', 'Hari Statistik Nasional (HSN) diperingati setiap tanggal 26 September untuk mengenang lahirnya Undang-Undang Nomor 7 Tahun 1960 tentang Statistik. Lembaga pemerintah non-kementerian di Indonesia yang bertanggung jawab langsung menyediakan data statistik nasional adalah ...', 'Badan Perencanaan Pembangunan Nasional (Bappenas)', 'Badan Pusat Statistik (BPS)', 'Bank Indonesia (BI)', 'Kementerian Dalam Negeri (Kemendagri)', 'B', 'Berdasarkan amanat Undang-Undang Nomor 16 Tahun 1997 tentang Statistik (yang memperbarui UU No. 7 Tahun 1960), Badan Pusat Statistik (BPS) adalah Lembaga Pemerintah Non-Kementerian (LPNK) yang memegang tanggung jawab penuh dan mandiri dalam menyediakan data statistik dasar secara nasional. BPS berkedudukan di bawah Presiden Indonesia dan menyampaikan laporan pertanggungjawabannya secara langsung kepada Presiden.', 10),
(224, 2, 'Mudah', 'Dalam struktur ketatanegaraan Indonesia, Kepala Badan Pusat Statistik (BPS) bertanggung jawab langsung kepada ...', 'Dewan Perwakilan Rakyat (DPR)', 'Menteri Dalam Negeri', 'Menteri Keuangan', 'Presiden', 'D', 'Berdasarkan Undang-Undang Nomor 16 Tahun 1997 tentang Statistik dan Peraturan Presiden terkait struktur kelembagaan, Badan Pusat Statistik (BPS) merupakan Lembaga Pemerintah Non-Kementerian (LPNK). Sebagai LPNK, BPS berada di bawah dan bertanggung jawab langsung kepada Presiden.', 10),
(225, 2, 'Sedang', 'Perhatikan tabel tahun pelaksanaan sensus di bawah ini :\r\n(1) Sensus Penduduk : Tahun berakhiran angka 0 (contoh : 2010, 2020)\r\n(2) Sensus Pertanian : Tahun berakhiran angka 3 (contoh : 2013, 2023)\r\n(3) Sensus Ekonomi : Tahun berakhiran angka 6 (contoh : 2006, 2016)\r\n\r\nManakah pola periodisasi pelaksanaan sensus oleh BPS yang benar?', '(1) dan (2) saja', '(1) dan (3) saja', '(2) dan (3) saja', '(1), (2), dan (3) semua benar', 'D', 'Berdasarkan Undang-Undang Nomor 16 Tahun 1997 tentang Statistik, Badan Pusat Statistik (BPS) diamanatkan untuk menyelenggarakan tiga jenis sensus nasional. Masing-masing sensus tersebut dilaksanakan dalam jangka waktu 10 tahun sekali dengan pola periodisasi angka tahun berakhiran yang sangat konsisten dan teratur agar memudahkan perencanaan nasional :\r\n1. Sensus Penduduk (SP) : Diselenggarakan pada tahun-tahun yang berakhiran angka 0. Contoh pelaksanaannya adalah pada tahun 2000, 2010, dan 2020.\r\n2. Sensus Pertanian (ST) : Diselenggarakan pada tahun-tahun yang berakhiran angka 3. Contoh pelaksanaannya adalah pada tahun 2003, 2013, dan 2023.\r\n3. Sensus Ekonomi (SE) : Diselenggarakan pada tahun-tahun yang berakhiran angka 6. Contoh pelaksanaannya adalah pada tahun 2006, 2016, dan yang saat ini sedang \r\n    masif dilaksanakan di lapangan adalah Sensus Ekonomi 2026.', 10),
(226, 2, 'Sulit', 'Dalam rilis data ketenagakerjaan dan kemiskinan, BPS menggunakan sampel rumah tangga yang diperoleh dari survei berbasis rumah tangga terbesar di Indonesia. Survei rutin yang menjadi tulang punggung data sosial-ekonomi tersebut adalah ...', 'Sakernas (Survei Angkatan Kerja Nasional) & Susenas (Survei Sosial Ekonomi Nasional)', 'Potensi Desa (Podes) & Survei Harga Perdagangan Besar (IHPB)', 'Intercensal Population Survey (SUPAS) & Sensus Ekonomi', 'Survei Komoditas Hankam & Survei Demografi Kesehatan Indonesia (SDKI)', 'A', 'Badan Pusat Statistik (BPS) mengandalkan dua survei rumah tangga berskala besar yang menjadi pilar utama (backbone) data sosial-ekonomi nasional secara rutin :\r\n1. Susenas (Survei Sosial Ekonomi Nasional) : Merupakan tulang punggung utama untuk menghitung angka kemiskinan makro. Survei ini mengumpulkan data \r\n    pengeluaran konsumsi makanan dan non-makanan rumah tangga, pendidikan, kesehatan, serta perumahan.\r\n2. Sakernas (Survei Angkatan Kerja Nasional) : Merupakan tulang punggung utama untuk menghasilkan indikator ketenagakerjaan, seperti Tingkat Pengangguran \r\n    Terbuka (TPT) dan Tingkat Partisipasi Angkatan Kerja (TPAK).', 10),
(227, 2, 'Sulit', 'BPS mempublikasikan seluruh jadwal rilis data statistik makro (seperti inflasi dan pertumbuhan ekonomi) satu tahun penuh di muka melalui kalender resmi yang dapat diakses publik. Prinsip internasional Fundamental Principles of Official Statistics yang paling tecermin dari tindakan ini adalah ...', 'Professional Independence (Independensi Profesional)', 'Accountability and Transparency (Akuntabilitas dan Transparansi)', 'Confidentiality (Kerahasiaan Data Individu)', 'International Coordination (Koordinasi Internasional', 'A', 'Tindakan Badan Pusat Statistik (BPS) mengumumkan jadwal rilis data makro setahun penuh di muka melalui kalender resmi—yang dikenal sebagai Advance Release Calendar (ARC)—merupakan penerapan nyata dari prinsip ke-7 Fundamental Principles of Official Statistics (FPOS) oleh PBB, yaitu Accountability and Transparency.\r\nDengan menyediakan kalender rilis yang pasti, BPS menunjukkan akuntabilitas dan transparansi kepada publik mengenai kapan data dapat diakses oleh semua pihak secara serentak. Hal ini penting untuk mencegah kebocoran informasi (data leaks), menghindari manipulasi waktu rilis untuk kepentingan politik, serta memberikan kepastian bagi para pelaku pasar ekonomi dan pengambil kebijakan.', 10),
(228, 2, 'Sulit', 'Menurut UU No. 16 Tahun 1997, pengumpulan data statistik sektoral merupakan tugas mandiri instansi pemerintah/kementerian terkait. Namun, dalam pelaksanaannya, instansi tersebut wajib melakukan salah satu tindakan berikut terhadap BPS untuk menghindari duplikasi data. Tindakan yang dimaksud adalah ...', 'Meminta izin tertulis dan membayar royalti data kepada BPS', 'Menyerahkan seluruh anggaran survei sektoral untuk dikelola BPS', 'Melakukan konsultasi dan menyerahkan hasil kerja statistiknya kepada BPS', 'Menjadikan Kepala BPS sebagai ketua pelaksana survei sektoral tersebut', 'C', 'Berdasarkan Undang-Undang Nomor 16 Tahun 1997 tentang Statistik, penyelenggaraan statistik sektoral (statistik yang pemanfaatannya ditujukan untuk memenuhi kebutuhan instansi tertentu dalam rangka tugas-tugas pemerintahan dan pembangunan) wajib dikoordinasikan dengan BPS.\r\nTindakan wajib ini diatur demi menghindari terjadinya duplikasi (penumpukan) kegiatan pengumpulan data yang sama antar-instansi pemerintah, serta untuk menjaga standarisasi kaidah statistik. Ketentuan teknisnya meliputi :\r\n1. Melakukan Konsultasi : Instansi pemerintah wajib memberitahukan dan berkonsultasi mengenai rencana serta rancangan survei sektoralnya kepada BPS sebelum \r\n    kegiatan lapangan dimulai.\r\n2. Menyerahkan Hasil : Setelah survei selesai, instansi tersebut wajib menyerahkan hasil atau produk akhir dari statistik sektoral yang diperolehnya kepada BPS.', 10),
(229, 3, 'Sedang', 'Indeks Pembangunan Manusia (IPM) yang dirilis BPS menggunakan komponen \"Usia Harapan Hidup saat Lahir\" (UHH). Jika di suatu kabupaten nilai UHH meningkat tajam, maka hal tersebut secara langsung mencerminkan keberhasilan performa wilayah pada dimensi ...', 'Standar hidup layak', 'Umur panjang dan hidup sehat', 'Pengetahuan umum masyarakat', 'Produktivitas angkatan kerja ekonomi', 'B', 'Dimensi Umur Panjang dan Hidup Sehat (A Long and Healthy Life) => Diukur menggunakan indikator Usia Harapan Hidup saat Lahir (UHH). UHH mencerminkan rata-rata perkiraan jumlah tahun yang dapat ditempuh oleh seseorang sejak lahir jika pola kematian pada setiap lapisan umur tetap sama. Peningkatan tajam pada UHH di suatu kabupaten secara langsung menandakan adanya perbaikan pada kualitas kesehatan masyarakat, akses layanan medis, dan penurunan angka kematian bayi/ibu di wilayah tersebut.', 10),
(230, 3, 'Sedang', 'Mengapa dalam menghitung inflasi eceran bulanan, BPS menggunakan diagram timbang (bobot komoditas) yang diperoleh dari Survei Biaya Hidup (SBH), bukannya langsung merata-ratakan seluruh harga barang di pasar?', 'Agar komoditas yang paling banyak dikonsumsi masyarakat mendapat porsi pengaruh yang lebih besar terhadap angka inflasi', 'Untuk mempermudah petugas lapangan dalam memilih toko atau pasar yang akan disurvei', 'Karena aturan undang-undang melarang penghitungan statistik tanpa pembobotan nilai nominal', 'Agar komoditas barang mewah memiliki nilai inflasi yang setara dengan bahan pangan pokok', 'A', 'BPS menggunakan diagram timbang (bobot komoditas) yang diperbarui secara berkala melalui Survei Biaya Hidup (SBH). Fungsi utama dari diagram timbang ini adalah :\r\n1. Memberikan porsi pengaruh yang proporsional : Komoditas pokok yang sangat sering dibeli dan dikonsumsi masyarakat (seperti beras, tarif listrik, atau bensin) akan \r\n    diberikan bobot (weight) yang besar. Jika harga beras naik sedikit saja, dampaknya terhadap angka inflasi akan sangat terasa.\r\n2. Mencegah bias data : Komoditas yang jarang dibeli masyarakat (misalnya perhiasan atau barang mewah) akan diberikan bobot yang sangat kecil. Dengan demikian, \r\n    jika harga barang mewah tersebut melonjak tajam, hal tersebut tidak akan mengacaukan atau mendistorsi angka inflasi riil yang dirasakan oleh mayoritas \r\n    masyarakat luas.', 10),
(231, 3, 'Sulit', 'Dalam penghitungan Produk Domestik Bruto (PDB) Indonesia, BPS melakukan penyesuaian periodik berupa perubahan Tahun Dasar (misalnya dari Tahun Dasar 2000 ke Tahun Dasar 2010). Apa alasan metodologis utama dilakukannya perubahan Tahun Dasar ini?', 'Untuk menyelaraskan masa jabatan Kepala BPS dengan siklus data makro ekonomi', 'Mengakomodasi perubahan struktur ekonomi, pergeseran pola konsumsi masyarakat, dan munculnya jenis komoditas baru', 'Memastikan nilai inflasi tahunan selalu berada di bawah angka dua digit demi stabilitas negara', 'Memenuhi syarat bantuan pendanaan survei dari lembaga keuangan internasional', 'B', 'Perubahan Tahun Dasar dalam penghitungan Produk Domestik Bruto (PDB) dilakukan secara berkala oleh Badan Pusat Statistik (BPS) demi menjaga kualitas dan validitas data makroekonomi agar tetap relevan dengan kondisi riil di lapangan. Alasan metodologis utamanya meliputi :\r\n1. Perubahan Struktur Ekonomi : Seiring berjalannya waktu, perekonomian Indonesia terus bergeser. Sebagai contoh, peran sektor berbasis digital, teknologi informasi, \r\n    dan ekonomi kreatif kini jauh lebih besar dibandingkan satu atau dua dekade lalu.\r\n2. Pergeseran Pola Konsumsi : Kebutuhan dan kebiasaan belanja masyarakat mengalami perubahan nyata (misalnya meningkatnya alokasi anggaran untuk kuota \r\n    internet, belanja online, atau jasa transportasi digital).\r\n3. Komoditas Baru : Munculnya berbagai jenis barang dan jasa baru yang belum pernah diproduksi atau dikonsumsi pada tahun-tahun dasar sebelumnya.', 10),
(232, 2, 'Sedang', 'Dalam melakukan Survei Sosial Ekonomi Nasional (Susenas), BPS menggunakan kerangka sampel induk (Master Sampling Frame) yang disusun berdasarkan data dari basis data geospasial dan demografi tertentu. Basis data utama yang digunakan untuk menyusun kerangka sampel induk Susenas tersebut adalah ...', 'Data wajib pajak aktif dari Direktorat Jenderal Pajak', 'Hasil Sensus Penduduk (SP) terbaru yang terus dimutakhirkan', 'Laporan bulanan dari asosiasi pengusaha logistik Indonesia', 'Registrasi data kendaraan bermotor dari Korlantas POLRI', 'B', 'Dalam metodologi survei berbasis rumah tangga seperti Survei Sosial Ekonomi Nasional (Susenas), Badan Pusat Statistik (BPS) memerlukan daftar populasi yang lengkap dan akurat agar sampel yang ditarik bisa mewakili seluruh kondisi masyarakat secara objektif. Daftar populasi inilah yang menyusun Kerangka Sampel Induk (Master Sampling Frame / MSF).\r\nBasis data utama untuk menyusun MSF tersebut bersumber dari Hasil Sensus Penduduk (SP) terbaru [B1]. Karena Sensus Penduduk mencacah seluruh penduduk dan rumah tangga di Indonesia secara total (by name by address), BPS memiliki peta geospasial serta muatan Blok Sensus yang sangat detail. Kerangka sampel dari hasil sensus ini kemudian terus dimutakhirkan secara berkala oleh BPS di lapangan agar tetap mencerminkan perubahan demografi terbaru sebelum sampel acak Susenas dipilih.', 10),
(233, 3, 'Sulit', 'Indikator \"Angka Kematian Ibu\" (AKI) sangat sulit diukur secara akurat melalui survei sampel tahunan biasa (seperti Susenas) karena jumlah kasusnya yang relatif jarang terjadi pada skala sampel kecil (rare events). Untuk mengatasi keterbatasan metodologi ini, BPS biasanya mengestimasi angka AKI melalui kegiatan ...', 'Sensus Penduduk Long Form atau Survei Penduduk Antar Sensus (SUPAS)', 'Survei Harga Konsumen bulanan di wilayah perkotaan', 'Menggunakan proyeksi murni berdasarkan total angka kelahiran kasar (CBR)', 'Survei Khusus Lembaga Non-Profit (SKLNP)', 'A', 'Angka Kematian Ibu (AKI) atau Maternal Mortality Ratio (MMR) merupakan contoh klasik dari karakteristik data yang disebut rare events (peristiwa yang frekuensi kejadiannya relatif kecil/jarang di dalam populasi umum).\r\nUntuk mengatasi kendala metodologi ini, statistik memerlukan ukuran cakupan sampel yang sangat masif (large sample size). Oleh sebab itu, BPS mengestimasi AKI melalui kegiatan :\r\n1. Sensus Penduduk (SP) Long Form : Pendataan sampel berskala besar yang mengikuti rangkaian sensus lengkap untuk menggali data demografi mendalam.\r\n2. SUPAS (Survei Penduduk Antar Sensus):  Survei khusus kependudukan berskala nasional yang dilaksanakan tepat di pertengahan antara dua periode sensus \r\n    penduduk dengan jumlah sampel yang jauh lebih besar daripada survei sosial biasa.', 10),
(234, 3, 'Sedang', 'Dalam publikasi statistik BPS, terdapat indikator ketenagakerjaan bernama TPAK (Tingkat Partisipasi Angkatan Kerja). Angka TPAK ini dihitung dengan cara membandingkan ...', 'Jumlah angkatan kerja dengan jumlah seluruh penduduk usia kerja', 'Jumlah pekerja penuh dengan jumlah penganggur terbuka', 'Jumlah penduduk yang bekerja dengan jumlah seluruh penduduk', 'Jumlah angkatan kerja dengan jumlah penduduk non-produktif', 'A', 'Berdasarkan konsep ketenagakerjaan yang digunakan oleh Badan Pusat Statistik (BPS), Tingkat Partisipasi Angkatan Kerja (TPAK) merupakan indikator yang mengukur persentase penduduk usia kerja yang aktif secara ekonomi di pasar kerja.\r\nAngka TPAK dihitung dengan rumus membagi Jumlah Angkatan Kerja (yaitu total penduduk yang bekerja ditambah penduduk yang menganggur/mencari kerja) dengan Jumlah Seluruh Penduduk Usia Kerja (penduduk berumur 15 tahun ke atas), kemudian dikalikan 100 persen.', 10),
(235, 2, 'Sedang', 'Saat menyelenggarakan Sensus Pertanian atau Sensus Ekonomi, petugas BPS sering melakukan pendaftaran bangunan dan usaha/rumah tangga di seluruh wilayah tugasnya terlebih dahulu sebelum melakukan pencacahan detail. Tahapan awal sensus ini dikenal dengan istilah ...', 'Listing / Pencacahan Lengkap', 'Sampling / Pengambilan Contoh', 'Editing / Pemeriksaan Dokumen', 'Coding / Pemberian Kode Baku', 'A', 'Dalam rangkaian pelaksanaan kegiatan sensus (seperti Sensus Pertanian atau Sensus Ekonomi), tahapan awal yang krusial dilakukan oleh petugas lapangan adalah Listing atau disebut juga dengan istilah Pendaftaran/Pencacahan Lengkap.', 10),
(236, 3, 'Sedang', 'BPS menggunakan indikator IPM (Indeks Pembangunan Manusia) untuk mengukur kualitas hidup masyarakat. Komponen yang digunakan untuk menyusun dimensi Pengetahuan dalam IPM tersebut adalah ...', 'Angka Melek Huruf (AMH) dan Angka Partisipasi Murni (APM)', 'Rata-rata Lama Sekolah (RLS) dan Harapan Lama Sekolah (HLS)', 'Angka Partisipasi Kasar (APK) dan Tingkat Kelulusan Sekolah)', 'Angka Putus Sekolah (APS) dan Rasio Guru-Murid', 'B', 'Sejak tahun 2014, Badan Pusat Statistik (BPS) bersama dengan United Nations Development Programme (UNDP) telah memperbarui metodologi perhitungan Indeks Pembangunan Manusia (IPM). Pada Dimensi Pengetahuan, indikator penyusun yang digunakan secara resmi adalah :\r\n1. Rata-rata Lama Sekolah (RLS) / Mean Years of Schooling (MYS) : Mengukur rata-rata jumlah tahun yang telah ditempuh oleh penduduk berusia 25 tahun ke atas \r\n    dalam mengenyam pendidikan formal.\r\n2. Harapan Lama Sekolah (HLS) / Expected Years of Schooling (EYS) : Mengukur lamanya tahun sekolah (formal) yang diharapkan akan dirasakan oleh anak pada umur \r\n    tertentu di masa mendatang (dihitung untuk anak usia 7 tahun ke atas).', 10),
(237, 3, 'Sulit', 'BPS menghitung Indeks Harga Konsumen (IHK) menggunakan formula indeks yang dimodifikasi. Formula indeks yang secara umum digunakan oleh BPS untuk menghitung perubahan harga kelompok barang tersebut adalah formula ...', 'Paasche', 'Laspeyres', 'Fisher Ideal', 'Marshall-Edgeworth', 'B', 'Dalam menghitung Indeks Harga Konsumen (IHK) sebagai dasar penentuan angka inflasi bulanan, Badan Pusat Statistik (BPS) menggunakan rumus Laspeyres yang telah dimodifikasi (Modified Laspeyres Formula).\r\nKarakteristik utama dari indeks Laspeyres adalah menggunakan kuantitas barang pada tahun dasar (Q0) sebagai timbangan atau bobot tetap pembagi. Keunggulan metodologis dari formula ini adalah :\r\na. Konsistensi Penimbangan : Bobot pengeluaran komoditas (diagram timbang) tidak perlu diubah setiap bulan, melainkan dikunci berdasarkan data hasil Survei Biaya \r\n    Hidup (SBH) pada tahun dasar.\r\nb. Efisiensi Waktu : Memungkinkan BPS merilis angka inflasi dengan sangat cepat (setiap tanggal 1 pada bulan berikutnya) karena petugas lapangan hanya perlu \r\n    memperbarui data harga berjalan (Pt), tanpa harus menghitung ulang volume konsumsi masyarakat setiap bulannya.', 10),
(238, 3, 'Sulit', 'Dalam statistik pendapatan nasional (PDB), BPS menyajikan data PDB Atas Dasar Harga Konstan (ADHK). Metode yang paling sering digunakan BPS untuk menilai output riil suatu sektor usaha dengan cara membagi nilai nominal saat ini menggunakan indeks harga yang sesuai dinamakan ...', 'Revaluasi langsung', 'Ekstrapolasi volume', 'Deflasi (Deflating)', 'Penyesuaian kualitas (Hedonic Quality Adjustment)', 'C', 'Dalam menghitung Produk Domestik Bruto (PDB) Atas Dasar Harga Konstan (ADHK) untuk memperoleh nilai pertumbuhan ekonomi riil yang bersih dari pengaruh inflasi, Badan Pusat Statistik (BPS) menggunakan beberapa metode. Metode yang dilakukan dengan cara membagi nilai nominal saat ini (PDB Atas Dasar Harga Berlaku) menggunakan indeks harga yang sesuai dinamakan Deflasi (Deflating).\r\nIndeks harga yang digunakan sebagai pembagi umumnya adalah Indeks Harga Produsen (IHP), Indeks Harga Perdagangan Besar (IHPB), atau Indeks Harga Konsumen (IHK) yang relevan dengan sektor usaha tersebut.', 10),
(239, 2, 'Sedang', 'Dalam klasifikasi statistik BPS, terdapat standardisasi bernama KBJI (Klasifikasi Baku Jabatan Indonesia). Standardisasi ini secara khusus digunakan BPS untuk mengelompokkan data responden berdasarkan ...', 'Jenis produk barang atau jasa yang diproduksi tempatnya bekerja', 'Jenis tugas, keahlian, dan fungsi pekerjaan perorangan di tempat kerja', 'Skala modal usaha dan legalitas hukum tempatnya bekerja', 'Tingkat pendidikan formal tertinggi yang berhasil ditamatkan', 'B', 'Klasifikasi Baku Jabatan Indonesia (KBJI) adalah standardisasi resmi yang disusun oleh BPS (bersama Kementerian Ketenagakerjaan) yang merujuk pada standar internasional International Standard Classification of Occupations (ISCO).\r\nFungsi utama KBJI adalah untuk mengelompokkan jabatan/pekerjaan perorangan berdasarkan kesamaan jenis tugas yang dilakukan, tingkat keahlian (skill level), serta spesialisasi keahlian (skill specialisation) yang dibutuhkan untuk menjalankan pekerjaan tersebut (misalnya: kelompok manajer, profesional, teknisi, tenaga usaha jasa, hingga pekerja kasar).', 10);
INSERT INTO `soal` (`id`, `kategori_id`, `level`, `pertanyaan`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `jawaban`, `pembahasan`, `xp`) VALUES
(240, 3, 'Sedang', 'Mengapa data inflasi nasional yang dirilis BPS pada awal bulan sering kali berbeda atau tidak bisa langsung dijumlahkan begitu saja dari inflasi kota-kota penyusunnya?', 'Karena setiap kota memiliki nilai penimbang (bobot nilai konsumsi) yang berbeda berdasarkan hasil Survei Biaya Hidup (SBH)', 'Karena undang-undang melarang penggabungan data daerah untuk menjaga kerahasiaan daerah', 'Karena BPS menggunakan metode sampel acak yang tidak saling berhubungan antar kota', 'Karena inflasi nasional murni dihitung dari harga barang di Ibu Kota Negara saja', 'A', 'Angka inflasi nasional tidak bisa dihitung dengan cara merata-ratakan atau menjumlahkan langsung angka inflasi dari seluruh kota Indeks Harga Konsumen (IHK) begitu saja. Hal ini disebabkan karena setiap kota memiliki andil dan volume ekonomi yang berbeda terhadap potret pengeluaran masyarakat Indonesia secara keseluruhan.', 10),
(241, 1, 'Mudah', 'Selisih antara nilai tertinggi dan nilai terendah dalam suatu data disebut ...', 'Jangkauan (Range)', 'Simpangan Baku', 'Kuartil', 'Median', 'A', 'Dalam statistika deskriptif, Jangkauan (Range) atau rentang adalah ukuran penyebaran data yang paling sederhana. Nilai jangkauan diperoleh cukup dengan mencari selisih antara nilai pengamatan tertinggi (maksimum) dan nilai pengamatan terendah (minimum) di dalam suatu kumpulan data.\r\n       Jangkauan (Range) = Xmaks - X min', 10),
(242, 1, 'Mudah', 'Bagian kecil dari populasi yang diambil untuk mewakili seluruh objek penelitian disebut ...', 'Sampel', 'Paramter', 'Sensus', 'Variabel', 'A', 'Dalam statistika dan metodologi penelitian, Sampel didefinisikan sebagai bagian kecil dari anggota populasi yang diambil berdasarkan prosedur atau teknik sampling tertentu guna mewakili seluruh objek penelitian. Karena memiliki karakteristik yang sama dengan populasinya, hasil analisis dari sampel ini nantinya dapat digunakan untuk menarik kesimpulan yang berlaku bagi seluruh populasi (generalisasi).', 10),
(243, 1, 'Mudah', 'Data mengenai jenis kelamin (Laki-laki dan Perempuan) merupakan contoh dari skala pengukuran ...', 'Nominal', 'Ordinal', 'Interval', 'Rasio', 'A', 'Dalam statistika, terdapat empat tingkat atau skala pengukuran data. Data mengenai jenis kelamin (Laki-laki dan Perempuan) dikategorikan ke dalam Skala Nominal.', 10),
(244, 1, 'Mudah', 'Nilai kuartil kedua (Q₂) dalam statistika nilainya selalu sama dengan nilai ...', 'Modus', 'Mean', 'Median', 'Jangkauan', 'C', 'Kuartil adalah ukuran letak yang membagi sekumpulan data yang telah diurutkan menjadi empat bagian yang sama banyak, yang dibatasi oleh tiga nilai pembatas yaitu Kuartil Bawah (Q1), Kuartil Tengah (Q2), dan Kuartil Atas (Q3).Kuartil Kedua (Q2) membatasi 50% data di bagian bawah dan 50% data di bagian atas. \r\nMedian didefinisikan sebagai nilai tengah yang membagi tepat 50% data setelah data tersebut diurutkan dari yang terkecil hingga terbesar.', 10),
(245, 1, 'Mudah', 'Grafik berbentuk lingkaran yang dibagi menjadi beberapa sektor untuk menunjukkan proporsi bagian disebut ...', 'Histogram', 'Diagram Batang', 'Diagram Lingkaran (Pie Chart)', 'Poligon Frekuensi', 'C', 'Diagram Lingkaran (Pie Chart) adalah jenis visualisasi grafik berupa satu lingkaran penuh yang dibagi menjadi beberapa sektor/irisan. Setiap sektor mewakili proporsi atau persentase dari keseluruhan kumpulan data. Ukuran sudut pusat dan luas masing-masing sektor dibuat sebanding dengan nilai atau kuantitas dari kategori data yang diwakilinya. Total dari keseluruhan sektor di dalam satu lingkaran penuh tersebut wajib bernilai 100% atau 360 derajat.', 10),
(246, 1, 'Mudah', 'Berapakah jumlah seluruh nilai data jika diketahui mean = 8 dan banyak data = 5?', '20', '30', '40', '50', 'C', 'Dalam statistika dasar, rata-rata hitung (mean) diperoleh dari hasil pembagian antara jumlah seluruh nilai data dengan banyaknya data yang diteliti. Rumus matematika umumnya adalah : Mean (m) = Jumlah Seluruh Nilai Data / Banyak Data (n)\r\nUntuk mencari jumlah seluruh nilai data, kita tinggal membalikkan rumus tersebut menjadi operasi perkalian antara nilai mean dengan banyaknya data : \r\nJumlah Seluruh Nilai Data = Mean x Banyak Data = 8 x 5 = 40', 10),
(247, 1, 'Mudah', 'Metode pengumpulan data populasi di mana setiap anggota populasi tanpa kecuali dicatat atau diteliti disebut ...', 'Survei Sampel', 'Sensus', 'Studi Kasus', 'Eksperimen', 'B', 'Sensus adalah metode pengumpulan data di mana seluruh elemen atau setiap anggota populasi tanpa kecuali dicatat, didata, dan diteliti secara menyeluruh. Karakteristik data yang dihasilkan dari sensus disebut sebagai nilai parameter populasi.', 10),
(248, 1, 'Mudah', 'Jika suatu data memiliki jangkauan sama dengan nol (0), maka hal tersebut berarti ...', 'Data tersebut tidak memiliki modus', 'Seluruh nilai data di dalam kelompok tersebut sama besar', 'Rata-rata data tersebut pasti bernilai nol', 'Jumlah sampel data sangat banyak', 'B', 'Jangkauan (Range) dihitung dengan mencari selisih antara nilai tertinggi (maksimum) dan nilai terendah (minimum) di dalam suatu kumpulan data. Rumusnya adalah :\r\nJangkauan = Xmaks - Xmin\r\n\r\nJika diketahui nilai jangkauannya sama dengan nol (0), maka persamaannya menjadi : \r\n0 = Xmaks - Xmin\r\nXmaks = Xmin', 10),
(249, 1, 'Mudah', 'Contoh data kontinu dalam kehidupan sehari-hari yang diperoleh dari hasil pengukuran adalah ...', 'Jumlah anak dalam satu rumah tangga', 'Berat badan siswa kelas 6 SD', 'Jumlah mobil di area parkir', 'Banyaknya buku di perpustakaan', 'B', 'Data Kontinu => Data yang diperoleh dari hasil pengukuran (measuring). Nilainya berada dalam rentang atau interval tertentu dan bisa berbentuk bilangan pecahan atau desimal (misalnya: 35,5 kg, 42,8 kg) tergantung tingkat ketelitian alat ukur. Contohnya adalah berat badan, tinggi badan, suhu, dan waktu.', 10),
(250, 1, 'Mudah', 'Pada skala suhu Celsius, nilai 0°C tidak berarti ketiadaan suhu (melainkan titik beku air). Oleh karena itu, suhu termasuk dalam skala pengukuran ...', 'Nominal', 'Ordinal', 'Interval', 'Rasio', 'C', 'Suhu dalam skala Celsius merupakan contoh klasik dari Skala Interval. Karakteristik utama dari skala interval yang membedakannya dengan skala rasio adalah tidak memiliki nilai nol mutlak.\r\nArtinya, angka 0°C bukan berarti \"tidak ada suhu sama sekali\" atau ketiadaan materi, melainkan hanyalah sebuah titik acuan yang disepakati (titik beku air). Karena tidak memiliki nilai nol mutlak, kita tidak bisa melakukan operasi perkalian atau perbandingan rasio pada skala ini (contoh: suhu 40°C tidak bisa dikatakan dua kali lebih panas dari suhu 20°C).', 10),
(251, 1, 'Mudah', 'Jika median dari data terurut: 4, 5, x, 8, 9 adalah 7, maka nilai x adalah ...', '6', '7', '7,5', '8', 'B', 'Pada soal, diketahui data sudah dalam keadaan terurut : 4, 5, x, 8, 9\r\nLangkah menentukan nilai x adalah sebagai berikut :\r\n1. Hitung Banyak Data (n) : Jumlah data ada 5 (ganjil).\r\n2. Cari Letak Median : Untuk jumlah data ganjil, posisi median berada tepat di tengah, yaitu pada data ke-3.\r\n    Letak Median = Data ke- (5 + 1) / (2) = Data ke-3\r\n3. Tentukan Nilai x :  Berdasarkan urutan data tersebut, data ke-3 adalah variabel x. Karena diketahui nilai mediannya adalah 7, maka otomatis nilai dari : x = 7\r\n\r\nJika x diganti dengan angka 7, urutan data menjadi 4, 5, 7, 8, 9, dan nilai tengahnya terbukti adalah 7.', 10),
(252, 1, 'Mudah', 'Kuesioner yang disebarkan kepada responden merupakan instrumen yang digunakan untuk mengumpulkan data ...', 'Sekunder', 'Tersier', 'Primer', 'Riwayat', 'C', 'Data Primer => Data mentah yang dikumpulkan secara langsung dari sumber pertama (responden) oleh peneliti untuk tujuan spesifik penelitiannya. Kuesioner (angket), wawancara langsung, observasi lapangan, dan eksperimen laboratorium merupakan instrumen utama yang digunakan untuk mendapatkan data primer.', 10),
(253, 1, 'Mudah', 'Manakah di antara pilihan berikut yang merupakan visualisasi terbaik jika kita ingin melihat tren perkembangan suatu data dari waktu ke waktu (secara berkala)?', 'Diagram Lingkaran', 'Diagram Garis', 'Histogram', 'Diagram Batang Komponen', 'B', 'Diagram Garis (Line Chart) adalah jenis visualisasi terbaik untuk menampilkan data deret waktu (time series data). Grafik ini menghubungkan titik-titik data menggunakan garis lurus secara berurutan, sehingga sangat efektif untuk memperlihatkan :\r\n1. Tren perkembangan : Apakah suatu data cenderung naik, turun, atau stabil dari waktu ke waktu.\r\n2. Fluktuasi berkala : Melihat pola musiman atau perubahan tren pada periode waktu tertentu (misalnya data inflasi bulanan atau pertumbuhan ekonomi tahunan).', 10),
(254, 1, 'Mudah', 'Diketahui data tunggal : 8, 3, 5, 4, 8, 9, 2. \r\nJika data tersebut diurutkan dari yang terkecil, maka nilai data yang berada pada urutan kelima adalah ...', '5', '6', '7', '8', 'D', 'Data acak asli : 8, 3, 5, 4, 8, 9, 2\r\nProses pengurutan :\r\na. Urutan ke-1 : 2\r\nb. Urutan ke-2 : 3\r\nc. Urutan ke-3 : 4\r\nd. Urutan ke-4 : 5\r\ne. Urutan ke-5 : 8\r\nf. Urutan ke-6 : 8\r\ng. Urutan ke-7 : 9\r\n\r\nSetelah diurutkan secara rapi, rangkaian datanya menjadi : 2, 3, 4, 5, 8, 8, 9. \r\nAngka yang menempati posisi atau urutan kelima secara tepat adalah bilangan 8.', 10),
(255, 1, 'Mudah', 'Manakah di antara data berikut yang memiliki nilai modus sebesar 6?', '4, 5, 6, 7, 8', '6, 6, 7, 7, 8, 8', '5, 6, 6, 6, 7, 8', '6, 7, 8, 9, 10', 'C', 'Modus adalah nilai yang paling sering muncul atau memiliki frekuensi tertinggi di dalam suatu kumpulan data.\r\n5, 6, 6, 6, 7, 8 => Angka 6 muncul sebanyak 3 kali, sedangkan angka lainnya hanya muncul 1 kali. Karena angka 6 menjadi nilai yang paling dominan dan sering muncul, maka modusnya tunggal sebesar 6', 10),
(256, 1, 'Mudah', 'Seseorang ingin mengetahui tinggi badan rata-rata siswa di sebuah sekolah. Untuk menghemat waktu, ia hanya mengukur tinggi badan 30 siswa yang dipilih secara acak. Dalam statistika, seluruh siswa di sekolah tersebut dinamakan ...', 'Sampel', 'Populasi', 'Anggota', 'Parameter', 'B', 'Populasi =>Merupakan keseluruhan atau totalitas objek yang memiliki karakteristik tertentu dan menjadi target utama pengamatan atau penelitian (dalam hal ini, seluruh siswa di sekolah tersebut).', 10),
(257, 1, 'Mudah', 'Data yang disajikan dalam bentuk kategori berupa kata-kata atau kualitas (bukan angka hasil berhitung), seperti \"Mata Pencaharian: Petani, Nelayan, PNS\", termasuk jenis data ...', 'Kuantitatif', 'Kualitatif', 'Kontinu', 'Distrit', 'B', 'Data Kualitatif (Kategorik) =>Data yang disajikan dalam bentuk kata-kata, atribut, atau kualitas yang menunjukkan karakteristik tertentu dan bukan berupa angka hasil perhitungan. Data ini hanya berfungsi sebagai pelabelan atau pengelompokan ke dalam kategori-kategori spesifik. Contohnya adalah mata pencaharian (Petani, Nelayan, PNS), jenis kelamin, warna mata, atau suku bangsa.', 10),
(258, 1, 'Mudah', 'Berapakah nilai jangkauan (range) dari data : 45, 50, 55, 60, 65, 70?', '10', '15', '20', '25', 'D', 'Jangkauan (Range) dihitung dengan cara mencari selisih antara nilai tertinggi (maksimum) dan nilai terendah (minimum) di dalam suatu kumpulan data.\r\nDari data tunggal yang diberikan : 45, 50, 55, 60, 65, 70\r\n- Nilai tertinggi (Xmaks) = 70\r\n- Nilai terendah (Xmin) = 45\r\n\r\nRumus jangkauan : Jangkauan = Xmaks - Xmin = 70 - 45 = 25', 10),
(259, 1, 'Mudah', 'Jika Anda membaca tabel frekuensi dan melihat bahwa nilai 80 memiliki frekuensi 5, hal itu berarti ...', 'Nilai rata-rata kelas adalah 80', 'Ada 5 orang siswa yang mendapatkan nilai 80', 'Nilai tertinggi di kelas tersebut adalah 80', 'Nilai kelulusan minimum adalah 80', 'B', 'Dalam statistika, sebuah tabel distribusi frekuensi digunakan untuk menyederhanakan dan menyusun data agar mudah dibaca.\r\n- Kolom Nilai menunjukkan variasi angka atau skor yang muncul dari objek yang diteliti.\r\n- Kolom Frekuensi menunjukkan seberapa banyak atau seberapa sering nilai tersebut muncul/terulang di dalam kumpulan data.\r\n\r\nJadi, jika nilai 80 memiliki frekuensi 5, hal itu secara harfiah berarti angka 80 tersebut muncul sebanyak 5 kali dalam pencatatan data (dalam konteks sekolah, artinya ada 5 orang siswa yang memperoleh nilai 80).', 10),
(260, 1, 'Mudah', 'Pengumpulan data tinggi badan seluruh siswa di satu kelas tanpa terkecuali oleh wali kelas untuk keperluan pengisian rapor disebut kegiatan ...', 'Sampling', 'Sensus', 'Survei', 'Eksperimen', 'B', 'Kegiatan mengumpulkan data tinggi badan seluruh siswa di satu kelas tanpa terkecuali dikategorikan sebagai Sensus.\r\nDalam statistika, metode sensus adalah proses pengumpulan data di mana peneliti mencatat, mendata, dan memeriksa setiap elemen atau seluruh anggota populasi yang menjadi target penelitian. Karena target penelitian wali kelas adalah populasi satu kelas tersebut dan semua siswa diukur tanpa ada yang dilewati, maka kegiatan ini memenuhi syarat definisi sensus.', 10),
(261, 1, 'Sedang', 'Nilai rata-rata ujian matematika dari sebuah kelas yang berisi 29 siswa adalah 80. Jika nilai ujian dari seorang siswa yang bernama Budi digabungkan, nilai rata-rata ujian matematika di kelas tersebut meningkat menjadi 80,5. Berapakah nilai ujian matematika yang diperoleh Budi?', '85', '90', '95', '100', 'C', 'Langkah 1 : Hitung total nilai dari 29 siswa sebelum Budi bergabung.\r\n=> Total Nilai Awal = 29 x 80 = 2.320\r\n\r\nLangkah 2 : Hitung total nilai setelah Budi bergabung (jumlah siswa menjadi 30 orang).\r\n=> Total Nilai Baru = 30 x 80,5 = 2.415\r\n\r\nLangkah 3 : Cari nilai Budi dengan menghitung selisih antara total nilai baru dan total nilai awal.\r\n=> Nilai Budi = Total Nilai Baru - Total Nilai Awal= 2.415 - 2.320 = 95', 10),
(262, 3, 'Sulit', 'Dalam penghitungan Indeks Pembangunan Manusia (IPM) metode baru, BPS menggunakan rata-rata geometrik (geometric mean) untuk menggabungkan ketiga dimensi penyusunnya, menggantikan metode rata-rata aritmatika (arithmetic mean) yang digunakan pada metode lama. Mengapa BPS melakukan perubahan formula ini?', 'Rata-rata geometrik lebih mudah dihitung secara manual oleh petugas lapangan', 'Rata-rata geometrik memastikan bahwa capaian rendah di satu dimensi tidak bisa ditutupi secara instan oleh capaian tinggi di dimensi lain (efek substitusi sempurna)', 'Formula rata-rata geometrik secara otomatis menaikkan nilai rata-rata nasional agar terlihat lebih tinggi', 'Karena metode rata-rata aritmatika dilarang oleh standar baku PBB sejak tahun 2020', 'A', 'Sejak tahun 2014, BPS memperbarui metodologi penghitungan Indeks Pembangunan Manusia (IPM). Alasan utama penggantian rata-rata aritmatika menjadi rata-rata geometrik (geometric mean) adalah untuk mengatasi kelemahan sifat kompensasi antar-dimensi :\r\n- Kelemahan Rata-Rata Aritmatika : Pada metode lama, jika suatu daerah memiliki nilai dimensi ekonomi (pendapatan) yang sangat tinggi, nilai tersebut dapat \r\n  mendongkrak total skor IPM secara signifikan meskipun nilai dimensi kesehatannya sangat buruk. Hal ini memicu bias karena seolah-olah mengizinkan terjadinya \r\n  substitusi sempurna (satu dimensi menutupi dimensi lain).\r\n- Kelebihan Rata-Rata Geometrik : Metode baru ini memberikan sinyal bahwa ketiga dimensi IPM sama pentingnya dan tidak bisa saling menggantikan. Dengan rata-\r\n  rata geometrik, jika ada satu saja dimensi yang nilainya sangat rendah atau timpang, maka nilai total IPM daerah tersebut akan langsung turun drastis secara \r\n  proporsional.', 10),
(263, 2, 'Sulit', 'Dalam melakukan Survei Sosial Ekonomi Nasional (Susenas), BPS menerapkan teknik sampling dua tahap (Two-Stage Sampling). Aktivitas penarikan sampel yang dilakukan pada Tahap Pertama dan Tahap Kedua secara berurutan adalah ...', 'Tahap 1 : Memilih Kabupaten; Tahap 2 : Memilih Kecamatan', 'Tahap 1 : Memilih Blok Sensus (BS); Tahap 2 : Memilih Rumah Tangga (Ruta) di dalam Blok Sensus terpilih', 'Tahap 1 : Memilih Rumah Tangga; Tahap 2 : Memilih Anggota Rumah Tangga secara acak', 'Tahap 1 : Memilih Provinsi; Tahap 2 : Memilih Perusahaan/Pelaku Usaha Dagang', 'B', 'Dalam pelaksanaan Survei Sosial Ekonomi Nasional (Susenas), Badan Pusat Statistik (BPS) menggunakan desain penarikan sampel probabilitas yang disebut Two-Stage Stratified Sampling (Sampling Dua Tahap Berstrata). Tahapan penarikan sampelnya dilakukan secara berurutan sebagai berikut :\r\n1. Tahap Pertama (Stage 1) : BPS memilih sejumlah Blok Sensus (BS) secara acak dari Kerangka Sampel Induk (Master Sampling Frame) yang disusun berdasarkan data \r\n    sensus terbaru. Pemilihan BS ini dilakukan dengan metode Probability Proportional to Size (PPS).\r\n2. Tahap Kedua (Stage 2): Petugas BPS terlebih dahulu melakukan pendaftaran (listing) semua rumah tangga di dalam Blok Sensus yang terpilih pada tahap pertama.  \r\n    Dari daftar tersebut, BPS kemudian memilih sejumlah Rumah Tangga (Ruta) secara acak (biasanya menggunakan metode Systematic Sampling) untuk dijadikan \r\n    responden akhir yang akan diwawancarai.', 10),
(264, 1, 'Sedang', 'Mengapa penyajian data dalam bentuk grafik lebih mudah dipahami dibandingkan daftar angka?', 'Karena grafik memiliki banyak warna', 'Karena grafik selalu lebih pendek', 'Karena grafik mempermudah melihat pola, perbandingan, dan tren data', 'Karena grafik tidak memerlukan data', 'C', 'Grafik merupakan alat visualisasi data yang dirancang untuk menerjemahkan kumpulan angka yang rumit menjadi bentuk visual. Ketika data disajikan dalam bentuk grafik (seperti grafik batang atau grafik garis), mata manusia dapat dengan cepat menangkap naik-turunnya data (tren), perbedaan ukuran antar-kategori (perbandingan), serta kecenderungan tertentu (pola) tanpa harus membaca dan menghitung angka satu per satu.', 10),
(265, 2, 'Sedang', 'Kabupaten A memiliki angka kemiskinan lebih tinggi daripada Kabupaten B menurut data BPS. Informasi tersebut dapat digunakan untuk ...', 'Menentukan lokasi prioritas bantuan sosial', 'Menentukan juara lomba', 'Menentukan harga emas', 'Menentukan nilai ujian', 'A', 'Data Badan Pusat Statistik (BPS) mengenai tingkat kemiskinan daerah berfungsi sebagai indikator capaian pembangunan dan dasar pengambilan kebijakan pemerintah. Ketika diketahui Kabupaten A memiliki angka kemiskinan yang lebih tinggi daripada Kabupaten B, pemerintah dan lembaga terkait akan menggunakan informasi tersebut untuk mengalokasikan anggaran, merancang program pengentasan kemiskinan, serta mengarahkan bantuan sosial secara tepat sasaran ke wilayah yang paling membutuhkan (skala prioritas).', 10),
(266, 3, 'Sulit', 'Dalam survei BPS seperti Susenas, metode penarikan sampel yang digunakan umumnya bersifat multi-tahap (Multi-stage Sampling). Jika tahap pertama memilih Blok Sensus (BS) menggunakan metode PPS (Probability Proportional to Size), ukuran apa yang paling sering digunakan sebagai \'Size\' pada tahap tersebut?', 'Jumlah muatan rumah tangga berdasarkan hasil Regsosek terbaru', 'Jumlah muatan rumah tangga berdasarkan hasil Sensus Penduduk terdahulu', 'Luas wilayah geografis dari Blok Sensus tersebut', 'Jumlah target sampel yang harus dipenuhi oleh Petugas Cacah Lapangan (PCL)', 'B', 'Dalam metode penarikan sampel acak dua tahap berstrata (Stratified Two-Stage Sampling) yang umum diterapkan oleh BPS, tahap pertama melibatkan pemilihan Blok Sensus (BS) dengan metode PPS (Probability Proportional to Size).\r\nUkuran atau \"Size\" yang digunakan sebagai dasar peluang terpilihnya suatu Blok Sensus adalah jumlah muatan rumah tangga hasil Sensus Penduduk (SP) terdahulu (atau pemutakhiran kerangka sampel induk/SP-Master). Blok Sensus yang memiliki jumlah rumah tangga lebih banyak akan memiliki probabilitas terpilih yang lebih besar.', 10),
(267, 2, 'Sulit', 'Seorang Petugas Lapangan (PCL) menemukan sebuah bangunan fisik yang dihuni oleh sekelompok orang yang memasak dari satu dapur yang sama, dipimpin oleh seorang kepala keluarga. Namun, salah satu anggota ruangan tersebut membayar sewa kamar secara bulanan dan makan secara terpisah di luar. Dalam konsep BPS, kamar sewaan tersebut dikategorikan sebagai ...', 'Satu Rumah Tangga Biasa yang menyatu dengan pemilik rumah', 'Satu Rumah Tangga Khusus', 'Satu Rumah Tangga Biasa yang berdiri sendiri (pisah dari pemilik rumah)', 'Anggota Rumah Tangga (ART) menumpang bebas', 'C', 'Berdasarkan konsep dan definisi Badan Pusat Statistik (BPS), syarat utama sebuah kelompok/individu dianggap sebagai Satu Rumah Tangga Biasa adalah mereka mendiami sebagian atau seluruh bangunan fisik dan biasanaya makan bersama dari satu dapur.\r\nKarena salah satu penyewa kamar tersebut membayar sewa secara bulanan dan makan terpisah (mengurus kebutuhan makannya sendiri), maka pengelolaan ekonominya sudah terpisah dari keluarga utama/pemilik rumah. Meskipun berada di bawah satu atap bangunan fisik, kamar sewaan tersebut dihitung sebagai satu rumah tangga biasa tersendiri yang terpisah.', 10),
(268, 2, 'Sulit', 'Sensus Penduduk (SP) BPS menerapkan kombinasi pendekatan De Jure dan De Facto. Seseorang yang bertempat tinggal di Kota A, namun sedang melakukan perjalanan dinas atau wisata di Kota B selama 2 minggu saat hari sensus, akan dicatat sebagai penduduk ...', 'Kota B secara De Facto', 'Kota A secara De Jure', 'Dicatat di kedua kota (Kota A dan Kota B) kemudian dianulir saat cleansing data', 'Tidak dicatat di keduanya sampai dia kembali menetap lebih dari 6 bulan', 'B', 'Konsep waktu batas (cut-off) menetap yang digunakan oleh BPS dalam sensus adalah 6 bulan (atau kurang dari 6 bulan tetapi memiliki tujuan kuat untuk menetap). Karena orang tersebut hanya pergi ke Kota B selama 2 minggu untuk urusan dinas atau wisata, ia dikategorikan sebagai penduduk yang bepergian sementara. Berdasarkan standar operasional BPS, ia akan tetap dicatat di tempat tinggal asalnya yaitu Kota A secara De Jure, melalui informasi yang diberikan oleh anggota keluarga lain yang berada di rumahnya (proxy interview).', 10),
(269, 2, 'Sulit', 'Berdasarkan Undang-Undang Nomor 16 Tahun 1997 tentang Statistik, jenis statistik di Indonesia dibagi menjadi 3, yaitu Statistik Dasar, Statistik Sektoral, dan Statistik Khusus. Manakah pernyataan berikut yang mendefinisikan posisi dan kewenangan BPS secara tepat?', 'BPS menyelenggarakan Statistik Dasar, Statistik Sektoral, dan Statistik Khusus sekaligus tanpa keterlibatan instansi lain', 'BPS tidak memiliki kewenangan hukum untuk memberikan rekomendasi terhadap kegiatan statistik yang dilakukan oleh Kementerian/Lembaga', 'BPS hanya bertanggung jawab penuh atas penyelenggaraan Statistik Dasar, serta bertindak sebagai pembina dalam penyelenggaraan Statistik Sektoral yang dilakukan oleh instansi pemerintah/kementerian', 'Statistik Sektoral diselenggarakan oleh BPS, sedangkan Statistik Dasar diselenggarakan oleh lembaga swasta berskala nasional', 'C', 'Berdasarkan Undang-Undang Nomor 16 Tahun 1997 tentang Statistik, pembagian peran dalam penyelenggaraan statistik nasional diatur secara jelas untuk membangun Sistem Statistik Nasional yang terpadu :\r\n- Statistik Dasar (bersifat makro, lintas sektoral, dan skala nasional) sepenuhnya menjadi tanggung jawab BPS.\r\n- Statistik Sektoral menjadi tanggung jawab Kementerian atau Instansi Pemerintah terkait sesuai tugas pokoknya. Namun, BPS memiliki kewajiban hukum untuk \r\n   bertindak sebagai pembina dengan memberikan bimbingan, standar metodologi, dan rekomendasi kegiatan statistik kepada instansi-instansi tersebut', 10),
(270, 2, 'Sulit', 'BPS menerapkan pengamanan data tingkat tinggi melalui teknik \"Anonisasi Data Mikro\" (Anonymized Microdata) sebelum membagikannya kepada para peneliti atau publik. Mengapa prosedur ini wajib dilakukan secara hukum?', 'Menyembunyikan kesalahan lapangan yang dilakukan oleh PCL agar citra institusi tetap terjaga', 'Menyamaratakan seluruh jawaban responden menjadi satu angka rata-rata yang sama', 'Memenuhi amanat UU No. 16 Tahun 1997 yang mewajibkan BPS melindungi kerahasiaan data pribadi/identitas individu responden tanpa pengecualian', 'Untuk memangkas ukuran file data agar server BPS tidak mengalami kelebihan beban (overload) saat diunduh', 'C', 'Data mikro adalah data tingkat individu, rumah tangga, atau perusahaan yang menjadi dasar pembentukan angka statistik BPS. Sebelum disebarluaskan kepada peneliti, data ini harus melalui proses anonimisasi (penghapusan atau pengaburan identitas asli seperti nama, alamat detail, nomor NIK, hingga koordinat rumah).\r\nBerdasarkan Pasal 21 Undang-Undang Nomor 16 Tahun 1997 tentang Statistik, penyelenggara statistik wajib menjamin kerahasiaan data responden. Pelanggaran terhadap pasal kerahasiaan ini dapat dikenai sanksi pidana. Anonimisasi data mikro adalah langkah teknis wajib untuk melindungi privasi masyarakat agar identitas mereka tidak bisa dilacak kembali oleh siapa pun.', 10),
(271, 2, 'Sulit', 'Dalam pemutakhiran peta Wilkerstat, jika sebuah blok sensus mengalami pemekaran muatan secara masif hingga jumlah rumah tangganya melebihi 250 RT (Padahal standar BS adalah 80-120 RT), tindakan teknis apa yang harus dilakukan oleh tim pemetaan BPS?', 'Membiarkan blok sensus tersebut apa adanya agar histori data tahun sebelumnya tidak hilang', 'Mengubah metode survei di blok tersebut menjadi sensus lengkap secara permanen', 'Menghapus blok sensus tersebut dan menggabungkannya ke desa tetangga', 'Melakukan Splitting (pemecahan) blok sensus menjadi dua atau lebih blok sensus baru dengan batas alam/buatan yang jelas', 'D', 'Jika terjadi pertumbuhan penduduk yang masif di suatu wilayah (misalnya pembangunan perumahan baru atau apartemen) hingga muatannya melonjak drastis, tim pemetaan BPS harus melakukan prosedur Splitting (Pemecahan). Blok Sensus induk akan dipecah menjadi beberapa BS baru (misal: BS 001B, BS 001C) dengan mengikuti kaidah geografis, yaitu wajib menggunakan batas-batas fisik yang jelas di lapangan seperti jalan, sungai, atau saluran irigasi agar tidak membingungkan petugas.', 10),
(272, 3, 'Sedang', 'Konsep \"Pengangguran Terselubung\" (Disguised Unemployment) secara metodologis diukur oleh BPS melalui pendekatan jam kerja. Seseorang dikategorikan masuk ke dalam kelompok ini jika ...', 'Bekerja aktif tetapi tidak memiliki kontrak kerja resmi (sektor informal)', 'Bekerja dengan jam kerja rendah (kurang dari 35 jam seminggu) dan masih mencari pekerjaan atau masih bersedia menerima pekerjaan tambahan', 'Memiliki gelar sarjana namun bekerja sebagai staf administrasi biasa', 'Sedang mogok kerja karena menuntut kenaikan upah', 'A', 'BPS menggunakan ukuran jam kerja normal yaitu 35 jam seminggu. Seseorang dikategorikan sebagai setengah penganggur (terpaksa/terselubung) jika waktu kerjanya di bawah 35 jam dan secara aktif masih mencari pekerjaan atau siap menerima pekerjaan tambahan karena kapasitas tenaganya belum termanfaatkan secara optimal.', 10),
(273, 3, 'Sedang', 'Mengapa dalam menghitung Garis Kemiskinan (GK), BPS memisahkan antara Garis Kemiskinan Makanan (GKM) dan Garis Kemiskinan Non-Makanan (GKNM)?', 'GKM hanya berlaku di wilayah pedesaan, sedangkan GKNM hanya berlaku di wilayah perkotaan', 'GKNM nilainya selalu konstan di seluruh provinsi di Indonesia, tidak seperti GKM', 'Karena GKM dihitung menggunakan standar pengeluaran minimum, sedangkan GKNM dihitung berdasarkan jumlah aset fisik yang dimiliki', 'Untuk memastikan kebutuhan kalori setara 2.100 kilokalori per kapita per hari terpenuhi (pada GKM), sementara GKNM mengakomodasi kebutuhan dasar minimum seperti perumahan, sandang, dan pendidikan', 'D', 'Pemisahan ini dilakukan karena kedua komponen memiliki standar pemenuhan kebutuhan yang sangat berbeda secara metodologis.\r\n- GKM digunakan untuk mengukur nilai pengeluaran makanan minimum yang disetarakan dengan kecukupan energi 2.100 kilokalori per kapita per hari (diwakili oleh \r\n   paket komoditas makanan dasar).\r\n- GKNM digunakan untuk mengukur kebutuhan minimum non-makanan (seperti biaya sewa rumah, pakaian, transportasi, pendidikan, dan kesehatan).', 10),
(274, 3, 'Sulit', 'Jika angka Inflasi Year-on-Year (YoY) pada bulan Juni 2026 tercatat sebesar 3,5%, hal ini berarti terjadi ...', 'Kenaikan harga barang dan jasa pada bulan Juni 2026 sebesar 3,5% dibandingkan dengan bulan Mei 2026', 'Kenaikan harga saham gabungan di bursa efek sebesar 3,5%', 'Kenaikan harga barang dan jasa pada bulan Juni 2026 sebesar 3,5% dibandingkan dengan bulan Juni 2025', 'Penurunan daya beli masyarakat sebesar 3,5% dalam satu bulan terakhir', 'C', 'Metode penghitungan inflasi di Badan Pusat Statistik (BPS) mengacu pada perubahan Indeks Harga Konsumen (IHK). Istilah Year-on-Year (YoY) atau tahunan secara khusus membandingkan tingkat harga pada bulan yang sama di dua tahun yang berurutan. Dengan demikian, angka inflasi YoY sebesar 3,5% pada Juni 2026 mencerminkan rata-rata kenaikan harga barang dan jasa jika dibandingkan langsung dengan kondisi pada Juni 2025.', 10),
(275, 3, 'Sulit', 'Dalam pengujian hipotesis hasil survei pertanian, apa yang dimaksud dengan Kesalahan Tipe I (Type I Error) atau nilai Alfa (α)?', 'Menolak hipotesis nol (H₀) padahal hipotesis nol tersebut sebenarnya benar', 'Menerima hipotesis nol (H₀) padahal hipotesis nol tersebut sebenarnya salah', 'Kesalahan menghitung jumlah produksi padi akibat timbangan rusak', 'Bias yang muncul karena responden berbohong mengenai luas lahannya', 'A', 'Kesalahan Tipe I (Type I Error) atau sering disebut tingkat signifikansi (Alfa) terjadi ketika kita mengambil keputusan untuk menolak H0, padahal di dunia nyata (populasi sebenarnya) kondisi H0 tersebut adalah benar/sah. Dalam survei pertanian, contohnya adalah menyimpulkan bahwa sebuah pupuk baru berhasil meningkatkan hasil panen (menolak H0), padahal kenyataannya pupuk tersebut tidak memberikan efek apa-apa (H0 benar).', 10),
(276, 2, 'Sulit', 'BPS merilis \"Metadata Statistik\" bersamaan dengan rilis angka indikator. Apa fungsi utama dari Metadata tersebut dalam konsep Satu Data Indonesia?', 'Berisi daftar nama dan alamat lengkap responden yang disurvei', 'Menghitung otomatis nilai bonus tunai untuk petugas lapangan', 'Memberikan informasi terstruktur mengenai definisi, konsep, metodologi, dan tujuan pengumpulan data agar tidak terjadi salah interpretasi oleh pengguna data', 'Sebagai dokumen rahasia negara yang hanya boleh dibaca oleh Kepala BPS', 'C', 'Metadata menyediakan dokumentasi resmi yang menjelaskan bagaimana sebuah angka statistik diproduksi. Dokumen ini memuat definisi variabel, konsep dasar, cakupan wilayah, metode penarikan sampel, hingga rumus kalkulasi yang digunakan. Adanya metadata memastikan instansi pemerintah lain, peneliti, dan publik memiliki pemahaman yang seragam dan tidak salah menafsirkan arti dari angka indikator tersebut.', 10),
(277, 2, 'Sulit', 'Sensus Ekonomi (SE) yang diselenggarakan oleh BPS setiap sepuluh tahun sekali (pada tahun berakhiran angka 6) bertujuan untuk memetakan ...', 'Seluruh usaha/perusahaan non-pertanian yang beroperasi di wilayah Indonesia', 'Jumlah hewan ternak dan kepemilikan lahan sawah milik petani', 'Tingkat pendapatan dan pengeluaran seluruh rumah tangga miskin', 'Distribusi persebaran pegawai negeri sipil di tingkat pusat', 'A', 'Sensus Ekonomi (SE) yang diadakan oleh Badan Pusat Statistik (BPS) pada setiap tahun berakhiran angka 6 (seperti SE2026 saat ini) dirancang untuk memotret peta perekonomian nasional secara menyeluruh.\r\nCakupan utama Sensus Ekonomi adalah seluruh sektor usaha/perusahaan non-pertanian di Indonesia, baik skala makro (perusahaan besar) maupun mikro (UMKM, usaha online, pedagang kaki lima), serta bersifat formal maupun informal. Hasil sensus ini menyajikan karakteristik, struktur, dan dinamika bisnis di luar sektor pertanian.', 10),
(278, 3, 'Sedang', 'Jika Angka Melek Aksara (AMA) di suatu wilayah mencapai 96%, arti statistik yang paling tepat dari indikator tersebut adalah ...', 'Sebanyak 96% penduduk di wilayah tersebut sudah lulus pendidikan minimal SMA', 'Dari setiap 100 penduduk usia 15 tahun ke atas, terdapat 96 orang yang dapat membaca dan menulis kalimat sederhana', 'Sebanyak 4% penduduk di wilayah tersebut tidak mau bersekolah', 'Rata-rata lama sekolah anak-anak di daerah tersebut adalah 9,6 tahun', 'A', 'Angka Melek Aksara (AMA) atau Literacy Rate merupakan salah satu komponen penting dalam mengukur kualitas sumber daya manusia dan penyusunan Indeks Pembangunan Manusia (IPM) BPS.\r\nSecara definisi standar, AMA mengukur persentase penduduk usia 15 tahun ke atas yang memiliki kemampuan untuk membaca dan menulis kalimat sederhana dalam kehidupan sehari-hari (baik huruf Latin, Arab, Braille, atau huruf lainnya). Jika angkanya 96%, artinya secara proporsional ada 96 orang melek huruf dari setiap 100 orang di kelompok usia tersebut.', 10),
(279, 3, 'Sulit', 'Suatu daerah memiliki Angka Beban Ketergantungan (Dependency Ratio) sebesar 50%. Interpretasi yang benar mengenai struktur demografi daerah tersebut adalah ...', 'Setiap 100 penduduk usia produktif menanggung 50 penduduk usia non-produkti', 'Setengah dari total populasi di daerah tersebut berstatus sebagai pengangguran', 'Jumlah penduduk usia tua (65 tahun ke atas) sama banyak dengan jumlah anak-anak (0-14 tahun)', 'Pendapatan daerah tersebut 50% bersumber dari bantuan pemerintah pusat', 'A', 'Pengali konstanta sebesar 100 berarti indikator ini menyetarakan basis perbandingannya per 100 penduduk usia produktif. Jika nilainya 50%, artinya secara rata-rata setiap 100 orang yang berada di rentang usia kerja (15-64 tahun) memiliki beban ekonomi untuk menanggung 50 orang usia tidak produktif (gabungan anak-anak dan lansia). Angka ini tergolong rendah dan sering kali menjadi penanda sebuah wilayah sedang menikmati bonus demografi.', 10),
(280, 3, 'Sedang', 'Indikator Rata-rata Lama Sekolah (RLS) dan Harapan Lama Sekolah (HLS) digunakan untuk menyusun Indeks Pembangunan Manusia (IPM). Jika suatu kabupaten memiliki nilai HLS sebesar 13 tahun, apa maknanya?', 'Anak-anak usia 7 tahun yang mulai bersekolah di kabupaten tersebut berpeluang menempuh pendidikan hingga diploma satu (D1) atau kuliah tahun pertama', 'Rata-rata penduduk usia 25 tahun ke atas di wilayah tersebut sudah menempuh pendidikan selama 13 tahun', 'Pemerintah daerah menjamin fasilitas beasiswa kuliah gratis selama 13 tahun', 'Seluruh anak usia sekolah dipastikan putus sekolah saat menginjak tahun ke-13', 'A', 'Secara definisi metodologis, HLS didefinisikan sebagai lamanya tahun pendidikan formal yang diharapkan akan dinikmati oleh anak pada umur tertentu (biasanya umur 7 tahun) di masa depan. Angka HLS sebesar 13 tahun menggambarkan bahwa anak-anak usia 7 tahun di kabupaten tersebut secara rata-rata memiliki peluang/prospek untuk mengenyam bangku sekolah selama 13 tahun. Dalam struktur pendidikan di Indonesia, 13 tahun setara dengan lulus SD (6 tahun) + lulus SMP (3 tahun) + lulus SMA (3 tahun) + 1 tahun di perguruan tinggi (kuliah semester awal/Diploma 1).', 10),
(281, 3, 'Sedang', 'Dalam menentukan Garis Kemiskinan (GK), BPS menggunakan pendekatan pemenuhan kebutuhan dasar (Basic Needs Approach). Komponen terbesar yang menyumbang nilai Garis Kemiskinan di Indonesia umumnya berasal dari ...', 'Garis Kemiskinan Non-Makanan (seperti perumahan dan pakaian)', 'Garis Kemiskinan Makanan (setara 2.100 kilokalori per kapita per hari)', 'Biaya transportasi umum dan internet bulanan', 'Biaya jaminan kesehatan dan premi asuransi', 'B', 'Garis Kemiskinan Makanan (GKM) secara konsisten memberikan sumbangan yang sangat besar, yaitu berkisar antara 74% hingga 75% terhadap total nilai Garis Kemiskinan (GK) nasional. Hal ini menunjukkan bahwa pemenuhan kebutuhan kalori dasar (pangan) masih menjadi komponen pengeluaran paling utama dan sensitif bagi masyarakat di batas garis kemiskinan, dengan beras dan rokok kretek filter sebagai komoditas penyumbang nilai tertinggi.', 10),
(282, 3, 'Sulit', 'Koefisien Gini (Gini Ratio) digunakan untuk mengukur tingkat ketimpangan pengeluaran penduduk. Jika nilai Gini Ratio suatu provinsi menurun dari 0,38 menjadi 0,35, hal ini menunjukkan bahwa ...', 'Distribusi pengeluaran di masyarakat menjadi lebih merata', 'Jumlah penduduk miskin di provinsi tersebut meningkat pesat', 'Pertumbuhan ekonomi di wilayah tersebut mengalami stagnasi atau berhenti', 'Ketimpangan antar-penduduk menjadi semakin melebar dan parah', 'A', 'Nilai Koefisien Gini bergerak di rentang 0 hingga 1.\r\nNilai 0 berarti kemerataan sempurna (tidak ada kesenjangan sama sekali).\r\nNilai 1 berarti ketimpangan sempurna (seluruh pengeluaran hanya dikuasai satu orang/pihak).Ketika nilai Gini Ratio menurun (dari 0,38 menjadi 0,35), artinya posisi distribusi pengeluaran bergerak mendekati angka 0. Hal ini secara ekonomi menunjukkan bahwa distribusi pengeluaran di masyarakat menjadi lebih merata dan kesenjangan ekonomi mengecil.', 10),
(283, 3, 'Sulit', 'Indeks Ketimpangan Gender (IKG) atau Gender Inequality Index (GII) dihitung BPS untuk mengukur kerugian capaian pembangunan akibat ketimpangan gender. Manakah di antara indikator berikut yang menjadi penyusun dimensi Pemberdayaan (Empowerment) dalam IKG?', 'Angka Kematian Ibu (AKI) dan Angka Kelahiran Remaja (ASFR 15-19 tahun)', 'Persentase kursi di parlemen dan persentase penduduk usia 25 tahun ke atas dengan pendidikan minimal SMA/sederajat', 'Tingkat Partisipasi Angkatan Kerja (TPAK) menurut jenis kelamin', 'Rasio upah kerja formal antara laki-laki dan perempuan pada sektor industri manufaktur', 'B', 'Badan Pusat Statistik (BPS) mengadopsi kerangka kerja Gender Inequality Index (GII) dari UNDP untuk menghitung Indeks Ketimpangan Gender (IKG). Indeks ini mengukur kesenjangan antara laki-laki dan perempuan melalui tiga dimensi utama : \r\n- Dimensi Pemberdayaan (Empowerment) :Dimensi ini mengukur kekuatan representasi politik dan tingkat capaian pendidikan. Indikator pembentuknya dibagi \r\n  menurut jenis kelamin, yaitu persentase anggota legislatif/parlemen dan persentase penduduk usia 25 tahun ke atas yang berpendidikan minimal SMA ke atas.', 10),
(284, 3, 'Sulit', 'Dalam menghitung Indeks Harga Konsumen (IHK) sebagai dasar angka inflasi, BPS menggunakan formula Modified Laspeyres. Karakteristik utama dari pembobot (weight) yang digunakan dalam formula ini adalah ...', 'Menggunakan bobot nilai konsumsi komoditas dari tahun berjalan yang diperbarui setiap bulan secara dinamis', 'Menggunakan bobot nilai konsumsi komoditas dari tahun dasar yang diperoleh melalui Survei Biaya Hidup (SBH) secara periodik', 'Menggunakan rata-rata geometris antara kuantitas tahun dasar dan kuantitas tahun berjalan', 'Membuang seluruh komoditas bergejolak (volatile) dari pembobotan dasar', 'B', 'Karakteristik utama dari rumpun formula Laspeyres adalah menggunakan bobot (weight atau nilai cakupan komoditas) yang dikunci pada Tahun Dasar (\\(0\\)). Nilai penyeimbang bobot ini diperoleh secara periodik melalui Survei Biaya Hidup (SBH) yang diadakan beberapa tahun sekali (misalnya SBH 2018 atau SBH 2022). Bobot tahun dasar ini mencerminkan pola pengeluaran konsumsi masyarakat pada tahun dasar tersebut dan tidak berubah setiap bulan.', 10),
(285, 3, 'Sulit', 'Saat menghitung Produk Domestik Bruto (PDB) Atas Dasar Harga Konstan (ADHK), BPS menerapkan metode Double Deflation pada beberapa sektor tertentu. Apa yang dimaksud dengan metode Double Deflation tersebut?', 'Mendeflasikan nilai output bruto dan nilai input antara (biaya antara) secara terpisah menggunakan deflator yang sesuai, kemudian mengurangkannya untuk mendapatkan Nilai Tambah Bruto (NTB) riil', 'Mengalikan output dan input secara terpisah dengan angka inflasi umum sebelum dikurangkan', 'Membagi nilai PDB dengan indeks harga konsumen dan indeks harga perdagangan besar secara bersamaan', 'Melakukan pembersihan data outlier sebanyak dua kali pada tingkat pelaporan korporasi', 'A', 'Metode Double Deflation (Deflasi Ganda) adalah teknik paling ideal dalam statistik pendapatan nasional. Cara kerjanya adalah :\r\n- Nilai Output Bruto diubah ke harga konstan menggunakan indeks harga output yang sesuai (Dideflasikan pertama).\r\n- Nilai Input Antara / Biaya Antara (bahan baku, energi, jasa yang digunakan dalam proses produksi) juga diubah ke harga konstan menggunakan indeks harga input \r\n   yang sesuai (Dideflasikan kedua).\r\n- Nilai Tambah Bruto (NTB) riil didapatkan dengan rumus : Output Konstan - Input Konstan. Metode ini mencegah bias jika harga bahan baku naik lebih cepat daripada \r\n   harga produk jadi.', 10),
(286, 3, 'Sulit', 'Indeks Kebahagiaan BPS dihitung menggunakan metode komposit dengan menyusun tiga dimensi utama, yaitu Kepuasan Hidup (Life Satisfaction), Perasaan (Affect), dan Dimensi Eudaimonia. Apa makna esensial yang diukur secara khusus melalui dimensi Eudaimonia?', 'Tingkat kepuasan material terhadap fasilitas infrastruktur publik dan layanan kesehatan gratis', 'Frekuensi munculnya emosi positif seperti rasa senang dan ketiadaan rasa khawatir dalam kehidupan sehari-hari', 'Makna dan fungsi keterfungsian hidup psikologis seseorang, seperti kemandirian, penguasaan lingkungan, tujuan hidup, dan pengembangan diri', 'Tingkat kepatuhan warga negara terhadap norma hukum dan pembayaran pajak tepat waktu', 'C', 'Dimensi Eudaimonia (sering disebut sebagai dimensi Makna Hidup) berakar dari konsep psikologi positif. Dimensi ini tidak mengukur kesenangan sesaat atau materi, melainkan mengukur kualitas fungsi psikologis mendalam seseorang. Indikator penyusunnya meliputi kemandirian (autonomy), penguasaan lingkungan, pengembangan diri (personal growth), hubungan positif dengan orang lain, tujuan hidup (purpose in life), dan penerimaan diri.', 10);
