(1, 'cintya', 'c4240091@gmail.com', '$2y$10$QXFT0CUGBRq2jEnvVdi.VuvPybB7emhPVCn3fz924li5hAjO373QO', 'default.png', 1, 0, '2026-07-03 04:30:46'),
(4, 'alvaro', 'alvaro23@gmail.com', '$2y$10$TueC8CUh6CdWmz5TpOBelulrE18gJPCX1GcYTemyKskBAgc3eeGM.', 'avatars/lainnya-03.jpg', 1, 0, '2026-07-17 03:03:21'),
(14, 'Preview Tester', 'temp_preview_test@example.local', '$2y$10$TtEYuEOTfVvxRm0WGN1br.hzPByTALGNscXFi4RH2iuvvk0G1KSuq', 'default.png', 3, 205, '2026-07-20 03:21:17');
